const stay_out_of_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"stay-out-of","title":"Stay Out Of","koreanPronunciation":"스테이 아웃 오브","tags":["구동사","자주 쓰는 표현"],"meaning":"어떤 일이나 장소에 관여하거나 접근하지 않고 멀리 떨어져 있다...의미입니다","description":"이 표현은 특정 상황, 문제, 장소 또는 사람에게서 거리를 두거나 개입하지 않음을 나타낼 때 사용됩니다. 주로 부정적인 의미를 내포하는 상황에서 \'멀리 떨어져 있어라\' 또는 \'간섭하지 마라\'는 경고나 조언으로 쓰입니다. 물리적인 거리뿐만 아니라 정신적, 감정적 개입을 피하라는 의미로도 활용됩니다.","examples":[{"en":"You should stay out of their argument; it\'s none of your business.","ko":"그들의 논쟁에 끼어들지 않는 것이 좋습니다; 당신과는 상관없는 일입니다."},{"en":"I\'m trying to stay out of trouble.","ko":"저는 문제에 휘말리지 않으려고 노력하고 있습니다."},{"en":"Stay out of my room!","ko":"내 방에 들어오지 마!"},{"en":"She advised him to stay out of politics.","ko":"그녀는 그에게 정치에 관여하지 말라고 조언했습니다."},{"en":"If you want to avoid getting sick, stay out of crowded places.","ko":"병에 걸리고 싶지 않다면, 붐비는 장소는 피하세요."}],"related":[{"slug":"keep-away-from","title":"Keep Away From","type":"synonym","note":"유사하게 특정 사람, 장소 또는 사물에서 거리를 두라는 의미입니다."},{"slug":"avoid","title":"Avoid","type":"synonym","note":"가장 직접적인 동의어로, 무엇인가를 피하는 행위를 나타냅니다."},{"slug":"refrain-from","title":"Refrain From","type":"synonym","note":"주로 행동이나 습관을 삼가는 의미로 사용됩니다."},{"slug":"get-involved-in","title":"Get Involved In","type":"antonym","note":"어떤 일에 적극적으로 참여하거나 개입하는 것을 의미합니다."},{"slug":"interfere-with","title":"Interfere With","type":"antonym","note":"주로 원치 않는 방식으로 어떤 일에 간섭하거나 방해하는 것을 의미합니다."}],"date":"2025-09-03T00:00"}');
