const come_to_a_conclusion_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"come-to-a-conclusion","title":"Come To A Conclusion","koreanPronunciation":"컴 투 어 컨클루전","tags":["자주 쓰는 표현","관용구"],"meaning":"결론에 도달하거나 판단을 내리는 것의 의미입니다","description":"이 표현은 어떤 상황, 논의, 또는 정보를 검토한 후에 최종적인 결정이나 판단을 내릴 때 사용됩니다. 생각이나 토론의 과정을 거쳐 최종적인 결과에 도달하는 것을 의미하며, 개인적인 사고 과정뿐만 아니라 회의나 조사 후에 집단적으로 결론을 내릴 때도 활용됩니다.","examples":[{"en":"After reviewing all the evidence, the jury came to a conclusion that the defendant was guilty.","ko":"모든 증거를 검토한 후에, 배심원단은 피고인이 유죄라는 결론에 도달했습니다."},{"en":"We need to discuss this further before we can come to a conclusion.","ko":"결론을 내리기 전에 이것에 대해 더 논의해야 합니다."},{"en":"It took them a long time to come to a conclusion about the best marketing strategy.","ko":"그들은 최고의 마케팅 전략에 대한 결론에 도달하는 데 오랜 시간이 걸렸습니다."},{"en":"She quickly came to a conclusion that moving to a new city was the right choice for her career.","ko":"그녀는 새 도시로 이사하는 것이 자신의 경력에 올바른 선택이라는 결론을 빠르게 내렸습니다."}],"related":[{"slug":"reach-a-conclusion","title":"Reach A Conclusion","type":"synonym","note":"거의 동일한 의미로 사용됩니다."},{"slug":"draw-a-conclusion","title":"Draw A Conclusion","type":"synonym","note":"특정 사실이나 증거로부터 결론을 도출한다는 뉘앙스가 강합니다."},{"slug":"make-a-decision","title":"Make A Decision","type":"synonym","note":"결론보다는 특정 상황에 대한 행동 방침을 결정할 때 더 자주 쓰입니다."},{"slug":"form-an-opinion","title":"Form An Opinion","type":"synonym","note":"최종적인 결론보다는 어떤 주제에 대한 개인적인 견해를 형성하는 것을 의미합니다."}],"date":"2025-09-29T00:01"}');
