const break_the_news_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"break-the-news","title":"Break The News","koreanPronunciation":"브레이크 더 뉴스","tags":["관용구","자주 쓰는 표현"],"meaning":"중요하거나 좋지 않은 소식을 전하다는 의미입니다","description":"이 표현은 대개 조심스럽거나 준비된 방식으로 중요한 정보, 특히 좋지 않거나 민감한 소식을 다른 사람에게 알리는 행위를 설명할 때 사용됩니다. \'뉴스\'가 꼭 새로워야 한다는 의미보다는, 듣는 사람에게 영향을 미칠 만한 소식을 의미하며, 종종 감정적인 요소가 포함될 수 있습니다.","examples":[{"en":"I had to break the news to my friend that her car was stolen.","ko":"친구에게 그녀의 차가 도난당했다는 소식을 전해야만 했습니다."},{"en":"Who\'s going to break the news to the team about the project cancellation?","ko":"누가 팀에게 프로젝트 취소 소식을 전할 건가요?"},{"en":"The doctor gently broke the news of the diagnosis to the patient\'s family.","ko":"의사는 환자 가족에게 진단 소식을 조심스럽게 전했습니다."},{"en":"She broke the news of her engagement to her parents last night.","ko":"그녀는 어젯밤 부모님께 약혼 소식을 전했습니다."}],"related":[{"slug":"deliver-the-news","title":"Deliver The News","type":"synonym","note":"소식을 전하다는 의미로, 격식 없이 사용될 수 있습니다."},{"slug":"impart-information","title":"Impart Information","type":"synonym","note":"좀 더 공식적인 상황에서 정보를 전달한다는 의미입니다."},{"slug":"inform-someone","title":"Inform Someone","type":"synonym","note":"누군가에게 알리다, 통지하다는 일반적인 의미입니다."},{"slug":"keep-it-a-secret","title":"Keep It A Secret","type":"antonym","note":"소식을 전하지 않고 비밀로 유지하는 것을 의미합니다."}],"date":"2025-12-20T00:00"}');
