const beat_the_clock_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"beat-the-clock","title":"Beat The Clock","koreanPronunciation":"비트 더 클락","tags":["관용구","자주 쓰는 표현"],"meaning":"주어진 시간 안에 어떤 일을 성공적으로 마치거나, 시간 제한을 극복하고 목표를 달성한다는 의미입니다.","description":"이 표현은 특정 시간 제한 내에 작업을 완료해야 하거나, 정해진 시간 안에 특정 목표를 달성해야 하는 상황에서 사용됩니다. 주로 경쟁적인 상황, 시험, 마감 기한이 있는 프로젝트 등에서 시간이 촉박한 상황에 직면했을 때, 그 시간을 이겨내고 성공적으로 목표를 달성하는 것을 의미합니다. 문자 그대로 시계(시간)를 이긴다는 비유적인 표현입니다.","examples":[{"en":"We had to beat the clock to submit all the documents before the office closed.","ko":"우리는 사무실이 닫히기 전에 모든 서류를 제출하기 위해 시간과의 싸움에서 이겨야 했습니다."},{"en":"The chef managed to beat the clock and prepare a five-course meal in under an hour.","ko":"그 요리사는 시간 안에 해내서 한 시간도 안 되어 5가지 코스 요리를 준비했습니다."},{"en":"Can you beat the clock and finish this puzzle before dinner?","ko":"저녁 식사 전에 이 퍼즐을 시간 내에 끝낼 수 있겠니?"},{"en":"The basketball team needed to beat the clock with a last-minute shot to win the game.","ko":"그 농구팀은 경기를 이기기 위해 막판 슛으로 시간과의 싸움에서 이겨야 했습니다."}],"related":[{"slug":"race-against-time","title":"Race Against Time","type":"synonym","note":"시간에 쫓기어 서두르다"},{"slug":"against-the-clock","title":"Against The Clock","type":"synonym","note":"시간과의 싸움에서, 시간에 쫓겨"},{"slug":"meet-the-deadline","title":"Meet The Deadline","type":"synonym","note":"마감 기한을 맞추다"}],"date":"2026-03-14T00:00"}');
;// ./blog/trust-your-instinct/content.json
const trust_your_instinct_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"trust-your-instinct","title":"Trust Your Instinct","koreanPronunciation":"트러스트 유어 인스팅트","tags":["자주 쓰는 표현","관용구"],"meaning":"직감이나 본능적인 느낌을 믿고 따르라는 의미입니다.","description":"이 표현은 어떤 결정을 내리거나 상황을 판단할 때, 논리적인 사고방식뿐만 아니라 내면의 직감이나 본능적인 느낌을 따르는 것이 중요함을 강조합니다. 특히 불확실한 상황에서 데이터나 명확한 증거가 없을 때 자신의 내적 감각을 신뢰하라는 조언으로 사용됩니다.","examples":[{"en":"When in doubt, always trust your instinct.","ko":"의심스러울 때에는 항상 당신의 직감을 믿으세요."},{"en":"She decided to trust her instinct and turn down the job offer, even though it looked good on paper.","ko":"그녀는 서류상으로는 좋아 보였지만, 직감을 믿고 그 일자리 제안을 거절하기로 결정했습니다."},{"en":"My instinct told me not to go, and I\'m glad I listened.","ko":"내 직감이 가지 말라고 했고, 내가 그 말을 듣길 잘했어."},{"en":"Sometimes, the best decisions come from trusting your instinct, not overthinking.","ko":"때로는 너무 깊이 생각하기보다 직감을 믿는 것이 최고의 결정을 내리는 방법입니다."}],"related":[{"slug":"follow-your-gut","title":"Follow Your Gut","type":"synonym","note":"비슷하게 직감을 따르라는 의미입니다."},{"slug":"go-with-your-gut-feeling","title":"Go With Your Gut Feeling","type":"synonym","note":"직감에 따라 행동하라는 의미입니다."},{"slug":"listen-to-your-intuition","title":"Listen To Your Intuition","type":"synonym","note":"내면의 목소리, 즉 직감을 들으라는 뜻입니다."},{"slug":"overthink","title":"Overthink","type":"antonym","note":"지나치게 생각하여 직감을 무시하는 행위를 뜻합니다."}],"date":"2025-11-21T00:00"}');
;// ./blog/let-off-steam/content.json
const let_off_steam_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"let-off-steam","title":"Let Off Steam","koreanPronunciation":"렛 오프 스팀","tags":["관용구","구동사"],"meaning":"쌓인 스트레스나 분노와 같은 강한 감정을 발산하거나 에너지를 분출하는 것의미입니다.","description":"이 표현은 압력솥에서 증기를 배출하여 내부 압력을 낮추는 것에 비유하여, 사람이 내면에 쌓인 긴장이나 분노, 스트레스 등을 밖으로 표출하여 정신적인 부담을 덜어내는 행동을 의미합니다. 답답한 감정을 삭이지 않고 해소하여 기분을 전환하거나 평온을 되찾는 상황에서 주로 사용됩니다.","examples":[{"en":"After a tough week, I need to go to the gym to let off steam.","ko":"힘든 한 주를 보낸 후에는 스트레스를 풀기 위해 헬스장에 가야겠어."},{"en":"He usually goes for a long run to let off steam when he\'s feeling overwhelmed.","ko":"그는 압도감을 느낄 때면 스트레스를 풀기 위해 보통 장거리 달리기를 합니다."},{"en":"Sometimes, a good cry is all you need to let off steam and feel better.","ko":"가끔은 실컷 우는 것만으로도 쌓인 감정을 해소하고 기분이 나아질 수 있어요."},{"en":"The kids let off steam by playing loudly in the park after school.","ko":"아이들은 방과 후에 공원에서 시끄럽게 놀며 에너지를 발산했습니다."}],"related":[{"slug":"blow-off-steam","title":"Blow Off Steam","type":"synonym","note":"동일한 의미로 사용됩니다."},{"slug":"vent-ones-feelings","title":"Vent One\'s Feelings","type":"synonym","note":"감정을 표출하는 것에 초점을 맞춥니다."},{"slug":"unwind","title":"Unwind","type":"synonym","note":"주로 긴장을 풀고 휴식을 취하는 것을 의미합니다."},{"slug":"bottle-up-emotions","title":"Bottle Up Emotions","type":"antonym","note":"감정을 억누르고 표현하지 않는 것을 의미합니다."}],"date":"2025-11-24T00:00"}');
