const warm_up_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"warm-up","title":"Warm Up","koreanPronunciation":"웜 업","tags":["구동사","자주 쓰는 표현"],"meaning":"몸을 풀거나 준비 운동을 하다, 또는 기계 등을 미리 가동시켜 적절한 상태로 만드는 것을 의미합니다","description":"이 표현은 주로 운동하기 전에 몸의 근육을 이완시키고 부상을 방지하기 위해 하는 준비 운동이나, 공연 전에 목소리나 악기를 가다듬는 행위, 혹은 기계나 엔진이 제대로 작동하기 위해 일정 시간 동안 가동시키는 행위 등을 설명할 때 사용됩니다. 비유적으로는 어떤 활동이나 작업에 본격적으로 들어가기 전에 연습하거나 준비하는 과정을 의미하기도 합니다. 명사로는 \'warm-up\'으로 쓰여 준비 운동 자체를 의미하기도 합니다.","examples":[{"en":"I need to warm up before I start my run.","ko":"달리기 시작하기 전에 몸을 풀어야 해."},{"en":"The band always warms up with some scales before a concert.","ko":"밴드는 콘서트 전에 항상 스케일 연습으로 몸을 푼다."},{"en":"The car needs a few minutes to warm up in this cold weather.","ko":"이 추운 날씨에는 차가 몇 분 정도 예열되어야 한다."},{"en":"Let\'s do some warm-up exercises first.","ko":"먼저 준비 운동을 좀 하자."},{"en":"The singer did some vocal warm-ups before going on stage.","ko":"가수는 무대에 오르기 전에 목을 좀 풀었다."}],"related":[{"slug":"prepare-for","title":"Prepare for","type":"synonym","note":"어떤 활동이나 사건에 대비하다."},{"slug":"loosen-up","title":"Loosen up","type":"synonym","note":"몸의 근육을 이완시키다."},{"slug":"get-ready","title":"Get ready","type":"synonym","note":"무언가를 할 준비를 마치다."},{"slug":"cool-down","title":"Cool down","type":"antonym","note":"운동 후 몸을 식히다."}],"date":"2025-09-19T00:01"}');
