const miss_out_on_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"miss-out-on","title":"Miss Out On","koreanPronunciation":"미스 아웃 온","tags":["구동사","자주 쓰는 표현"],"meaning":"어떤 좋은 기회나 경험을 놓치거나, 참가하지 못해서 아쉬워하다는 의미입니다.","description":"이 표현은 무언가 흥미롭거나 유익한 일에 참여하지 못하거나, 다른 사람들이 경험하는 것을 자신만 경험하지 못할 때 사용됩니다. 주로 후회나 아쉬움의 감정을 동반하며, 본인이 의도하지 않았거나 선택으로 인해 발생할 수 있는 상황 모두에 적용됩니다. 예를 들어, 좋은 거래, 재미있는 행사, 중요한 만남 등을 놓쳤을 때 이 표현을 쓸 수 있습니다.","examples":[{"en":"Don\'t miss out on this incredible opportunity to travel the world!","ko":"세계를 여행할 이 놀라운 기회를 놓치지 마세요!"},{"en":"I feel like I missed out on a lot of fun because I had to work.","ko":"일해야 해서 많은 재미를 놓친 것 같아요."},{"en":"She decided not to go to the concert, fearing she would miss out on sleep.","ko":"잠을 놓칠까 봐 그녀는 콘서트에 가지 않기로 결정했습니다."},{"en":"If you don\'t book your tickets now, you might miss out on the best seats.","ko":"지금 티켓을 예매하지 않으면 최고의 자리를 놓칠 수도 있습니다."},{"en":"They didn\'t want to miss out on the chance to meet their favorite author.","ko":"그들은 가장 좋아하는 작가를 만날 기회를 놓치고 싶지 않았습니다."}],"related":[{"slug":"lose-out-on","title":"Lose Out On","type":"synonym"},{"slug":"pass-up","title":"Pass Up","type":"synonym","note":"자발적으로 기회를 거절하여 놓칠 때 더 자주 사용됩니다."},{"slug":"forgo","title":"Forgo","type":"synonym","note":"즐거움이나 이익이 되는 것을 자발적으로 포기하거나 삼가할 때 사용됩니다."},{"slug":"take-part-in","title":"Take Part In","type":"antonym"},{"slug":"participate-in","title":"Participate In","type":"antonym"}],"date":"2025-10-08T00:00"}');
;// ./blog/master-of-none/content.json
const master_of_none_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"master-of-none","title":"Master of None","koreanPronunciation":"마스터 오브 논","tags":["관용구","자주 쓰는 표현"],"meaning":"여러 가지 일을 조금씩 할 줄 알지만, 그 어느 것 하나도 뛰어나게 잘하지 못하는 사람을 비유적으로 이르는 의미입니다","description":"이 표현은 한 사람이 다양한 기술이나 지식을 가지고 있지만, 특정 분야에서는 전문가 수준에 미치지 못할 때 사용됩니다. 주로 \'만물박사\'처럼 여러 분야에 손을 대는 사람을 묘사하지만, 깊이가 없다는 뉘앙스를 포함할 수 있습니다. 때로는 긍정적이라기보다는 부정적인 의미로 사용될 수 있으며, 특정 분야의 전문성이 부족함을 지적할 때 쓰이기도 합니다. 전체 표현은 보통 \'Jack of all trades, master of none\'입니다.","examples":[{"en":"My brother is a true jack of all trades, master of none; he can fix anything, but nothing perfectly.","ko":"우리 형은 진정한 팔방미인이지만 한 가지도 완벽하게 잘하지는 못해; 무엇이든 고칠 수 있지만 완벽하게는 못 해."},{"en":"She tried various hobbies, but ended up being a master of none.","ko":"그녀는 여러 취미를 시도했지만, 결국 어느 것 하나도 제대로 마스터하지 못했다."},{"en":"Being a master of none isn\'t necessarily bad; it means you\'re versatile.","ko":"여러 가지를 조금씩 잘하는 것이 꼭 나쁜 것은 아니야; 그건 네가 다재다능하다는 뜻이거든."},{"en":"He’s a jack of all trades, master of none, so his skills are broad but not deep.","ko":"그는 팔방미인이지만 어떤 한 분야의 전문가도 아니어서, 그의 기술은 넓지만 깊지는 않다."}],"related":[{"slug":"jack-of-all-trades","title":"Jack of all trades","type":"synonym","note":"이 표현과 함께 쓰여 전체적인 숙어를 이룹니다."},{"slug":"versatile","title":"Versatile","type":"synonym","note":"여러 분야에 능하다는 긍정적인 의미를 가집니다."},{"slug":"well-rounded","title":"Well-rounded","type":"synonym","note":"다재다능하고 균형 잡힌 능력을 가졌다는 긍정적인 의미를 가집니다."},{"slug":"dabbler","title":"Dabbler","type":"synonym","note":"특정 분야를 깊이 파고들지 않고 취미 삼아 즐기는 사람을 지칭하며, 깊이가 부족하다는 뉘앙스가 있습니다."}],"date":"2025-07-09T16:30"}');
;// ./blog/the-choice-is-yours/content.json
const the_choice_is_yours_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"the-choice-is-yours","title":"The Choice Is Yours","koreanPronunciation":"더 초이스 이즈 유어즈","tags":["자주 쓰는 표현"],"meaning":"결정이나 선택의 권한이 당신에게 있음을 나타내는 의미입니다.","description":"이 표현은 상대방에게 어떤 상황이나 옵션에 대한 최종적인 결정권을 부여하거나, 그 선택에 대한 책임을 강조할 때 사용됩니다. 주로 \'나는 나의 역할을 다 했으니, 이제 네가 결정할 차례다\'라는 뉘앙스를 가집니다. 다른 사람이 강요하거나 대신 결정해 주지 않음을 강조하며, 개인의 자유로운 의사결정을 존중하는 맥락에서 쓰이기도 합니다.","examples":[{"en":"I\'ve laid out all the options; now the choice is yours.","ko":"모든 선택지를 제시했으니, 이제 선택은 당신의 몫입니다."},{"en":"You can come with us or stay home. The choice is yours.","ko":"저희와 함께 가셔도 되고 집에 계셔도 됩니다. 선택은 당신에게 달려있습니다."},{"en":"Remember, it\'s your career path, so the choice is ultimately yours.","ko":"기억하세요, 이건 당신의 경력 경로이니, 궁극적인 선택은 당신의 것입니다."},{"en":"We can eat at the Italian place or the Chinese restaurant. The choice is yours.","ko":"이탈리아 식당으로 가도 되고 중국 식당으로 가도 됩니다. 당신이 고르세요."}],"related":[{"slug":"it-s-up-to-you","title":"It\'s Up To You","type":"synonym","note":"결정이나 책임이 당신에게 있다는 의미"},{"slug":"the-ball-is-in-your-court","title":"The Ball Is In Your Court","type":"synonym","note":"다음 행동이나 결정권이 당신에게 있다는 의미"},{"slug":"you-call-the-shots","title":"You Call The Shots","type":"synonym","note":"주도권을 가지고 결정한다는 의미"},{"slug":"i-ll-decide-for-you","title":"I\'ll Decide For You","type":"antonym","note":"당신 대신 내가 결정하겠다는 의미로, \'선택은 당신의 몫\'이라는 표현과 반대됩니다."}],"date":"2026-02-02T00:00"}');
;// ./blog/time-will-tell/content.json
const time_will_tell_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"time-will-tell","title":"Time Will Tell","koreanPronunciation":"타임 윌 텔","tags":["관용구","자주 쓰는 표현"],"meaning":"어떤 일의 진실이나 결과는 시간이 지나야 알 수 있다는 의미입니다.","description":"이 표현은 현재 불확실하거나 알 수 없는 상황, 또는 미래에 밝혀질 진실에 대해 이야기할 때 사용됩니다. 어떤 결론이나 해답을 바로 알 수 없을 때, 시간이 지나면 자연스럽게 모든 것이 드러날 것이라는 인내와 기다림의 의미를 내포합니다. 주로 예측하기 어려운 상황이나 논쟁적인 문제에 대한 최종 결론이 나올 때까지 기다려야 함을 강조합니다.","examples":[{"en":"Will the new strategy succeed? Only time will tell.","ko":"새로운 전략이 성공할까요? 오직 시간이 말해줄 겁니다."},{"en":"They made a lot of promises, but time will tell if they keep them.","ko":"그들은 많은 약속을 했지만, 그 약속을 지킬지는 시간이 지나봐야 알겠죠."},{"en":"We don\'t know yet if the investment was a good idea, but time will tell.","ko":"아직 그 투자가 좋은 생각이었는지 모르겠지만, 시간이 지나면 알게 될 겁니다."},{"en":"The critics are divided on the film\'s quality. Time will tell if it becomes a classic.","ko":"평론가들은 그 영화의 작품성에 대해 의견이 분분합니다. 명작이 될지는 시간이 알려줄 것입니다."}],"related":[{"slug":"wait-and-see","title":"Wait And See","type":"synonym","note":"결과를 알기 위해 기다려야 한다는 점을 강조합니다."},{"slug":"only-time-will-reveal","title":"Only Time Will Reveal","type":"synonym","note":"\'Time will tell\'과 거의 동일한 의미로 사용됩니다."},{"slug":"we-ll-see","title":"We\'ll See","type":"synonym","note":"상황의 결과나 진실을 미래에 알게 될 것이라는 간단한 표현입니다."}],"date":"2025-11-04T00:01"}');
;// ./blog/settle-a-dispute/content.json
const settle_a_dispute_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"settle-a-dispute","title":"Settle A Dispute","koreanPronunciation":"세틀 어 디스퓨트","tags":["자주 쓰는 표현","연어"],"meaning":"갈등이나 논쟁을 해결하거나 끝내는 것의 의미입니다.","description":"이 표현은 사람들 사이의 의견 차이나 논쟁을 평화롭게, 또는 합의를 통해 해결하는 상황을 묘사할 때 사용됩니다. 주로 법적 분쟁, 가족 간의 다툼, 직장 내 갈등 등 다양한 종류의 불화를 종결시키는 것을 의미합니다. 양측이 만족할 만한 해결책을 찾거나, 중재를 통해 합의에 도달하는 과정을 포함합니다.","examples":[{"en":"The mediator helped both parties settle their dispute amicably.","ko":"중재자는 양측이 그들의 분쟁을 원만하게 해결하도록 도왔다."},{"en":"They\'ve been trying to settle the dispute over the inheritance for months.","ko":"그들은 상속 문제에 대한 분쟁을 몇 달째 해결하려고 노력하고 있다."},{"en":"It\'s crucial to settle this business dispute quickly to avoid further losses.","ko":"더 이상의 손실을 막기 위해 이 사업 분쟁을 신속히 해결하는 것이 중요하다."},{"en":"The best way to settle a dispute is often through open communication and compromise.","ko":"분쟁을 해결하는 가장 좋은 방법은 종종 열린 소통과 타협을 통해서이다."}],"related":[{"slug":"resolve-a-conflict","title":"Resolve A Conflict","type":"synonym"},{"slug":"iron-out-differences","title":"Iron Out Differences","type":"synonym","note":"비격식적인 표현"},{"slug":"reach-a-compromise","title":"Reach A Compromise","type":"synonym","note":"합의점을 찾는 뉘앙스"},{"slug":"make-peace","title":"Make Peace","type":"synonym","note":"관계를 회복하거나 화해하는 것에 중점"},{"slug":"aggravate-a-dispute","title":"Aggravate A Dispute","type":"antonym","note":"분쟁을 악화시키다"}],"date":"2026-03-27T00:00"}');
;// ./blog/fade-away/content.json
const fade_away_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"fade-away","title":"Fade Away","koreanPronunciation":"페이드 어웨이","tags":["구동사"],"meaning":"점차 사라지거나 흐려지다; 점차 기세, 건강, 중요성 등이 약해지거나 없어지는 것을 의미합니다.","description":"이 표현은 주로 빛, 소리, 기억 등이 서서히 희미해지거나 사라지는 것을 묘사할 때 사용됩니다. 또한 사람의 기력이나 건강이 점차 쇠퇴하거나, 어떤 것의 중요성이나 인기가 서서히 줄어들 때도 쓰일 수 있습니다. 시간의 흐름에 따라 자연스럽게 소멸하는 과정을 나타내는 데 적합합니다.","examples":[{"en":"The old photograph had started to fade away.","ko":"오래된 사진이 흐릿해지기 시작했다."},{"en":"Her voice began to fade away as she walked further down the hall.","ko":"그녀가 복도 아래로 더 멀리 걸어갈수록 그녀의 목소리는 점차 작아졌다."},{"en":"His memories of the war are slowly fading away.","ko":"그의 전쟁 기억은 서서히 희미해지고 있다."},{"en":"The bright colors of the painting will fade away over time if exposed to sunlight.","ko":"그 그림의 밝은 색깔들은 햇빛에 노출되면 시간이 지나면서 바래질 것이다."},{"en":"The enthusiasm for the new project began to fade away after the initial excitement.","ko":"새 프로젝트에 대한 열정은 초반의 흥분이 가라앉은 후 사라지기 시작했다."}],"related":[{"slug":"disappear","title":"Disappear","type":"synonym"},{"slug":"vanish","title":"Vanish","type":"synonym","note":"\'fade away\'보다 갑작스럽거나 완전히 사라지는 것을 강조"},{"slug":"diminish","title":"Diminish","type":"synonym","note":"점차적으로 감소하거나 약해지는 것을 의미"},{"slug":"die-down","title":"Die Down","type":"synonym","note":"소리, 감정, 폭풍 등이 점차 약해지거나 가라앉는 것을 의미"},{"slug":"wear-off","title":"Wear Off","type":"synonym","note":"약의 효과, 감정, 흥미 등이 점차 사라지는 것을 의미"}],"date":"2025-07-05T17:15"}');
;// ./blog/hit-the-sack/content.json
const hit_the_sack_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"hit-the-sack","title":"Hit the Sack","koreanPronunciation":"히트 더 색","tags":["관용구","자주 쓰는 표현"],"meaning":"잠자리에 들다, 자러 가다 라는 의미입니다","description":"이 표현은 비격식적인 표현으로, 하루를 마무리하고 잠자리에 들 때 사용됩니다. 피곤할 때 “I’m going to hit the sack”이라고 말하면 \\"이제 자러 간다\\"는 뜻이 됩니다. 친구나 가족 간의 일상 대화에서 자주 쓰입니다.","examples":[{"en":"I’m exhausted. I’m going to hit the sack.","ko":"너무 피곤해. 이제 자러 갈게."},{"en":"It’s getting late — time to hit the sack.","ko":"늦었네 — 이제 잘 시간이야."},{"en":"After the long trip, we all hit the sack early.","ko":"긴 여행 끝에 우리 모두 일찍 잠자리에 들었어."},{"en":"He usually hits the sack around midnight.","ko":"그는 보통 자정쯤 잠자리에 들어."},{"en":"Let’s hit the sack and get some rest before tomorrow’s hike.","ko":"내일 하이킹 전에 쉬자. 자러 가자."}],"related":[{"slug":"go-to-bed","title":"Go to bed","type":"synonym"},{"slug":"turn-in","title":"Turn in","type":"synonym"},{"slug":"crash","title":"Crash","type":"synonym","note":"Slang; often implies falling asleep quickly due to exhaustion or lack of a proper bed."},{"slug":"get-some-shut-eye","title":"Get some shut-eye","type":"synonym"},{"slug":"call-it-a-night","title":"Call it a night","type":"synonym"}],"date":"2025-06-18T11:15"}');
;// ./blog/be-the-spitting-image-of/content.json
const be_the_spitting_image_of_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"be-the-spitting-image-of","title":"Be The Spitting Image Of","koreanPronunciation":"비 더 스피팅 이미지 오브","tags":["관용구"],"meaning":"어떤 사람이나 사물이 다른 사람이나 사물과 아주 흡사하게 닮았다는 의미입니다","description":"이 표현은 주로 외모나 생김새가 매우 비슷하여 마치 복사해 놓은 것 같을 때 사용됩니다. \'spitting image\'는 \'침을 뱉은 듯이 똑같다\'는 뜻에서 유래했는데, 이는 강한 유사성을 강조하는 말입니다. 주로 부모가 자녀를 닮았을 때나, 유명인을 닮았을 때 등에 쓰입니다.","examples":[{"en":"Everyone says she\'s the spitting image of her mother when she was young.","ko":"모두가 그녀가 어렸을 적 어머니와 똑 닮았다고 말한다."},{"en":"The painting was the spitting image of the old king.","ko":"그 그림은 옛 왕과 판박이였다."},{"en":"He\'s the spitting image of his grandfather, even down to his mannerisms.","ko":"그는 버릇까지도 할아버지를 빼닮았다."},{"en":"That new building is the spitting image of the one downtown.","ko":"저 새 건물은 시내에 있는 건물과 판박이다."}],"related":[{"slug":"take-after","title":"Take After","note":"주로 부모나 조상을 닮을 때 사용됩니다."},{"slug":"resemble","title":"Resemble","note":"일반적으로 \'~와 닮다\'는 뜻으로 사용됩니다."},{"slug":"look-like","title":"Look Like","note":"가장 일반적인 \'~처럼 보이다\' 또는 \'~와 닮다\'는 뜻입니다."}],"date":"2025-08-10T00:00"}');
;// ./blog/get-out-of-hand/content.json
const get_out_of_hand_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"get-out-of-hand","title":"Get Out Of Hand","koreanPronunciation":"겟 아웃 오브 핸드","tags":["관용구","자주 쓰는 표현"],"meaning":"통제 불능의 상태가 되거나 상황이 악화되는 것을 의미합니다.","description":"이 표현은 어떤 상황이나 행동이 통제력을 잃고 걷잡을 수 없게 될 때 사용됩니다. 주로 부정적인 맥락에서 쓰이며, 예상치 못한 방식으로 상황이 악화되거나 통제 범위를 벗어나는 문제를 야기할 때 적합한 표현입니다.","examples":[{"en":"The party started to get out of hand after midnight.","ko":"자정 이후 파티는 걷잡을 수 없이 되어갔다."},{"en":"If the situation gets out of hand, we\'ll have to call for backup.","ko":"상황이 통제 불능이 되면, 우리는 지원을 요청해야 할 것입니다."},{"en":"Parents worry when their children\'s screen time starts to get out of hand.","ko":"아이들의 스크린 사용 시간이 걷잡을 수 없게 되면 부모들은 걱정한다."},{"en":"We need to address this problem now before it gets completely out of hand.","ko":"이 문제가 완전히 통제 불능이 되기 전에 지금 해결해야 합니다."}],"related":[{"slug":"lose-control","title":"Lose Control","type":"synonym"},{"slug":"go-awry","title":"Go Awry","type":"synonym","note":"계획이나 상황이 예상대로 되지 않고 잘못되는 경우에 사용됩니다."},{"slug":"keep-under-control","title":"Keep Under Control","type":"antonym"}],"date":"2025-10-02T00:00"}');
;// ./blog/walking-on-air/content.json
const walking_on_air_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"walking-on-air","title":"Walking On Air","koreanPronunciation":"워킹 온 에어","tags":["관용구","자주 쓰는 표현"],"meaning":"매우 행복하거나 기뻐서 발이 땅에 닿지 않는 것 같은 상태를 의미합니다","description":"이 표현은 엄청난 행복감이나 기쁨, 흥분으로 인해 마치 공중을 걷는 듯한 가벼운 기분을 묘사할 때 사용됩니다. 주로 좋은 소식, 성공적인 결과, 사랑에 빠졌을 때 등 긍정적인 경험으로 인해 느끼는 벅찬 감정을 나타냅니다.","examples":[{"en":"After getting the job offer, she was walking on air for days.","ko":"취업 제안을 받은 후, 그녀는 며칠 동안 구름 위를 걷는 듯한 기분이었다."},{"en":"He\'s been walking on air ever since he won the lottery.","ko":"그는 복권에 당첨된 이후로 계속해서 너무 행복해하고 있다."},{"en":"When they announced her name as the winner, she felt like she was walking on air.","ko":"그녀의 이름이 우승자로 호명되었을 때, 그녀는 마치 하늘을 걷는 듯한 기분이었다."},{"en":"She\'s walking on air after her first successful art exhibition.","ko":"첫 번째 미술 전시회를 성공적으로 마친 후 그녀는 매우 행복해하고 있다."}],"related":[{"slug":"over-the-moon","title":"Over The Moon","type":"synonym","note":"매우 기뻐하는 상태를 강조합니다."},{"slug":"on-cloud-nine","title":"On Cloud Nine","type":"synonym","note":"최고로 행복한 상태를 나타냅니다."},{"slug":"be-on-top-of-the-world","title":"Be On Top Of The World","type":"synonym","note":"세상 모든 것을 가진 듯한 기쁨을 표현합니다."},{"slug":"down-in-the-dumps","title":"Down In The Dumps","type":"antonym","note":"우울하거나 슬픈 감정을 나타냅니다."}],"date":"2025-08-24T00:01"}');
;// ./blog/mince-no-words/content.json
const mince_no_words_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"mince-no-words","title":"Mince No Words","koreanPronunciation":"민스 노 워즈","tags":["관용구","자주 쓰는 표현"],"meaning":"솔직하고 직설적으로 말하는 것을 의미합니다.","description":"이 표현은 다른 사람의 감정을 상하게 할까 걱정하거나 완곡하게 돌려 말하지 않고, 자신의 생각이나 의견을 가감 없이 직접적으로 전달하는 것을 나타냅니다. 특히 중요한 문제나 불편한 진실을 이야기할 때 사용됩니다. \'mince\'는 \'잘게 썰다\'라는 의미로, \'no words\'와 결합하여 말을 잘게 부수지 않고, 즉 에둘러 말하지 않는다는 뜻이 됩니다.","examples":[{"en":"The CEO minced no words when he criticized the team\'s performance.","ko":"CEO는 팀의 성과를 비판할 때 직설적으로 말했다."},{"en":"She\'s known for mincing no words, so you\'ll always know where you stand with her.","ko":"그녀는 솔직하게 말하는 것으로 유명해서, 그녀와 있을 때는 항상 당신의 입장을 정확히 알 수 있을 것이다."},{"en":"If you want my honest opinion, I\'ll mince no words: this plan won\'t work.","ko":"솔직한 의견을 원한다면, 저는 돌려 말하지 않겠습니다: 이 계획은 성공하지 못할 겁니다."},{"en":"He minced no words in his assessment of the dire situation, presenting the facts as they were.","ko":"그는 심각한 상황에 대한 평가에서 돌려 말하지 않고, 있는 그대로의 사실을 제시했다."}],"related":[{"slug":"speak-plainly","title":"Speak Plainly","type":"synonym"},{"slug":"tell-it-like-it-is","title":"Tell It Like It Is","type":"synonym"},{"slug":"call-a-spade-a-spade","title":"Call a Spade a Spade","type":"synonym","note":"돌려 말하지 않고 본질을 그대로 말하다."},{"slug":"sugarcoat","title":"Sugarcoat","type":"antonym","note":"불쾌한 것을 더 좋게 보이도록 꾸미다."},{"slug":"walk-on-eggshells","title":"Walk on Eggshells","type":"antonym","note":"다른 사람의 감정을 상하게 할까 봐 매우 조심스럽게 행동하다."}],"date":"2025-08-30T00:01"}');
;// ./blog/jump-the-gun/content.json
const jump_the_gun_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"jump-the-gun","title":"Jump The Gun","koreanPronunciation":"점프 더 건","tags":["관용구","자주 쓰는 표현"],"meaning":"너무 성급하게 행동하거나, 어떤 일이 시작되기도 전에 미리 행동하는 것을 의미합니다.","description":"이 표현은 육상 경기에서 출발 신호(총소리)가 울리기도 전에 미리 출발선에서 뛰쳐나가는 것을 비유하는 말에서 유래했습니다. 즉, 어떤 행동이나 결정을 내리기 전에 충분히 기다리거나 준비하지 않고 너무 서두르거나 성급하게 행동하는 상황을 묘사할 때 사용됩니다. 조급하거나 섣부른 행동이 부정적인 결과를 초래할 수 있음을 암시하는 경우가 많습니다.","examples":[{"en":"Don\'t jump the gun; let\'s wait for all the information before making a decision.","ko":"성급하게 굴지 마세요. 모든 정보를 기다린 후에 결정합시다."},{"en":"I think he jumped the gun by announcing his engagement so soon after meeting her.","ko":"그가 그녀를 만난 지 얼마 안 되어 약혼을 발표한 것은 너무 성급한 행동이었다고 생각해요."},{"en":"The company jumped the gun and released the product before it was fully tested, leading to many bugs.","ko":"회사는 너무 성급하게 제품을 완전히 테스트하기도 전에 출시했고, 이는 많은 버그로 이어졌습니다."},{"en":"We need to plan carefully and not jump the gun on this project.","ko":"우리는 이 프로젝트에 대해 신중하게 계획해야 하며, 성급하게 행동해서는 안 됩니다."}],"related":[{"slug":"rush-into-things","title":"Rush Into Things","type":"synonym"},{"slug":"haste-makes-waste","title":"Haste Makes Waste","type":"synonym","note":"성급함이 일을 그르친다는 속담입니다."},{"slug":"act-precipitously","title":"Act Precipitously","type":"synonym","note":"좀 더 격식 있는 표현으로, 섣부르게 행동한다는 의미입니다."},{"slug":"proceed-cautiously","title":"Proceed Cautiously","type":"antonym"},{"slug":"take-your-time","title":"Take Your Time","type":"antonym"}],"date":"2026-04-15T00:00"}');
;// ./blog/talk-turkey/content.json
const talk_turkey_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"talk-turkey","title":"Talk Turkey","koreanPronunciation":"토크 터키","tags":["관용구"],"meaning":"솔직하고 직접적으로 이야기하는 의미입니다","description":"이 표현은 돌려 말하거나 완곡하게 표현하지 않고, 어떤 문제나 사업에 대해 솔직하고 직접적으로 이야기하는 것을 의미합니다. 주로 중요한 문제나 어려운 협상에서 진지하게 논의할 때 사용됩니다. 비유적으로 마치 감사절 칠면조를 나누듯 진지하게 핵심을 파고드는 것을 나타냅니다.","examples":[{"en":"Let\'s talk turkey about the budget, we need to find a solution quickly.","ko":"예산 문제에 대해 솔직하게 이야기해봅시다. 빨리 해결책을 찾아야 합니다."},{"en":"It\'s time for us to sit down and talk turkey about your performance.","ko":"이제 앉아서 당신의 업무 성과에 대해 솔직하게 이야기할 시간입니다."},{"en":"They finally decided to talk turkey and settle their differences.","ko":"그들은 마침내 솔직하게 이야기하고 의견 차이를 해결하기로 결정했습니다."}],"related":[{"slug":"get-down-to-brass-tacks","title":"Get Down to Brass Tacks","type":"synonym","note":"본론으로 들어가다, 핵심을 논의하다"},{"slug":"lay-it-on-the-line","title":"Lay It on the Line","type":"synonym","note":"솔직하게 말하다, 분명히 밝히다"},{"slug":"pull-no-punches","title":"Pull No Punches","type":"synonym","note":"솔직하게 말하다, 봐주지 않고 말하다"}],"date":"2025-10-24T00:00"}');
;// ./blog/turn-a-blind-eye/content.json
const turn_a_blind_eye_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"turn-a-blind-eye","title":"Turn A Blind Eye","koreanPronunciation":"턴 어 블라인드 아이","tags":["관용구"],"meaning":"문제가 있거나 불쾌한 상황을 의도적으로 모른 척하거나 무시하는 것을 의미합니다.","description":"이 표현은 영국 해군 제독 호레이쇼 넬슨이 전투 중 상관의 후퇴 신호를 못 본 척하기 위해 의도적으로 실명한 눈에 망원경을 대고 있었던 일화에서 유래했습니다. 주로 어떤 잘못이나 불법적인 행위, 혹은 눈에 거슬리는 것을 알면서도 모른 척하거나 개입하지 않는 상황에서 사용됩니다. 책임 회피나 편의를 위해 의도적으로 사실을 외면할 때 쓰이며, 때로는 도덕적 비난의 뉘앙스를 가질 수도 있습니다.","examples":[{"en":"The teacher decided to turn a blind eye to the students\' minor infractions on the last day of school.","ko":"선생님은 학기 마지막 날 학생들의 사소한 규칙 위반을 못 본 척하기로 결정했습니다."},{"en":"Many people turn a blind eye to environmental issues because they seem too big to solve.","ko":"많은 사람들이 환경 문제가 너무 커서 해결하기 어렵다고 생각하여 외면합니다."},{"en":"If you always turn a blind eye to his mistakes, he\'ll never learn.","ko":"그의 실수를 항상 못 본 척한다면, 그는 결코 배우지 못할 것입니다."},{"en":"The government was accused of turning a blind eye to the corruption within its ranks.","ko":"정부는 내부 부패를 외면했다는 비난을 받았습니다."}],"related":[{"slug":"look-the-other-way","title":"Look The Other Way","type":"synonym","note":"비슷하게 문제를 알면서도 모른 척하는 의미입니다."},{"slug":"ignore","title":"Ignore","type":"synonym","note":"더 일반적인 의미의 \'무시하다\'입니다."},{"slug":"address-the-issue","title":"Address The Issue","type":"antonym","note":"문제를 직시하고 해결하려 노력하는 행동입니다."}],"date":"2025-10-31T00:00"}');
;// ./blog/suppress-emotions/content.json
const suppress_emotions_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"suppress-emotions","title":"Suppress Emotions","koreanPronunciation":"서프레스 이모션스","tags":["자주 쓰는 표현","관용구"],"meaning":"감정을 억누르거나 숨기는 것을 의미합니다.","description":"이 표현은 슬픔, 분노, 기쁨과 같은 강한 감정을 겉으로 드러내지 않고 내면에 가두어 두는 행위를 설명합니다. 사회적 상황, 개인적인 이유 또는 감정적으로 취약해 보이고 싶지 않을 때 자주 사용됩니다. 건강하지 못한 대처 방식이 될 수도 있으며, 장기적으로는 정신 건강에 부정적인 영향을 미칠 수 있습니다.","examples":[{"en":"He always tries to suppress his emotions, even when he\'s upset.","ko":"그는 화가 나도 항상 감정을 억누르려고 노력합니다."},{"en":"It\'s not healthy to constantly suppress your emotions; sometimes you need to express them.","ko":"감정을 계속 억누르는 것은 건강에 좋지 않습니다. 때로는 표현할 필요가 있습니다."},{"en":"She had to suppress her laughter during the serious meeting.","ko":"그녀는 진지한 회의 중에 웃음을 억눌러야 했습니다."},{"en":"Many people suppress their true feelings to avoid conflict.","ko":"많은 사람들이 갈등을 피하기 위해 자신의 진정한 감정을 억누릅니다."}],"related":[{"slug":"bottle-up-emotions","title":"Bottle Up Emotions","type":"synonym","note":"감정을 속으로 삭이다, 억압하다는 의미가 강합니다."},{"slug":"bury-one-s-feelings","title":"Bury One\'s Feelings","type":"synonym","note":"자신의 감정을 숨기거나 묻어두는 것을 의미합니다."},{"slug":"hold-back-tears","title":"Hold Back Tears","type":"synonym","note":"특정 감정인 눈물을 참는 것에 초점을 맞춥니다."},{"slug":"express-emotions","title":"Express Emotions","type":"antonym","note":"감정을 겉으로 드러내거나 표출하는 것을 의미합니다."},{"slug":"wear-one-s-heart-on-one-s-sleeve","title":"Wear One\'s Heart On One\'s Sleeve","type":"antonym","note":"자신의 감정을 숨기지 않고 솔직하게 드러내는 것을 의미합니다."}],"date":"2025-11-24T00:01"}');
;// ./blog/on-the-fence/content.json
const on_the_fence_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"on-the-fence","title":"On The Fence","koreanPronunciation":"온 더 펜스","tags":["관용구","자주 쓰는 표현"],"meaning":"결정을 내리지 못하고 망설이거나 중립적인 태도를 취하는 것을 의미합니다","description":"이 표현은 울타리(fence) 위에 앉아 이쪽저쪽을 보며 어느 쪽으로 뛰어내릴지 망설이는 모습에서 유래했습니다. 명확한 입장을 정하지 못하고 중립적인 태도를 유지하거나 결정을 미루는 상황을 묘사할 때 사용됩니다. 중요한 선택의 기로에 서서 주저하는 상태를 나타낼 때 흔히 쓰입니다.","examples":[{"en":"I\'m still on the fence about whether to take the new job offer or not.","ko":"새로운 직업 제안을 받아들일지 말지 여전히 망설이고 있어요."},{"en":"The committee is on the fence about the proposed changes to the company policy.","ko":"위원회는 회사 정책 변경 제안에 대해 결정을 내리지 못하고 있습니다."},{"en":"You can\'t stay on the fence forever; you need to make a decision soon.","ko":"영원히 망설일 수 없어요; 곧 결정을 내려야 합니다."},{"en":"Many voters are still on the fence, trying to decide which candidate to support.","ko":"많은 유권자들이 어떤 후보를 지지할지 결정하기 위해 여전히 망설이고 있습니다."}],"related":[{"slug":"sit-on-the-sidelines","title":"Sit On The Sidelines","type":"synonym","note":"직접 참여하지 않고 관망하는 태도를 강조합니다."},{"slug":"waver-between","title":"Waver Between","type":"synonym","note":"두 가지 선택지 사이에서 흔들리는 것을 나타냅니다."},{"slug":"make-up-one-s-mind","title":"Make Up One\'s Mind","type":"antonym","note":"결심하다, 결정하다."},{"slug":"take-a-stand","title":"Take A Stand","type":"antonym","note":"확고한 입장을 취하다."}],"date":"2025-09-03T00:00"}');
