const miss_the_mark_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"miss-the-mark","title":"Miss The Mark","koreanPronunciation":"미스 더 마크","tags":["관용구","자주 쓰는 표현"],"meaning":"목표나 기대를 달성하지 못하거나 빗나가다라는 의미입니다.","description":"이 표현은 어떤 목적, 목표 또는 의도한 바를 이루는 데 실패했거나, 기대치에 미치지 못했을 때 사용됩니다. 원래는 사격이나 던지기 등에서 목표물(mark)을 맞히지 못하고 빗나가는 것을 의미했으나, 점차 비유적으로 확장되어 계획, 노력, 말 등이 예상했던 결과를 내지 못하거나 적절치 못했을 때 쓰이게 되었습니다.","examples":[{"en":"Our new marketing campaign unfortunately missed the mark and didn\'t attract new customers.","ko":"우리의 새로운 마케팅 캠페인은 불행히도 목표를 달성하지 못했고 새로운 고객을 유치하지 못했습니다."},{"en":"I tried to impress the boss, but my presentation totally missed the mark.","ko":"상사에게 깊은 인상을 주려 했지만, 제 발표는 완전히 빗나갔습니다."},{"en":"The director\'s latest film missed the mark with critics and audiences alike.","ko":"그 감독의 최신 영화는 비평가와 관객 모두에게 혹평을 받았습니다."},{"en":"He completely missed the mark when he tried to guess my age; I\'m much younger!","ko":"그는 내 나이를 추측하려 했을 때 완전히 빗나갔어. 나는 훨씬 어려!"}],"related":[{"slug":"fail-to-achieve","title":"Fail To Achieve","type":"synonym","note":"특정 목표나 결과를 이루는 데 실패하다."},{"slug":"fall-flat","title":"Fall Flat","type":"synonym","note":"기대했던 효과나 성공을 거두지 못하고 실패하다."},{"slug":"not-measure-up","title":"Not Measure Up","type":"synonym","note":"특정 기준이나 기대치에 미치지 못하다."},{"slug":"hit-the-target","title":"Hit The Target","type":"antonym","note":"목표나 목적을 정확히 달성하다."},{"slug":"meet-expectations","title":"Meet Expectations","type":"antonym","note":"기대치나 요구 사항을 충족시키다."}],"date":"2026-03-25T00:00"}');
