const strike_while_the_iron_is_hot_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"strike-while-the-iron-is-hot","title":"Strike While The Iron Is Hot","koreanPronunciation":"스트라이크 와일 더 아이언 이즈 핫","tags":["관용구","자주 쓰는 표현"],"meaning":"기회가 왔을 때 즉시 행동하여 이점을 취해야 한다는 의미입니다","description":"이 표현은 대장장이가 쇠를 달굴 때 뜨거울 때 두드려야 원하는 모양을 만들 수 있다는 것에서 유래했습니다. 무언가를 성공시키기 위해서는 적절한 때, 즉 기회가 주어졌을 때 망설이지 말고 즉시 행동해야 함을 강조합니다. 타이밍이 매우 중요하며, 기회를 놓치면 나중에 후회할 수 있음을 일깨워 줍니다.","examples":[{"en":"Don\'t wait too long to apply for that scholarship; you need to strike while the iron is hot.","ko":"그 장학금에 너무 오래 기다리지 말고 지원하세요. 기회가 있을 때 잡아야 해요."},{"en":"The market is booming, so it\'s a good time to invest. You should strike while the iron is hot.","ko":"시장이 호황이니 투자하기 좋은 시기입니다. 기회를 놓치지 말고 행동해야 합니다."},{"en":"The client seemed interested in our proposal. We should send them a follow-up email immediately and strike while the iron is hot.","ko":"고객이 우리 제안에 관심이 있는 것 같았습니다. 즉시 후속 이메일을 보내 기회를 잡아야 합니다."},{"en":"If you want to get tickets for the concert, you need to buy them now. They\'ll sell out fast, so strike while the iron is hot.","ko":"콘서트 표를 구하고 싶다면 지금 당장 사야 합니다. 빨리 매진될 테니, 기회를 잡으세요."}],"related":[{"slug":"carpe-diem","title":"Carpe Diem","type":"synonym","note":"기회를 포착하라는 의미에서 유사합니다."},{"slug":"make-hay-while-the-sun-shines","title":"Make Hay While The Sun Shines","type":"synonym","note":"좋은 여건일 때 이점을 취하라는 의미입니다."},{"slug":"hesitate-and-be-lost","title":"Hesitate And Be Lost","type":"antonym","note":"망설이면 기회를 잃는다는 의미로 반대되는 맥락입니다."},{"slug":"miss-the-boat","title":"Miss The Boat","type":"antonym","note":"기회를 놓치다는 의미로 반대됩니다."},{"slug":"procrastinate","title":"Procrastinate","type":"antonym","note":"일을 미루는 행위로, 즉시 행동하는 것과 반대됩니다."}],"date":"2025-10-28T00:01"}');
;// ./blog/hand-in/content.json
const hand_in_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"hand-in","title":"Hand In","koreanPronunciation":"핸드 인","tags":["구동사"],"meaning":"무언가를 권한이 있는 사람이나 기관에 제출하거나 건네주는 의미입니다.","description":"이 표현은 주로 과제, 서류, 사직서 등 공식적인 문서를 제출할 때 사용됩니다. 또한, 잃어버린 물건을 주인에게 돌려주거나 경찰서에 가져다줄 때와 같이, 어떤 물건을 물리적으로 전달하는 상황에서도 쓰일 수 있습니다. \'제출하다\', \'제공하다\', \'건네주다\' 등의 뉘앙스를 가집니다.","examples":[{"en":"I need to hand in my essay by Friday.","ko":"금요일까지 에세이를 제출해야 합니다."},{"en":"Did you hand in your resignation letter yet?","ko":"사직서를 아직 제출하지 않았나요?"},{"en":"Please hand in your exam papers before you leave the room.","ko":"방을 나가기 전에 시험지를 제출해 주세요."},{"en":"She found a lost wallet and decided to hand it in to the police.","ko":"그녀는 잃어버린 지갑을 발견하고 경찰에 가져다주기로 했습니다."},{"en":"All assignments must be handed in on time to avoid penalties.","ko":"모든 과제는 벌점을 피하기 위해 제시간에 제출되어야 합니다."}],"related":[{"slug":"submit","title":"Submit","type":"synonym","note":"공식적으로 서류, 제안서 등을 제출할 때 사용되는 일반적인 단어입니다."},{"slug":"turn-in","title":"Turn In","type":"synonym","note":"\'hand in\'과 유사하게 숙제나 서류 등을 제출할 때 자주 쓰이는 구동사입니다."},{"slug":"turn-over","title":"Turn Over","type":"synonym","note":"물건이나 책임 등을 다른 사람에게 넘겨주거나 양도하는 의미로 사용될 수 있습니다."}],"date":"2025-10-04T00:00"}');
;// ./blog/better-safe-than-sorry/content.json
const better_safe_than_sorry_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"better-safe-than-sorry","title":"Better Safe Than Sorry","koreanPronunciation":"베터 세이프 댄 소리","tags":["관용구","자주 쓰는 표현"],"meaning":"나중에 후회할 일을 예방하기 위해 미리 조심하는 것이 더 낫다는 의미입니다.","description":"이 표현은 앞으로 발생할 수 있는 잠재적인 위험이나 문제에 대비하여 미리 조심하거나 필요한 조치를 취하는 것이 중요하다는 점을 강조합니다. 즉, 나중에 후회하는 것보다 지금 안전하게 행동하는 것이 현명하다는 뜻으로 사용됩니다. 종종 사소한 불편함이나 추가적인 노력을 감수하더라도 만약의 사태에 대비해야 할 때 인용됩니다.","examples":[{"en":"I know it\'s extra work, but it\'s better safe than sorry to double-check all the files before sending them.","ko":"수고스럽겠지만, 파일을 보내기 전에 모두 다시 확인하는 것이 나중에 후회하는 것보다 낫습니다."},{"en":"Always wear a helmet when cycling; it\'s better safe than sorry.","ko":"자전거를 탈 때는 항상 헬멧을 착용하세요. 안전하게 행동하는 것이 후회하는 것보다 낫습니다."},{"en":"She packed an umbrella even though the sky was clear, thinking it\'s better safe than sorry.","ko":"하늘은 맑았지만, 그녀는 만약을 대비해 우산을 챙겼습니다."},{"en":"Let\'s get to the airport early. Better safe than sorry, given the long security lines.","ko":"공항에 일찍 가자. 긴 보안 검색대를 고려하면 미리 가서 나쁠 건 없어."},{"en":"You should back up your important data regularly. Better safe than sorry!","ko":"중요한 데이터는 정기적으로 백업해야 합니다. 나중에 후회하는 것보다 안전한 것이 낫습니다!"}],"related":[{"slug":"err-on-the-side-of-caution","title":"Err On The Side Of Caution","type":"synonym","note":"문제를 피하기 위해 조심스러운 접근 방식을 선택하다."},{"slug":"look-before-you-leap","title":"Look Before You Leap","type":"synonym","note":"행동하기 전에 신중하게 생각하고 결과를 고려해야 함을 강조."},{"slug":"prevention-is-better-than-cure","title":"Prevention Is Better Than Cure","type":"synonym","note":"문제가 발생하기 전에 예방하는 것이 더 낫다는 의미."},{"slug":"throw-caution-to-the-wind","title":"Throw Caution To The Wind","type":"antonym","note":"미래의 결과에 대한 걱정 없이 위험을 감수하고 대담하게 행동하다."},{"slug":"leap-before-you-look","title":"Leap Before You Look","type":"antonym","note":"충분히 생각하지 않고 성급하게 행동하다."}],"date":"2026-04-01T00:01"}');
;// ./blog/prepare-for/content.json
const prepare_for_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"prepare-for","title":"Prepare For","koreanPronunciation":"프리페어 포","tags":["구동사","자주 쓰는 표현"],"meaning":"어떤 일이나 상황에 대비하거나 준비하는 것의 의미입니다.","description":"이 표현은 앞으로 닥쳐올 사건, 상황, 또는 활동에 대비하여 필요한 조치를 취하거나 마음의 준비를 하는 것을 의미합니다. 주로 미래의 불확실한 상황이나 중요한 일에 앞서 미리 계획을 세우고 필요한 것을 갖추는 맥락에서 사용됩니다. 육체적, 정신적, 물질적 준비 모두를 포함할 수 있습니다.","examples":[{"en":"We need to prepare for the big presentation next week.","ko":"우리는 다음 주 중요한 발표를 위해 준비해야 합니다."},{"en":"The company is preparing for a new product launch.","ko":"회사는 신제품 출시를 준비하고 있습니다."},{"en":"You should prepare for any questions they might ask during the interview.","ko":"면접 중 그들이 물어볼 수 있는 어떤 질문에도 대비해야 합니다."},{"en":"The rescue team had to prepare for harsh weather conditions.","ko":"구조팀은 혹독한 날씨 조건에 대비해야 했습니다."},{"en":"It\'s always wise to prepare for the worst, but hope for the best.","ko":"항상 최악의 상황에 대비하되, 최고를 희망하는 것이 현명합니다."}],"related":[{"slug":"get-ready-for","title":"Get Ready For","type":"synonym"},{"slug":"brace-for","title":"Brace For","type":"synonym","note":"특히 힘든 상황에 대비하다"},{"slug":"plan-for","title":"Plan For","type":"synonym"},{"slug":"be-unprepared-for","title":"Be Unprepared For","type":"antonym"},{"slug":"be-caught-off-guard","title":"Be Caught Off Guard","type":"antonym","note":"예기치 못한 상황에 직면하다"}],"date":"2025-09-15T00:01"}');
;// ./blog/look-like/content.json
const look_like_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"look-like","title":"Look Like","koreanPronunciation":"룩 라이크","tags":["구동사","자주 쓰는 표현"],"meaning":"외모나 특성이 무엇인가와 비슷하거나, 어떤 상태인 것처럼 보인다는 의미입니다","description":"이 표현은 주로 사람이나 사물의 외모, 특성, 또는 현재의 상태나 분위기가 특정 대상이나 상황과 유사할 때 사용됩니다. 또한, 어떤 상황이 특정 결과를 초래할 것 같다는 예측을 나타낼 때도 사용될 수 있습니다. 비유적인 의미로 \'어떤 것처럼 보인다\'는 인상을 전달하는 데 매우 유용합니다.","examples":[{"en":"You look like your mother, especially around the eyes.","ko":"너는 특히 눈매가 너희 어머니를 닮았어."},{"en":"It looks like it\'s going to rain heavily this afternoon.","ko":"오늘 오후에는 비가 많이 올 것 같네요."},{"en":"He looks like he hasn\'t slept in days; he must be exhausted.","ko":"그는 며칠 동안 잠을 못 잔 것처럼 보여요. 많이 지쳤나 봐요."},{"en":"What does your new house look like from the outside?","ko":"새 집은 밖에서 보면 어떻게 생겼나요?"},{"en":"It looks like a great opportunity for us to expand our business.","ko":"우리 사업을 확장할 좋은 기회인 것 같아요."}],"related":[{"slug":"resemble","title":"resemble","note":"보다 격식 있는 표현으로, 주로 외모나 특성이 비슷할 때 사용됩니다."},{"slug":"take-after","title":"take after","note":"특히 자녀가 부모의 외모나 성격을 닮았을 때 사용되는 구동사입니다."},{"slug":"seem","title":"seem","note":"\'~인 것 같다\'는 의미로, 외모뿐 아니라 감정, 상태 등 전반적인 인상에 사용됩니다."},{"slug":"appear","title":"appear","note":"\'~처럼 보이다\'는 의미로, 시각적인 인상이나 어떤 사실이 명백해질 때 사용됩니다."}],"date":"2025-08-10T00:00"}');
;// ./blog/find-fault-with/content.json
const find_fault_with_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"find-fault-with","title":"Find Fault With","koreanPronunciation":"파인드 폴트 위드","tags":["관용구","구동사"],"meaning":"누군가나 어떤 것의 실수나 단점을 찾아내어 비판하거나 불평하다는 의미입니다.","description":"이 표현은 주로 다른 사람이나 어떤 사물의 결점, 단점, 또는 잘못된 부분을 찾아내어 지적하고 비판하거나 불평할 때 사용됩니다. 부정적인 뉘앙스를 가지며, 사소한 흠이나 작은 실수까지도 꼬집어 말하는 상황에서 흔히 쓰입니다.","examples":[{"en":"My boss always finds fault with my reports, no matter how hard I try.","ko":"내가 아무리 노력해도 상사는 항상 내 보고서에서 흠을 잡는다."},{"en":"Don\'t always find fault with others; try to see the good in them.","ko":"항상 남의 단점만 찾지 말고, 그들의 좋은 점을 보려고 노력해."},{"en":"Some people just enjoy finding fault with everything around them.","ko":"어떤 사람들은 그냥 주변 모든 것에서 흠을 찾는 것을 즐긴다."}],"related":[{"slug":"criticize","title":"Criticize","type":"synonym","note":"가장 일반적인 비판, 비난을 의미합니다."},{"slug":"nitpick","title":"Nitpick","type":"synonym","note":"사소한 흠이나 결점을 트집 잡는 것에 초점을 맞춥니다."},{"slug":"complain","title":"Complain","type":"synonym","note":"불만을 표현하는 행위를 나타냅니다."},{"slug":"praise","title":"Praise","type":"antonym","note":"누군가나 어떤 것을 칭찬하거나 좋게 평가하는 것입니다."}],"date":"2025-11-19T00:00"}');
;// ./blog/shirk-one-s-responsibilities/content.json
const shirk_one_s_responsibilities_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"shirk-one-s-responsibilities","title":"Shirk One\'s Responsibilities","koreanPronunciation":"셔크 원스 리스폰서빌리티스","tags":["관용구"],"meaning":"자신의 책임이나 의무를 회피하거나 소홀히 하는 것을 의미합니다.","description":"이 표현은 누군가가 마땅히 해야 할 역할이나 의무를 고의로 피하거나 제대로 수행하지 않을 때 사용됩니다. 특히, 책임감을 보여야 할 상황에서 무책임하게 행동하거나 부담스러운 일을 다른 사람에게 전가하려 할 때 이 표현을 통해 그러한 태도를 비판할 수 있습니다. 예를 들어, 맡은 프로젝트의 중요한 부분을 게을리하거나 어려운 결정을 피할 때 \'shirk one\'s responsibilities\'라고 말할 수 있습니다.","examples":[{"en":"He always tries to shirk his responsibilities at work, leaving extra tasks for his colleagues.","ko":"그는 직장에서 항상 자신의 책임을 회피하여 동료들에게 추가 업무를 남깁니다."},{"en":"Shirk your responsibilities, and you\'ll never achieve anything significant in your career.","ko":"책임을 회피하면 직업에서 결코 중요한 것을 성취할 수 없을 것입니다."},{"en":"A good leader never shirks their responsibilities, especially in a crisis.","ko":"좋은 리더는 특히 위기 상황에서 결코 자신의 책임을 회피하지 않습니다."},{"en":"Don\'t shirk your responsibility to vote in the upcoming election; your voice matters.","ko":"다가오는 선거에서 투표할 책임을 회피하지 마십시오. 당신의 목소리가 중요합니다."}],"related":[{"slug":"neglect-one-s-duties","title":"Neglect One\'s Duties","type":"synonym","note":"비슷하게 의무를 소홀히 하는 것을 의미합니다."},{"slug":"evade-responsibility","title":"Evade Responsibility","type":"synonym","note":"책임을 피한다는 직접적인 의미를 가집니다."},{"slug":"take-responsibility","title":"Take Responsibility","type":"antonym","note":"책임을 인정하고 수행하는 것과 반대되는 의미입니다."},{"slug":"shoulder-one-s-duties","title":"Shoulder One\'s Duties","type":"antonym","note":"책임을 떠맡고 수행한다는 의미로, 반대되는 표현입니다."}],"date":"2025-10-12T00:01"}');
;// ./blog/fall-short-of-expectations/content.json
const fall_short_of_expectations_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"fall-short-of-expectations","title":"Fall Short Of Expectations","koreanPronunciation":"폴 쇼트 오브 익스펙테이션스","tags":["관용구","자주 쓰는 표현"],"meaning":"기대에 미치지 못하거나 예상했던 수준에 도달하지 못했다는 의미입니다","description":"이 표현은 어떤 사람, 사물, 계획 또는 결과가 기대했던 것보다 좋지 않거나 목표한 바를 달성하지 못했을 때 사용됩니다. 주로 실망감을 표현할 때 쓰이며, 예상했던 기준이나 수준에 도달하지 못했음을 나타냅니다. 이는 종종 계획이나 약속이 제대로 이행되지 않았을 때의 결과를 설명하는 데 유용합니다.","examples":[{"en":"The company\'s quarterly earnings fell short of expectations due to unforeseen market changes.","ko":"예상치 못한 시장 변화로 인해 회사의 분기별 실적은 기대에 미치지 못했습니다."},{"en":"His performance in the final game fell short of expectations, much to the disappointment of his fans.","ko":"결승전에서 그의 경기력은 기대 이하였고, 팬들은 크게 실망했습니다."},{"en":"Despite heavy marketing, the new product fell short of expectations and sales were lower than projected.","ko":"대대적인 마케팅에도 불구하고, 신제품은 기대에 미치지 못했고 판매량은 예상보다 저조했습니다."},{"en":"The team\'s project fell short of expectations, leading to a significant delay in the product launch.","ko":"팀의 프로젝트는 기대에 미치지 못하여 제품 출시가 크게 지연되었습니다."}],"related":[{"slug":"not-meet-the-mark","title":"Not Meet The Mark","type":"synonym","note":"표준이나 기대치에 미치지 못하다는 의미로, \'fall short of expectations\'와 유사하게 사용됩니다."},{"slug":"fail-to-deliver","title":"Fail To Deliver","type":"synonym","note":"약속하거나 기대했던 것을 이행하지 못하다는 의미입니다."},{"slug":"underperform","title":"Underperform","type":"synonym","note":"예상보다 좋지 않은 성과를 내다라는 뜻입니다."},{"slug":"exceed-expectations","title":"Exceed Expectations","type":"antonym","note":"기대치를 뛰어넘는 성과를 내다라는 의미로, 반대되는 상황을 나타냅니다."},{"slug":"live-up-to-expectations","title":"Live Up To Expectations","type":"antonym","note":"기대에 부응하다, 기대만큼 잘 해내다는 의미로, \'fall short of expectations\'와 반대되는 표현입니다."}],"date":"2025-09-05T00:00"}');
;// ./blog/a-blessing-in-disguise/content.json
const a_blessing_in_disguise_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"a-blessing-in-disguise","title":"A Blessing in Disguise","koreanPronunciation":"어 블레싱 인 디스가이즈","tags":["관용구","자주 쓰는 표현"],"meaning":"겉으로는 불리해 보이지만 결과적으로는 좋은 결과를 가져오는 상황을 의미합니다","description":"이 표현은 어떤 불운하거나 부정적으로 보이는 사건이 장기적으로는 이로운 결과를 가져올 때 사용됩니다. 처음에는 나쁜 일처럼 보이지만, 시간이 지나면서 그것이 실제로는 좋은 기회나 긍정적인 변화의 계기가 되었음을 깨달을 때 이 표현을 사용합니다. 예를 들어, 해고당한 것이 새로운 직업을 찾게 된 계기가 되어 결국 더 만족스러운 삶을 살게 된 경우에 해당됩니다.","examples":[{"en":"Losing that job was a blessing in disguise because it led me to a much better opportunity.","ko":"그 직업을 잃은 것은 오히려 전화위복이었어, 왜냐하면 그것이 나를 훨씬 더 좋은 기회로 이끌었거든."},{"en":"The cancelled flight was a blessing in disguise, as I got to spend an extra day with my family.","ko":"취소된 항공편은 오히려 행운이었어, 가족과 하루 더 보낼 수 있었으니까."},{"en":"At first, failing that exam felt terrible, but it was a blessing in disguise because it made me reconsider my major.","ko":"처음에는 그 시험에 떨어진 것이 정말 끔찍했지만, 전공을 다시 생각하게 만든 전화위복이었어."},{"en":"Her illness was a blessing in disguise; it forced her to slow down and prioritize her health.","ko":"그녀의 병은 오히려 행운이었어. 그것이 그녀로 하여금 속도를 늦추고 건강을 우선시하게 만들었거든."}],"related":[{"slug":"make-the-best-of-a-bad-situation","title":"Make the Best of a Bad Situation","type":"synonym","note":"어려운 상황에서 최선을 다해 긍정적인 결과를 이끌어내는 것을 의미합니다."},{"slug":"turn-lemons-into-lemonade","title":"Turn Lemons into Lemonade","type":"synonym","note":"불운하거나 불쾌한 상황을 이점으로 바꾸는 것을 의미합니다."},{"slug":"phoenix-from-the-ashes","title":"Phoenix from the Ashes","type":"synonym","note":"재앙이나 실패 이후에 더 강하게 또는 아름답게 부활하는 것을 의미합니다."}],"date":"2025-07-23T00:00"}');
;// ./blog/burn-bridges/content.json
const burn_bridges_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"burn-bridges","title":"Burn Bridges","koreanPronunciation":"번 브릿지스","tags":["관용구"],"meaning":"과거의 관계나 기회를 끊어버려 되돌아갈 수 없게 만드는 의미입니다.","description":"이 표현은 어떤 관계나 상황, 또는 기회를 영구적으로 단절하여 다시는 되돌릴 수 없는 상태로 만드는 것을 비유적으로 나타냅니다. 주로 과거의 직장, 친구 관계, 혹은 특정 상황에서 완전히 손을 떼는 경우에 사용되며, 이는 신중하게 결정해야 할 중요한 행동임을 암시합니다.","examples":[{"en":"Don\'t burn your bridges when you leave your old job; you might need them for a reference later.","ko":"이전 직장을 떠날 때 다리를 불태우지 마세요. 나중에 추천서가 필요할 수도 있습니다."},{"en":"After the argument, she decided to burn her bridges with her former best friend.","ko":"논쟁 후에, 그녀는 옛 가장 친한 친구와의 관계를 끊어버리기로 결정했습니다."},{"en":"He knew if he quit without notice, he would be burning his bridges with the company.","ko":"그는 예고 없이 그만두면 회사와 관계를 끊어버리게 될 것을 알고 있었습니다."},{"en":"It\'s never a good idea to burn bridges in your professional network.","ko":"직업적인 인맥에서 관계를 끊어버리는 것은 결코 좋은 생각이 아닙니다."}],"related":[{"slug":"sever-ties","title":"Sever Ties","type":"synonym","note":"관계나 연결을 단절한다는 유사한 의미입니다."},{"slug":"cut-off-all-contact","title":"Cut Off All Contact","type":"synonym","note":"모든 연락을 끊어버린다는 직접적인 유사 표현입니다."},{"slug":"mend-fences","title":"Mend Fences","type":"antonym","note":"갈등을 해결하고 관계를 회복한다는 반대 의미입니다."}],"date":"2025-09-22T00:00"}');
;// ./blog/backseat-driver/content.json
const backseat_driver_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"backseat-driver","title":"Backseat Driver","koreanPronunciation":"백시트 드라이버","tags":["관용구","속어","자주 쓰는 표현"],"meaning":"운전 중이 아니더라도 다른 사람의 일에 불필요하게 참견하거나 지시하는 사람을 의미입니다.","description":"이 표현은 운전 중에 뒷좌석에 앉아 운전자에게 이래라저래라 지시하거나 간섭하는 사람의 행동에서 유래했습니다. 실제 운전 상황뿐만 아니라, 어떤 일을 진행하는 과정에서 불필요하게 간섭하거나 조언을 남발하여 방해가 되는 사람을 비유적으로 지칭할 때 사용됩니다. 일반적으로 부정적인 뉘앙스를 가지며, 듣는 사람을 짜증 나게 할 수 있는 상황을 묘사할 때 적합합니다.","examples":[{"en":"My mother is such a backseat driver whenever I drive her car.","ko":"우리 엄마는 내가 차를 운전할 때마다 정말 잔소리꾼이다."},{"en":"I don\'t need a backseat driver when I\'m trying to figure out this problem.","ko":"이 문제를 해결하려고 할 때 불필요한 참견꾼은 필요 없어."},{"en":"He\'s always being a backseat driver, telling me how to do my job.","ko":"그는 항상 참견꾼처럼 내 업무 방식에 대해 이래라저래라 한다."},{"en":"Can you stop being a backseat driver and let me concentrate?","ko":"잔소리 좀 그만하고 내가 집중하게 해줄래?"}],"related":[{"slug":"meddler","title":"Meddler","type":"synonym","note":"다른 사람의 일에 불필요하게 간섭하는 사람을 지칭합니다."},{"slug":"busybody","title":"Busybody","type":"synonym","note":"다른 사람의 사생활이나 일에 지나치게 참견하는 사람을 의미합니다."},{"slug":"control-freak","title":"Control Freak","type":"synonym","note":"모든 것을 자신의 통제 하에 두려 하는 사람을 가리킵니다."}],"date":"2025-11-13T00:00"}');
