const dissent_from_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"dissent-from","title":"Dissent From","koreanPronunciation":"디센트 프롬","tags":["구동사","자주 쓰는 표현"],"meaning":"특정 의견, 결정 또는 지배적인 견해에 동의하지 않고 반대 의견을 표명하는 것의미입니다","description":"이 표현은 주로 공식적이거나 공적인 맥락에서 어떤 정책, 결정, 법률, 또는 다수의 의견에 반대하는 입장을 명확히 밝힐 때 사용됩니다. 단순히 \'동의하지 않는다\'는 것을 넘어, 적극적으로 이의를 제기하고 다른 입장을 취하는 행위를 나타냅니다. 종종 소수의 의견이나 비판적인 시각을 표현할 때 쓰입니다.","examples":[{"en":"Several board members chose to dissent from the CEO\'s proposal regarding the merger.","ko":"몇몇 이사회 구성원들은 합병에 대한 CEO의 제안에 반대하기로 결정했습니다."},{"en":"The judge\'s dissenting opinion clearly articulated his reasons for disagreement with the majority ruling.","ko":"판사의 반대 의견은 다수결에 대한 그의 동의하지 않는 이유를 명확하게 설명했습니다."},{"en":"It\'s important for employees to feel they can dissent from company policies without fear of retribution.","ko":"직원들이 보복에 대한 두려움 없이 회사 정책에 반대할 수 있다고 느끼는 것이 중요합니다."},{"en":"She felt compelled to dissent from the committee\'s final recommendation due to ethical concerns.","ko":"그녀는 윤리적인 문제 때문에 위원회의 최종 권고에 반대할 수밖에 없다고 느꼈습니다."}],"related":[{"slug":"disagree-with","title":"Disagree With","type":"synonym","note":"일반적으로 어떤 의견이나 사실에 대해 동의하지 않음을 나타내는 가장 흔한 표현."},{"slug":"object-to","title":"Object To","type":"synonym","note":"특정 제안이나 계획에 대해 강한 반대나 항의를 표명할 때 사용되며, 때로는 공식적인 이의 제기를 의미."},{"slug":"protest-against","title":"Protest Against","type":"synonym","note":"부당하다고 생각하는 것에 대해 공개적으로 반대하거나 항의하는 행위."},{"slug":"concur-with","title":"Concur With","type":"antonym","note":"어떤 의견이나 결정에 전적으로 동의하고 지지함을 의미."}],"date":"2025-11-17T00:01"}');
;// ./blog/under-the-gun/content.json
const under_the_gun_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"under-the-gun","title":"Under the Gun","koreanPronunciation":"언더 더 건","tags":["관용구","자주 쓰는 표현"],"meaning":"큰 압박이나 긴급한 상황에 처해 있다는 의미입니다","description":"이 표현은 무언가를 서둘러 해야 하거나, 강력한 압력에 직면했을 때 사용됩니다. 비유적으로 총구 아래에 있는 것처럼 위험하거나 절박한 상황을 묘사합니다. 주로 시간적 압박, 외부로부터의 강요, 또는 어려운 결정을 내려야 하는 상황 등에서 쓰입니다.","examples":[{"en":"We\'re really under the gun to finish this project by Friday.","ko":"우리는 금요일까지 이 프로젝트를 끝내야 한다는 큰 압박에 시달리고 있어요."},{"en":"The team is under the gun to deliver results quickly after the recent merger.","ko":"그 팀은 최근 합병 이후 빠르게 결과를 내야 하는 압박을 받고 있습니다."},{"en":"With the deadline looming, I feel like I\'m constantly under the gun.","ko":"마감일이 다가오면서, 저는 계속 압박감에 시달리는 것 같아요."},{"en":"The manager put him under the gun to improve sales figures.","ko":"관리자는 그에게 판매 수치를 개선하라고 압박했습니다."},{"en":"Being under the gun can sometimes make you more productive.","ko":"압박감에 시달리는 것이 때로는 생산성을 더 높일 수도 있습니다."}],"related":[{"slug":"under-pressure","title":"Under Pressure","type":"synonym","note":"유사한 의미로, 특정 상황이나 요구로 인한 압박을 나타냅니다."},{"slug":"against-the-clock","title":"Against the Clock","type":"synonym","note":"시간적 압박이 매우 강하다는 것을 강조할 때 사용됩니다."},{"slug":"on-a-tight-deadline","title":"On a Tight Deadline","type":"synonym","note":"주로 마감 시간에 대한 강한 압박을 구체적으로 나타냅니다."},{"slug":"have-ample-time","title":"Have Ample Time","type":"antonym","note":"시간에 쫓기지 않고 여유가 많다는 의미입니다."},{"slug":"be-at-ease","title":"Be at Ease","type":"antonym","note":"압박감 없이 편안하고 느긋한 상태를 나타냅니다."}],"date":"2026-03-14T00:01"}');
;// ./blog/put-ones-nose-to-the-grindstone/content.json
const put_ones_nose_to_the_grindstone_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"put-ones-nose-to-the-grindstone","title":"Put One\'s Nose To The Grindstone","koreanPronunciation":"풋 원스 노즈 투 더 그라인드스톤","tags":["관용구","자주 쓰는 표현"],"meaning":"매우 열심히, 꾸준히, 그리고 성실하게 일하거나 공부한다는 의미입니다.","description":"이 표현은 맷돌에 코를 대고 곡물을 갈듯이, 힘든 일이나 지루한 일을 끈기 있고 집중적으로 하는 모습을 비유합니다. 주로 어떤 목표를 달성하기 위해 꾸준히 노력하고 몰두할 때 사용됩니다. 고된 노동이나 학업에 전념하는 상황에 적합합니다.","examples":[{"en":"If you want to pass the exam, you need to put your nose to the grindstone.","ko":"시험에 합격하고 싶다면, 열심히 공부해야 해."},{"en":"She put her nose to the grindstone for months to finish her novel.","ko":"그녀는 소설을 완성하기 위해 몇 달 동안 끈기 있게 작업했다."},{"en":"The team knew they had to put their noses to the grindstone to meet the deadline.","ko":"팀은 마감일을 맞추기 위해 열심히 일해야 한다는 것을 알았다."},{"en":"It\'s time to stop procrastinating and put your nose to the grindstone.","ko":"이제 미루는 것을 멈추고 열심히 노력해야 할 때야."}],"related":[{"slug":"toil-away","title":"Toil Away","type":"synonym","note":"힘들게 꾸준히 일하다는 의미로, 물리적인 노력을 강조합니다."},{"slug":"roll-up-ones-sleeves","title":"Roll Up One\'s Sleeves","type":"synonym","note":"본격적으로 열심히 일할 준비를 하거나 실제로 일을 시작하는 것을 나타냅니다."},{"slug":"keep-at-it","title":"Keep At It","type":"synonym","note":"어려움에도 불구하고 어떤 일을 계속해서 노력하고 끈기 있게 해나가는 것을 의미합니다."}],"date":"2026-04-08T00:01"}');
;// ./blog/overcome-adversity/content.json
const overcome_adversity_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"overcome-adversity","title":"Overcome Adversity","koreanPronunciation":"오버컴 애드버시티","tags":["자주 쓰는 표현"],"meaning":"어려움이나 역경을 극복하고 이겨내는 것을 의미합니다.","description":"이 표현은 삶에서 직면하는 어려운 상황, 불행, 고난 등을 인내심과 강인함으로 이겨내고 성공하는 과정을 설명할 때 사용됩니다. 단순한 문제를 해결하는 것을 넘어, 정신적, 신체적 어려움을 넘어설 때 주로 쓰이며, 강한 의지와 긍정적인 태도를 강조합니다.","examples":[{"en":"Despite facing numerous setbacks, she managed to overcome adversity and achieve her dreams.","ko":"수많은 좌절에도 불구하고, 그녀는 역경을 극복하고 꿈을 이루어냈습니다."},{"en":"It takes great courage to overcome adversity and emerge stronger.","ko":"역경을 극복하고 더 강해지기 위해서는 큰 용기가 필요합니다."},{"en":"The team\'s ability to overcome adversity was key to their championship victory.","ko":"팀이 역경을 극복하는 능력은 그들의 챔피언십 우승에 핵심이었습니다."},{"en":"History is full of stories of individuals who overcame adversity through sheer determination.","ko":"역사는 순전한 결단력으로 역경을 극복한 개인들의 이야기로 가득합니다."},{"en":"She learned to overcome adversity with resilience and a positive outlook.","ko":"그녀는 회복력과 긍정적인 전망으로 역경을 극복하는 법을 배웠습니다."}],"related":[{"slug":"persevere-through-hardship","title":"Persevere Through Hardship","type":"synonym","note":"어려움을 참고 견디며 꾸준히 노력하는 것에 초점을 맞춥니다."},{"slug":"rise-above-challenges","title":"Rise Above Challenges","type":"synonym","note":"도전을 넘어서 더 높은 차원으로 나아가는 의미를 강조합니다."},{"slug":"weather-the-storm","title":"Weather The Storm","type":"synonym","note":"어려운 시기나 위기를 견뎌내는 것을 비유적으로 표현합니다."},{"slug":"succumb-to-difficulty","title":"Succumb To Difficulty","type":"antonym","note":"어려움에 굴복하거나 지는 것을 의미합니다."},{"slug":"be-defeated-by-challenges","title":"Be Defeated By Challenges","type":"antonym","note":"도전에 의해 패배하거나 좌절하는 상태를 나타냅니다."}],"date":"2026-03-19T00:00"}');
;// ./blog/in-sync/content.json
const in_sync_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"in-sync","title":"In Sync","koreanPronunciation":"인 싱크","tags":["관용구","자주 쓰는 표현"],"meaning":"조화를 이루거나 잘 맞아서 동시에 또는 일치하게 움직이는 것의 의미입니다.","description":"이 표현은 둘 이상의 사람이나 사물이 완벽하게 조화를 이루거나 같은 방식으로 기능하고 있음을 나타낼 때 사용됩니다. 리듬, 움직임, 생각, 일정 등 다양한 상황에서 일치성과 협력을 강조할 때 쓸 수 있습니다. 예를 들어, 댄서들이 음악에 맞춰 완벽하게 움직이거나, 팀원들이 같은 목표를 향해 협력하는 상황 등에 적용될 수 있습니다.","examples":[{"en":"The dancers were perfectly in sync with the music.","ko":"무용수들은 음악과 완벽하게 조화를 이루었습니다."},{"en":"Our team\'s ideas are usually in sync, which makes collaboration easy.","ko":"우리 팀의 아이디어는 보통 일치해서 협업하기 쉽습니다."},{"en":"It\'s important for a couple to be in sync on major life decisions.","ko":"커플이 중요한 인생 결정에 대해 서로 마음이 맞는 것이 중요합니다."},{"en":"After practicing for months, their movements were finally in sync.","ko":"몇 달 연습한 후에 그들의 움직임은 마침내 완벽하게 조화되었습니다."}],"related":[{"slug":"in-harmony","title":"In Harmony","type":"synonym","note":"서로 조화롭게 어울리는 상태를 나타냅니다."},{"slug":"aligned","title":"Aligned","type":"synonym","note":"목표나 생각 등이 일치하거나 정렬된 상태를 의미합니다."},{"slug":"coordinated","title":"Coordinated","type":"synonym","note":"움직임이나 행동 등이 서로 잘 조정된 상태를 나타냅니다."},{"slug":"out-of-sync","title":"Out of Sync","type":"antonym","note":"서로 조화롭지 않거나 일치하지 않는 상태를 의미합니다."}],"date":"2026-01-04T00:00"}');
