const hold_your_tongue_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"hold-your-tongue","title":"Hold Your Tongue","koreanPronunciation":"홀드 유어 텅","tags":["관용구","자주 쓰는 표현"],"meaning":"입을 다물고 침묵하며 할 말을 삼가는 의미입니다.","description":"이 표현은 화가 나거나 부적절한 말을 할 상황에서 자신을 통제하고 말하지 않음을 나타낼 때 사용됩니다. 특히 무례하거나 후회할 만한 발언을 피하기 위해 침묵하는 상황을 강조합니다.","examples":[{"en":"I wanted to argue, but I decided to hold my tongue.","ko":"논쟁하고 싶었지만, 입을 다물기로 결정했습니다."},{"en":"She was told to hold her tongue and let the manager handle it.","ko":"그녀는 입을 다물고 매니저가 처리하도록 하라는 말을 들었습니다."},{"en":"It\'s sometimes better to hold your tongue than to say something you\'ll regret.","ko":"후회할 말을 하는 것보다 때로는 침묵하는 것이 더 낫습니다."},{"en":"If you don\'t have anything nice to say, just hold your tongue.","ko":"좋은 말을 할 것이 없으면, 그냥 입을 다무세요."}],"related":[{"slug":"bite-your-tongue","title":"Bite Your Tongue","type":"synonym","note":"후회할 만한 말을 하려다가 억지로 참는다는 뉘앙스가 더 강합니다."},{"slug":"keep-quiet","title":"Keep Quiet","type":"synonym"},{"slug":"zip-your-lip","title":"Zip Your Lip","type":"synonym","note":"비격식적인 표현으로, \'입 다물어!\'와 비슷합니다."},{"slug":"speak-up","title":"Speak Up","type":"antonym","note":"자신의 의견이나 생각을 말하는 것을 의미합니다."}],"date":"2026-03-15T00:00"}');
;// ./blog/let-it-slide/content.json
const let_it_slide_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"let-it-slide","title":"Let It Slide","koreanPronunciation":"렛 잇 슬라이드","tags":["관용구","자주 쓰는 표현"],"meaning":"어떤 실수나 잘못을 못 본 척하거나 용서하고 넘어가주는 의미입니다.","description":"이 표현은 누군가의 실수, 잘못된 행동, 또는 무례함 등을 인지하고 있음에도 불구하고, 그것을 문제 삼지 않고 넘어가기로 결정할 때 사용됩니다. 보통 관계의 중요성, 상황의 사소함, 또는 갈등을 피하려는 의도 등 여러 이유로 인해 사용될 수 있습니다. 심각한 문제보다는 비교적 경미한 사안에 대해 주로 쓰이며, 너그러움이나 관용을 베푸는 태도를 나타냅니다.","examples":[{"en":"He made a small mistake, but I decided to let it slide this time.","ko":"그가 작은 실수를 했지만, 이번에는 그냥 넘어가기로 했다."},{"en":"Don\'t let every little thing slide; sometimes you need to address issues.","ko":"사소한 모든 것을 그냥 넘기지 마세요. 가끔은 문제를 해결해야 합니다."},{"en":"I know you forgot my birthday, but I\'ll let it slide.","ko":"네가 내 생일을 잊은 건 알지만, 그냥 넘어갈게."},{"en":"Her comment was a bit rude, but I chose to let it slide.","ko":"그녀의 말은 약간 무례했지만, 나는 그냥 넘어가기로 했다."}],"related":[{"slug":"turn-a-blind-eye","title":"Turn a Blind Eye","type":"synonym","note":"어떤 잘못이나 문제점을 알면서도 못 본 척하거나 모른 척하다."},{"slug":"overlook","title":"Overlook","type":"synonym","note":"실수나 잘못 등을 간과하거나 묵인하다."},{"slug":"call-someone-out","title":"Call Someone Out","type":"antonym","note":"누군가의 잘못이나 부적절한 행동을 공개적으로 지적하다."},{"slug":"hold-someone-accountable","title":"Hold Someone Accountable","type":"antonym","note":"누군가에게 행동에 대한 책임을 묻거나 지게 하다."}],"date":"2025-10-31T00:00"}');
;// ./blog/race-against-time/content.json
const race_against_time_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"race-against-time","title":"Race Against Time","koreanPronunciation":"레이스 어게인스트 타임","tags":["관용구"],"meaning":"정해진 시간 안에 어떤 일을 매우 급박하게 서둘러야 하는 상황을 의미합니다.","description":"이 표현은 특정 목표를 달성하기 위해 제한된 시간 내에 빠르게 행동해야 하는 긴박하고 압박감 있는 상황을 묘사할 때 사용됩니다. 주로 마감 기한이 임박했거나, 긴급한 상황에서 빠르게 조치해야 할 필요성을 강조할 때 쓰입니다. 마치 시간과 경쟁하듯이 서두르는 모습을 나타냅니다.","examples":[{"en":"We\'re in a race against time to finish the project before the deadline.","ko":"우리는 마감일 전에 프로젝트를 마치기 위해 시간과의 싸움을 하고 있다."},{"en":"The doctors were in a race against time to save the patient\'s life.","ko":"의사들은 환자의 생명을 구하기 위해 시간과의 싸움을 벌였다."},{"en":"Developing a vaccine was a global race against time during the pandemic.","ko":"백신을 개발하는 것은 팬데믹 동안 전 세계적인 시간과의 싸움이었다."},{"en":"With only an hour left, it became a real race against time to prepare everything for the event.","ko":"단 한 시간만 남았기에, 행사 준비를 모두 마치기 위한 진정한 시간과의 싸움이 되었다."}],"related":[{"slug":"work-against-the-clock","title":"Work Against The Clock","type":"synonym","note":"시간에 쫓겨 급하게 일한다는 의미로 매우 유사합니다."},{"slug":"be-pressed-for-time","title":"Be Pressed For Time","type":"synonym","note":"시간이 부족하여 서둘러야 하는 상황을 나타냅니다."},{"slug":"take-one-s-time","title":"Take One\'s Time","type":"antonym","note":"급하지 않게 여유를 가지고 일을 한다는 반대 의미입니다."}],"date":"2026-03-14T00:00"}');
;// ./blog/put-the-brakes-on/content.json
const put_the_brakes_on_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"put-the-brakes-on","title":"Put The Brakes On","koreanPronunciation":"풋 더 브레이크스 온","tags":["관용구"],"meaning":"무언가의 진행을 멈추거나 속도를 늦추는 의미입니다.","description":"이 표현은 자동차의 브레이크를 밟아 속도를 줄이거나 완전히 멈추는 행위에서 유래했습니다. 주로 어떤 활동, 프로젝트, 계획 또는 추세의 속도를 늦추거나 일시적으로 중단할 때 비유적으로 사용됩니다. 신중한 접근이 필요하거나 상황을 재평가해야 할 때 자주 쓰입니다.","examples":[{"en":"We need to put the brakes on this project until we get more funding.","ko":"더 많은 자금을 확보할 때까지 이 프로젝트의 진행을 멈춰야 합니다."},{"en":"The government decided to put the brakes on the new policy after public backlash.","ko":"정부는 대중의 반발 이후 새 정책 추진을 중단하기로 결정했습니다."},{"en":"If you feel overwhelmed, it\'s okay to put the brakes on and take a break.","ko":"압도감을 느낀다면, 잠시 멈추고 휴식을 취하는 것도 괜찮습니다."},{"en":"The manager had to put the brakes on the team\'s spending to avoid overbudgeting.","ko":"매니저는 예산 초과를 막기 위해 팀의 지출을 억제해야 했습니다."}],"related":[{"slug":"slow-down","title":"Slow Down","type":"synonym"},{"slug":"hold-off","title":"Hold Off","type":"synonym","note":"진행을 잠시 보류하거나 연기하다는 뉘앙스."},{"slug":"pump-the-brakes","title":"Pump The Brakes","type":"synonym","note":"속도를 줄이거나 신중하게 진행하라는 구어체 표현."},{"slug":"speed-up","title":"Speed Up","type":"antonym"},{"slug":"step-on-the-gas","title":"Step On The Gas","type":"antonym","note":"서두르거나 진행 속도를 높이다."}],"date":"2025-09-09T00:00"}');
;// ./blog/keep-someone-at-arms-length/content.json
const keep_someone_at_arms_length_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"keep-someone-at-arms-length","title":"Keep Someone At Arm\'s Length","koreanPronunciation":"킵 썸원 앳 암스 렝스","tags":["관용구"],"meaning":"누군가와 거리를 두거나 친밀해지지 않도록 하는 것을 의미합니다.","description":"이 표현은 물리적인 거리뿐만 아니라 감정적인 거리감을 유지하여 특정 사람과 지나치게 가깝게 지내지 않으려는 태도를 나타낼 때 사용됩니다. 이는 상대방을 신뢰하지 않거나, 개인적인 공간을 지키고 싶을 때, 혹은 복잡한 관계에 얽히고 싶지 않을 때 쓸 수 있습니다. 주로 경계심을 가지고 사람을 대하는 상황에서 쓰입니다.","examples":[{"en":"After being betrayed, she decided to keep everyone at arm\'s length for a while.","ko":"배신당한 후, 그녀는 한동안 모든 사람과 거리를 두기로 결정했다."},{"en":"He\'s friendly with his colleagues, but he always keeps them at arm\'s length.","ko":"그는 동료들과는 친하지만, 항상 그들과 거리를 둡니다."},{"en":"It\'s hard to get to know him because he keeps everyone at arm\'s length.","ko":"그는 모두와 거리를 두기 때문에 그를 알아가기가 어렵습니다."},{"en":"You should keep people you don\'t fully trust at arm\'s length.","ko":"완전히 신뢰하지 않는 사람들과는 거리를 두는 것이 좋습니다."}],"related":[{"slug":"hold-at-bay","title":"Hold At Bay","type":"synonym","note":"어떤 것을 가까이 오지 못하게 막다"},{"slug":"keep-ones-distance","title":"Keep One\'s Distance","type":"synonym","note":"신체적 또는 감정적 거리를 유지하다"},{"slug":"befriend","title":"Befriend","type":"antonym","note":"누구와 친구가 되다"},{"slug":"get-close-to","title":"Get Close To","type":"antonym","note":"누구와 가까워지다"}],"date":"2026-02-08T00:00"}');
