const in_harmony_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"in-harmony","title":"In Harmony","koreanPronunciation":"인 하모니","tags":["관용구","자주 쓰는 표현"],"meaning":"조화롭거나 동의하는 상태에 있는 것을 의미합니다.","description":"이 표현은 사람, 사물 또는 생각 등이 서로 잘 어울리거나 의견이 일치하여 평화로운 상태를 나타낼 때 사용됩니다. 갈등 없이 순조롭게 협력하거나 공존하는 상황을 묘사할 때 적합하며, 보통 \'함께\' 또는 \'서로\'라는 뉘앙스를 내포합니다.","examples":[{"en":"The different sections of the orchestra played in harmony.","ko":"오케스트라의 각 파트가 조화롭게 연주했다."},{"en":"Despite their different backgrounds, the couple lived in harmony.","ko":"서로 다른 배경에도 불구하고, 그 부부는 조화롭게 살았다."},{"en":"We need to work in harmony to achieve our common goal.","ko":"우리의 공동 목표를 달성하기 위해 우리는 조화롭게 협력해야 한다."},{"en":"Their voices blended perfectly in harmony, creating a beautiful sound.","ko":"그들의 목소리는 완벽하게 조화를 이루어 아름다운 소리를 만들어냈다."}],"related":[{"slug":"in-agreement","title":"In Agreement","type":"synonym","note":"의견이나 생각이 일치함을 강조합니다."},{"slug":"in-sync","title":"In Sync","type":"synonym","note":"행동이나 리듬이 잘 맞는 상태를 나타냅니다."},{"slug":"united","title":"United","type":"synonym","note":"목표나 목적을 위해 함께 뭉친 상태를 의미합니다."},{"slug":"at-odds","title":"At Odds","type":"antonym","note":"서로 의견이 다르거나 불화가 있는 상태를 나타냅s니다."},{"slug":"in-conflict","title":"In Conflict","type":"antonym","note":"직접적인 갈등이나 싸움이 있는 상태를 의미합니다."}],"date":"2026-01-04T00:01"}');
;// ./blog/add-fuel-to-the-fire/content.json
const add_fuel_to_the_fire_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"add-fuel-to-the-fire","title":"Add Fuel To The Fire","koreanPronunciation":"애드 퓨얼 투 더 파이어","tags":["관용구","자주 쓰는 표현"],"meaning":"상황을 더 악화시키거나 문제를 더 크게 만드는 것의미입니다.","description":"이 표현은 이미 좋지 않거나 논쟁이 있는 상황에 더 자극적인 말이나 행동을 더하여 문제를 더욱 악화시키는 것을 비유적으로 이르는 말입니다. 마치 불에 기름을 부으면 불길이 더 거세지는 것처럼, 사태를 더 통제 불능으로 만들 때 사용됩니다. 의도적이든 아니든, 기존의 갈등이나 문제를 심화시키는 행위를 묘사합니다.","examples":[{"en":"Please don\'t mention his ex-girlfriend; it would just add fuel to the fire.","ko":"제발 그의 전 여자친구 이야기는 꺼내지 마. 그건 그냥 불에 기름을 붓는 격일 테니까."},{"en":"Their argument was already heated, and his sarcastic comment only added fuel to the fire.","ko":"그들의 논쟁은 이미 뜨거웠는데, 그의 비꼬는 말이 불난 집에 부채질하는 격이 되었다."},{"en":"Instead of trying to calm things down, she kept criticizing him, which only added fuel to the fire.","ko":"상황을 진정시키려고 노력하는 대신, 그녀는 계속 그를 비난했고, 이는 불에 기름을 붓는 격이 되었다."},{"en":"Cutting their budget during a crisis will only add fuel to the fire of public discontent.","ko":"위기 상황에서 예산을 삭감하는 것은 대중의 불만에 기름을 부을 뿐이다."}],"related":[{"slug":"make-matters-worse","title":"Make Matters Worse","type":"synonym","note":"비슷하게 상황을 더 나쁘게 만든다는 의미"},{"slug":"exacerbate-the-situation","title":"Exacerbate the Situation","type":"synonym","note":"더 공식적인 표현으로 상황을 악화시키다는 의미"},{"slug":"inflame-the-situation","title":"Inflame the Situation","type":"synonym","note":"감정이나 분노를 격화시켜 상황을 악화시킨다는 의미"},{"slug":"pour-oil-on-troubled-waters","title":"Pour Oil on Troubled Waters","type":"antonym","note":"갈등을 진정시키고 화해시킨다는 반대 의미"}],"date":"2025-09-10T00:00"}');
;// ./blog/get-your-act-together/content.json
const get_your_act_together_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"get-your-act-together","title":"Get Your Act Together","koreanPronunciation":"겟 유어 액트 투게더","tags":["자주 쓰는 표현","관용구"],"meaning":"자신의 행동이나 상황을 정리하고 개선하며, 더 책임감 있고 효율적으로 행동하라는 의미입니다.","description":"이 표현은 주로 누군가가 무질서하거나 비효율적인 방식으로 행동하여 좋지 않은 결과를 초래할 때, 더 책임감 있고 조직적인 모습을 보일 것을 촉구하거나 스스로 행동을 개선할 필요가 있음을 강조할 때 사용됩니다. 목표 달성을 위해 계획을 세우고 실행해야 할 필요성을 나타내기도 합니다.","examples":[{"en":"You need to get your act together if you want to pass this exam.","ko":"이 시험에 통과하고 싶으면 정신 차리고 제대로 준비해야 해."},{"en":"After being fired, he realized he needed to get his act together and find a new job.","ko":"해고당한 후, 그는 정신을 차리고 새로운 직장을 찾아야 한다는 것을 깨달았다."},{"en":"The team really needs to get their act together before the big game next week.","ko":"팀은 다음 주 큰 경기를 앞두고 정말 전열을 가다듬어야 합니다."},{"en":"Stop procrastinating and get your act together to finish the project.","ko":"미루는 것을 멈추고 프로젝트를 끝내기 위해 정신을 똑바로 차려라."}],"related":[{"slug":"shape-up","title":"Shape Up","type":"synonym","note":"더 나은 행동이나 태도를 가지도록 개선하라는 의미로, 주로 경고의 뉘앙스를 포함합니다."},{"slug":"pull-yourself-together","title":"Pull Yourself Together","type":"synonym","note":"감정적으로 혼란스럽거나 동요할 때 침착함을 되찾고 평정심을 유지하라는 의미입니다."},{"slug":"clean-up-your-act","title":"Clean Up Your Act","type":"synonym","note":"나쁜 습관이나 부적절한 행동을 고쳐서 더 바람직한 방식으로 행동하라는 의미입니다."},{"slug":"mess-up","title":"Mess Up","type":"antonym","note":"일을 그르치거나 상황을 엉망으로 만들다는 의미로, \'Get Your Act Together\'와는 반대되는 개념입니다."}],"date":"2025-11-02T00:00"}');
;// ./blog/in-good-times-and-bad/content.json
const in_good_times_and_bad_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"in-good-times-and-bad","title":"In Good Times And Bad","koreanPronunciation":"인 굿 타임즈 앤 배드","tags":["관용구","자주 쓰는 표현"],"meaning":"좋을 때나 나쁠 때나, 어떤 상황에서든 함께 한다는 의미입니다.","description":"이 표현은 삶의 모든 면, 즉 기쁠 때나 힘들 때를 포함하여 어떤 상황에서든 변함없이 지지하고 함께 한다는 것을 강조합니다. 특히 관계나 약속의 지속성을 나타낼 때 사용됩니다.","examples":[{"en":"She promised to stand by him in good times and bad.","ko":"그녀는 좋을 때나 나쁠 때나 그를 곁에서 지켜주겠다고 약속했다."},{"en":"Our friendship has endured in good times and bad.","ko":"우리 우정은 좋을 때나 나쁠 때나 변함없이 지속되었다."},{"en":"A true partner supports you in good times and bad.","ko":"진정한 동반자는 좋을 때나 나쁠 때나 당신을 지지합니다."},{"en":"They built their business together, through good times and bad.","ko":"그들은 좋을 때나 나쁠 때나 함께 사업을 일궈나갔다."}],"related":[{"slug":"through-thick-and-thin","title":"Through Thick And Thin","type":"synonym","note":"좋을 때나 나쁠 때나, 어떤 어려움에도 불구하고"},{"slug":"come-what-may","title":"Come What May","type":"synonym","note":"무슨 일이 있어도"},{"slug":"for-better-or-worse","title":"For Better Or Worse","type":"synonym","note":"좋든 나쁘든 (주로 결혼 서약에서 사용)"}],"date":"2025-07-20T00:00"}');
;// ./blog/what-are-you-thinking-about/content.json
const what_are_you_thinking_about_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"what-are-you-thinking-about","title":"What Are You Thinking About?","koreanPronunciation":"왓 아 유 띵킹 어바웃?","tags":["자주 쓰는 표현","문장"],"meaning":"상대방의 생각이나 현재 몰두하고 있는 것에 대해 묻는 것의 의미입니다.","description":"이 표현은 상대방이 현재 어떤 생각을 하고 있는지, 무엇에 몰두하고 있는지 궁금할 때 사용하는 아주 흔한 질문입니다. 주로 대화의 시작이나 상대방이 멍하니 있거나 특정 상황에 대해 깊이 생각하는 것처럼 보일 때 사용됩니다. 상대방의 내면을 알고 싶거나 대화를 이끌어 나갈 때 유용하게 쓰입니다.","examples":[{"en":"You look deep in thought. What are you thinking about?","ko":"생각에 잠긴 것 같네요. 무슨 생각하세요?"},{"en":"After a long silence, she finally asked, \\"What are you thinking about?\\"","ko":"긴 침묵 끝에 그녀는 마침내 \\"무슨 생각해?\\"라고 물었다."},{"en":"He had a strange expression on his face. \\"What are you thinking about?\\" she wondered.","ko":"그는 이상한 표정을 짓고 있었다. 그녀는 \'무슨 생각하는 걸까?\' 하고 궁금해했다."},{"en":"Tell me, what are you thinking about right now?","ko":"말해봐, 지금 무슨 생각하고 있어?"}],"related":[{"slug":"whats-on-your-mind","title":"What\'s on your mind?","type":"synonym","note":"상대방의 생각이나 걱정을 묻는 매우 유사한 표현입니다."},{"slug":"a-penny-for-your-thoughts","title":"A penny for your thoughts","type":"synonym","note":"상대방이 생각하는 것을 말해보라고 요청하는 관용적인 표현입니다."},{"slug":"whats-bothering-you","title":"What\'s bothering you?","type":"synonym","note":"상대방을 괴롭히거나 걱정시키는 것이 무엇인지 물을 때 사용합니다."}],"date":"2025-08-22T00:00"}');
;// ./blog/take-office/content.json
const take_office_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"take-office","title":"Take Office","koreanPronunciation":"테이크 오피스","tags":["자주 쓰는 표현","연어"],"meaning":"취임하거나 공직을 시작하는 것을 의미합니다.","description":"이 표현은 주로 선출되거나 임명된 공직자들이 공식적으로 자신의 직무를 시작하는 상황에서 사용됩니다. 대통령, 국회의원, 시장 등과 같이 중요한 직책의 사람이 새로 임기를 시작할 때 이 표현을 씁니다. 단순히 새로운 직업을 시작하는 것을 넘어, 공식적인 역할과 책임을 맡는다는 의미가 강하며, 보통 특정 날짜나 행사를 기점으로 이루어집니다.","examples":[{"en":"The new president will take office in January.","ko":"새로운 대통령은 1월에 취임할 것입니다."},{"en":"She is expected to take office as governor next month.","ko":"그녀는 다음 달에 주지사로 취임할 것으로 예상됩니다."},{"en":"When does the newly elected mayor take office?","ko":"새로 선출된 시장은 언제 취임하나요?"},{"en":"He will take office after the formal ceremony.","ko":"그는 공식적인 의식 후에 취임할 것입니다."}],"related":[{"slug":"assume-office","title":"Assume Office","type":"synonym","note":"직무를 맡다, 취임하다. \'Take office\'보다 다소 격식 있는 표현입니다."},{"slug":"be-sworn-in","title":"Be Sworn In","type":"synonym","note":"취임 선서를 하고 공식적으로 직무를 시작하다는 의미로, \'take office\'와 유사하게 사용됩니다."},{"slug":"leave-office","title":"Leave Office","type":"antonym","note":"직책에서 물러나다, 퇴임하다는 의미입니다."},{"slug":"step-down","title":"Step Down","type":"antonym","note":"직책에서 사임하거나 물러나다. 주로 자진해서 직위에서 물러나는 경우에 사용됩니다."}],"date":"2025-10-27T00:00"}');
;// ./blog/a-trustworthy-person/content.json
const a_trustworthy_person_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"a-trustworthy-person","title":"A Trustworthy Person","koreanPronunciation":"어 트러스트워디 퍼슨","tags":["자주 쓰는 표현","연어"],"meaning":"믿을 수 있고 신뢰할 만한 사람을 의미합니다.","description":"이 표현은 어떤 사람이 정직하고, 책임감이 있으며, 약속을 잘 지켜 타인이 안심하고 의지할 수 있음을 나타낼 때 사용됩니다. 신뢰는 관계와 사회생활에서 매우 중요한 가치이며, \'a trustworthy person\'은 그러한 긍정적인 특성을 가진 사람을 칭찬하는 말로 쓰입니다. 보통 오랜 시간 동안 검증된 행동과 일관된 태도를 통해 신뢰를 쌓은 사람에게 적용됩니다.","examples":[{"en":"He\'s always been a trustworthy person, so I have no doubt he\'ll handle the money responsibly.","ko":"그는 항상 믿을 수 있는 사람이었으니, 돈을 책임감 있게 처리할 것이라고 확신합니다."},{"en":"It\'s important to have a trustworthy person to confide in, especially during difficult times.","ko":"특히 어려운 시기에는 털어놓을 수 있는 믿을 만한 사람이 있는 것이 중요합니다."},{"en":"Our team leader is a trustworthy person; you can rely on her judgment and discretion.","ko":"우리 팀 리더는 믿을 수 있는 사람입니다. 그녀의 판단과 신중함을 믿을 수 있어요."},{"en":"Finding a trustworthy person to care for your children is a top priority for parents.","ko":"자녀를 돌볼 믿을 수 있는 사람을 찾는 것은 부모들에게 최우선 과제입니다."}],"related":[{"slug":"a-reliable-person","title":"A Reliable Person","type":"synonym","note":"일관성 있게 의지할 수 있는 사람을 강조합니다."},{"slug":"a-dependable-person","title":"A Dependable Person","type":"synonym","note":"약속을 지키고 기대를 충족시키는 사람을 의미합니다."},{"slug":"an-honest-person","title":"An Honest Person","type":"synonym","note":"거짓말을 하지 않고 진실을 말하는 사람을 강조합니다."},{"slug":"an-untrustworthy-person","title":"An Untrustworthy Person","type":"antonym","note":"신뢰할 수 없는, 믿을 수 없는 사람을 의미합니다."},{"slug":"a-deceitful-person","title":"A Deceitful Person","type":"antonym","note":"남을 속이거나 기만하는 경향이 있는 사람을 의미합니다."}],"date":"2026-04-05T00:01"}');
;// ./blog/get-back-on-track/content.json
const get_back_on_track_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"get-back-on-track","title":"Get Back On Track","koreanPronunciation":"겟 백 온 트랙","tags":["구동사","자주 쓰는 표현"],"meaning":"본래의 궤도로 돌아가다, 다시 정상적인 상태로 돌아오다의 의미입니다.","description":"이 표현은 일, 계획, 또는 어떤 상황이 잠시 중단되거나 잘못된 방향으로 흘러갔을 때, 원래 목표나 정상적인 진행 상태로 되돌아오는 것을 의미합니다. 주로 개인의 습관, 프로젝트 진행, 건강 관리 등 다양한 맥락에서 사용될 수 있습니다. 방향을 잃었거나 문제가 발생했을 때 다시 올바른 경로를 찾아가는 과정을 나타냅니다.","examples":[{"en":"After a challenging week, I need to get back on track with my diet and exercise routine.","ko":"힘든 한 주를 보낸 후, 저는 식단과 운동 루틴을 다시 정상 궤도로 돌려놓아야 합니다."},{"en":"The project went off schedule, but we\'re working hard to get back on track by the end of the month.","ko":"프로젝트가 예정보다 늦어졌지만, 우리는 이달 말까지 다시 정상 궤도에 오르기 위해 열심히 노력하고 있습니다."},{"en":"He took a break from his studies, but now he\'s determined to get back on track and graduate on time.","ko":"그는 학업에서 잠시 휴식을 취했지만, 이제는 다시 정상 궤도로 돌아와 제때 졸업하기로 결심했습니다."},{"en":"Let\'s discuss how we can get the team back on track after this setback.","ko":"이 차질 이후에 팀을 어떻게 다시 정상 궤도에 올릴 수 있을지 논의해 봅시다."},{"en":"I felt a bit lost after the move, but I\'m slowly getting back on track with my new life.","ko":"이사 후에 약간 길을 잃은 기분이었지만, 이제 새로운 삶에 점차 적응하고 있습니다."}],"related":[{"slug":"right-the-ship","title":"Right The Ship","type":"synonym","note":"문제를 해결하고 상황을 바로잡다"},{"slug":"pick-up-the-pieces","title":"Pick Up The Pieces","type":"synonym","note":"어려운 상황 후에 상황을 수습하고 재건하다"},{"slug":"return-to-normal","title":"Return To Normal","type":"synonym","note":"평범한 상태로 되돌아가다"},{"slug":"go-off-track","title":"Go Off Track","type":"antonym","note":"정상 궤도를 벗어나다"},{"slug":"fall-behind","title":"Fall Behind","type":"antonym","note":"일정이나 기대치에 미치지 못하다"}],"date":"2026-01-27T00:00"}');
;// ./blog/give-one-s-all/content.json
const give_one_s_all_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"give-one-s-all","title":"Give One\'s All","koreanPronunciation":"기브 원스 올","tags":["관용구","자주 쓰는 표현"],"meaning":"자신이 가진 모든 힘과 노력을 다한다는 의미입니다.","description":"이 표현은 어떤 일이나 목표를 위해 개인이 가진 모든 에너지, 재능, 그리고 노력을 쏟아붓는 것을 나타냅니다. 특히 어려움에 직면했을 때나 중요한 순간에 최대한의 열정과 헌신을 다하는 상황에서 자주 사용됩니다. 단순히 노력하는 것을 넘어, 한계를 뛰어넘어 최선을 다하는 적극적인 태도를 강조합니다.","examples":[{"en":"She gave her all to finish the marathon, even though she was exhausted.","ko":"그녀는 지쳐 있었음에도 불구하고 마라톤을 완주하기 위해 모든 것을 바쳤다."},{"en":"If you want to succeed in this competition, you have to give your all.","ko":"이 대회에서 성공하고 싶다면, 너의 모든 것을 쏟아부어야 해."},{"en":"The team gave their all, but they still lost the game.","ko":"팀은 모든 것을 쏟아부었지만, 여전히 경기에서 졌다."},{"en":"He promised to give his all to make the project a success.","ko":"그는 프로젝트를 성공시키기 위해 모든 것을 바치겠다고 약속했다."}],"related":[{"slug":"do-one-s-best","title":"Do One\'s Best","type":"synonym"},{"slug":"go-all-out","title":"Go All Out","type":"synonym"},{"slug":"spare-no-effort","title":"Spare No Effort","type":"synonym"},{"slug":"hold-back","title":"Hold Back","type":"antonym","note":"최선을 다하지 않고 노력을 아낀다는 의미에서 반의어입니다."}],"date":"2025-09-26T00:01"}');
;// ./blog/scarcely-ever/content.json
const scarcely_ever_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"scarcely-ever","title":"Scarcely Ever","koreanPronunciation":"스캐슬리 에버","tags":["자주 쓰는 표현"],"meaning":"거의 ~하지 않거나 드물게 일어난다는 의미입니다","description":"이 표현은 어떤 행동이나 사건이 거의 발생하지 않거나 그 빈도가 매우 낮음을 강조할 때 사용됩니다. 부정적인 뉘앙스를 가지며, 일반적인 기대보다 훨씬 적은 빈도를 나타낼 때 쓰입니다. \'hardly ever\', \'rarely\', \'seldom\' 등과 유사하게 사용됩니다.","examples":[{"en":"She scarcely ever goes out on weekdays; she prefers to relax at home.","ko":"그녀는 주중에는 거의 외출하지 않고, 집에서 쉬는 것을 선호합니다."},{"en":"We scarcely ever see them anymore since they moved to a different city.","ko":"그들이 다른 도시로 이사 간 후로는 우리는 그들을 거의 보지 못합니다."},{"en":"He scarcely ever complains, even when faced with difficult situations.","ko":"그는 어려운 상황에 직면했을 때조차도 거의 불평하지 않습니다."},{"en":"Such opportunities scarcely ever come along, so you should seize this chance.","ko":"그런 기회는 좀처럼 오지 않으니, 이 기회를 잡아야 합니다."}],"related":[{"slug":"hardly-ever","title":"Hardly Ever","type":"synonym","note":"거의 동일한 의미로 사용됩니다."},{"slug":"rarely","title":"Rarely","type":"synonym","note":"어떤 일이 드물게 발생함을 나타냅니다."},{"slug":"seldom","title":"Seldom","type":"synonym","note":"어떤 일이 거의 발생하지 않음을 나타내는 문어체 표현입니다."},{"slug":"often","title":"Often","type":"antonym","note":"자주, 빈번하게 발생함을 나타냅니다."}],"date":"2025-09-11T00:00"}');
;// ./blog/take-it-as-it-comes/content.json
const take_it_as_it_comes_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"take-it-as-it-comes","title":"Take It As It Comes","koreanPronunciation":"테이크 잇 애즈 잇 컴스","tags":["관용구","자주 쓰는 표현"],"meaning":"미래의 일을 미리 계획하거나 걱정하지 않고, 생기는 대로 받아들이고 대처하는 것의 의미입니다.","description":"이 표현은 앞으로 닥쳐올 일이나 상황에 대해 미리 불안해하거나 과도하게 준비하기보다는, 그때그때 상황에 맞춰 유연하게 대처하라는 조언을 담고 있습니다. 통제할 수 없는 미래에 대한 걱정을 줄이고 현재에 집중하며 스트레스를 덜 받는 태도를 강조할 때 사용됩니다. 불확실한 상황에서 침착하고 여유로운 마음가짐을 가질 것을 권장하는 표현입니다.","examples":[{"en":"Don\'t worry too much about the future; just take it as it comes.","ko":"미래에 대해 너무 걱정하지 마세요. 그냥 생기는 대로 받아들이세요."},{"en":"We don\'t have a strict plan for the trip; we\'ll just take it as it comes.","ko":"여행에 대한 엄격한 계획은 없어요. 그냥 상황에 따라 움직일 거예요."},{"en":"Life is unpredictable, so it\'s best to take it as it comes.","ko":"인생은 예측할 수 없으니, 그냥 생기는 대로 받아들이는 것이 최선입니다."},{"en":"She\'s good at taking things as they come, which helps her stay calm under pressure.","ko":"그녀는 상황을 있는 그대로 받아들이는 데 능숙해서 압박감 속에서도 침착함을 유지합니다."}],"related":[{"slug":"let-things-be","title":"Let Things Be","type":"synonym","note":"상황을 있는 그대로 받아들이거나 두다."},{"slug":"not-sweat-the-small-stuff","title":"Not Sweat The Small Stuff","type":"synonym","note":"사소한 일에 지나치게 걱정하거나 신경 쓰지 않다."},{"slug":"be-prepared-for-anything","title":"Be Prepared For Anything","type":"antonym","note":"어떤 돌발 상황에도 철저히 대비하다."},{"slug":"overthink-things","title":"Overthink Things","type":"antonym","note":"어떤 일에 대해 지나치게 많이 생각하고 걱정하다."}],"date":"2026-04-11T00:00"}');
;// ./blog/get-down-to-brass-tacks/content.json
const get_down_to_brass_tacks_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"get-down-to-brass-tacks","title":"Get Down To Brass Tacks","koreanPronunciation":"겟 다운 투 브라스 택스","tags":["관용구","자주 쓰는 표현"],"meaning":"불필요한 이야기나 세부 사항을 제쳐두고 가장 중요하고 실질적인 문제나 핵심으로 들어가다...의미입니다.","description":"이 표현은 문제의 본질이나 가장 중요한 부분에 직접적으로 접근하자는 의미로 사용됩니다. \'brass tacks\'는 원래 건축이나 가구 제작에서 사용되는 작은 황동 못을 의미하는데, 이는 견고하고 실용적인 기초를 상징합니다. 따라서 \'Get down to brass tacks\'는 비유적으로 \'본론으로 들어가다\', \'핵심을 다루다\'는 뜻이 되었습니다. 주로 시간 낭비를 피하고 효율적으로 논의를 진행할 때 사용됩니다.","examples":[{"en":"Let\'s get down to brass tacks and discuss the budget for the new project.","ko":"본론으로 들어가서 새 프로젝트 예산을 논의합시다."},{"en":"Enough with the small talk; it\'s time to get down to brass tacks and solve this problem.","ko":"잡담은 그만하고, 이제 본론으로 들어가서 이 문제를 해결할 시간입니다."},{"en":"If we want to finish on time, we need to get down to brass tacks and focus on what\'s important.","ko":"시간 내에 끝내려면, 핵심을 다루고 중요한 것에 집중해야 합니다."},{"en":"The meeting went on for hours, but we finally got down to brass tacks and made a decision.","ko":"회의는 몇 시간 동안 계속되었지만, 우리는 마침내 핵심을 논의하여 결정을 내렸습니다."}],"related":[{"slug":"talk-turkey","title":"Talk Turkey","type":"synonym","note":"솔직하게 본론을 이야기하다"},{"slug":"address-the-main-issue","title":"Address The Main Issue","type":"synonym","note":"주요 문제를 다루다"},{"slug":"focus-on-the-essentials","title":"Focus On The Essentials","type":"synonym","note":"필수적인 것에 집중하다"},{"slug":"dance-around-the-subject","title":"Dance Around The Subject","type":"antonym","note":"핵심을 회피하며 돌려 말하다"},{"slug":"mince-words","title":"Mince Words","type":"antonym","note":"말을 얼버무리거나 완곡하게 하다"}],"date":"2025-10-24T00:00"}');
;// ./blog/put-all-your-eggs-in-one-basket/content.json
const put_all_your_eggs_in_one_basket_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"put-all-your-eggs-in-one-basket","title":"Put All Your Eggs In One Basket","koreanPronunciation":"풋 올 유어 에그스 인 원 바스켓","tags":["관용구","자주 쓰는 표현"],"meaning":"모든 자원, 노력 또는 희망을 한 가지 계획이나 투자에만 집중시켜, 그것이 실패할 경우 모든 것을 잃을 위험을 감수하는 것의 의미입니다","description":"이 표현은 비유적으로 모든 달걀을 하나의 바구니에 담으면, 바구니가 떨어질 때 모든 달걀이 깨질 수 있다는 경고에서 유래했습니다. 즉, 투자, 사업, 계획 등 어떤 영역에서든 위험을 분산시키지 않고 한 가지에만 모든 것을 걸지 말라는 조언을 할 때 사용됩니다. 신중하게 접근하고 다양한 대안을 고려하는 것의 중요성을 강조합니다.","examples":[{"en":"It\'s risky to put all your eggs in one basket; you should diversify your investments.","ko":"모든 달걀을 한 바구니에 담는 것은 위험해요. 투자를 분산해야 합니다."},{"en":"She put all her eggs in one basket by only applying to one dream university, which worried her parents.","ko":"그녀는 오직 한 곳의 꿈의 대학에만 지원함으로써 모든 것을 걸었고, 이는 부모님을 걱정시켰습니다."},{"en":"When starting a new business, try not to put all your eggs in one basket with a single client.","ko":"새 사업을 시작할 때는 한 명의 고객에게만 모든 것을 걸지 않도록 노력하세요."},{"en":"He learned a hard lesson about putting all his eggs in one basket when his main project failed.","ko":"그는 주요 프로젝트가 실패했을 때 모든 것을 한 가지에만 거는 것에 대한 뼈아픈 교훈을 얻었습니다."}],"related":[{"slug":"go-all-in","title":"Go All In","type":"synonym","note":"모든 것을 걸고 어떤 일에 전적으로 헌신한다는 의미에서 유사하지만, \'put all your eggs in one basket\'는 보통 경고의 뉘앙스가 강합니다."},{"slug":"stake-everything-on","title":"Stake Everything On","type":"synonym","note":"한 가지 특정 결과에 모든 것을 걸어 위험을 감수한다는 점에서 유사합니다."},{"slug":"diversify","title":"Diversify","type":"antonym","note":"위험을 줄이기 위해 투자나 자원을 여러 곳으로 분산한다는 의미로, 정반대의 행동을 나타냅니다."},{"slug":"hedge-your-bets","title":"Hedge Your Bets","type":"antonym","note":"잠재적인 손실을 최소화하기 위해 여러 가능성을 고려하거나 위험을 분산시킨다는 의미에서 반대됩니다."}],"date":"2025-09-26T00:00"}');
;// ./blog/stay-tight-lipped/content.json
const stay_tight_lipped_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"stay-tight-lipped","title":"Stay Tight-Lipped","koreanPronunciation":"스테이 타이트-립트","tags":["관용구"],"meaning":"비밀을 지키고 아무 말도 하지 않거나, 침묵을 지키는 것을 의미합니다.","description":"이 표현은 어떤 정보나 비밀에 대해 말하지 않고 침묵을 지키는 행동을 묘사할 때 사용됩니다. 주로 중요한 비밀이나 민감한 정보를 보호해야 할 때 쓰이며, 입술을 꽉 다물고 아무것도 말하지 않는 모습에서 유래했습니다. 누군가에게 특정 사실을 말하지 말라고 경고하거나, 자신이 비밀을 지키고 있다는 것을 나타낼 때 유용하게 쓰입니다.","examples":[{"en":"The detective advised the witness to stay tight-lipped about what she saw until the trial.","ko":"형사는 증인에게 재판 전까지 목격한 것에 대해 입을 다물라고 조언했습니다."},{"en":"I\'m trying to stay tight-lipped about the surprise party, but it\'s hard!","ko":"저는 깜짝 파티에 대해 비밀을 지키려고 노력 중인데, 정말 어렵네요!"},{"en":"Even under pressure, she managed to stay tight-lipped and not reveal any company secrets.","ko":"압박 속에서도 그녀는 끝까지 입을 다물고 회사 비밀을 하나도 누설하지 않았습니다."},{"en":"Can you promise to stay tight-lipped if I tell you something confidential?","ko":"제가 기밀 정보를 알려드리면 비밀을 지키겠다고 약속해 주실 수 있나요?"}],"related":[{"slug":"clam-up","title":"Clam Up","type":"synonym","note":"갑자기 말을 멈추고 침묵하는 것을 강조합니다."},{"slug":"hold-ones-tongue","title":"Hold One\'s Tongue","type":"synonym","note":"하고 싶은 말을 참는다는 뉘앙스가 있습니다."},{"slug":"keep-quiet","title":"Keep Quiet","type":"synonym","note":"비밀을 지키거나 소음을 내지 않는다는 의미로 사용됩니다."},{"slug":"blurt-out","title":"Blurt Out","type":"antonym","note":"생각 없이 불쑥 말하거나 비밀을 누설하는 것을 의미합니다."},{"slug":"let-slip","title":"Let Slip","type":"antonym","note":"부주의하게 비밀이나 정보를 누설하는 것을 의미합니다."}],"date":"2025-10-06T00:01"}');
;// ./blog/drag-one-s-feet/content.json
const drag_one_s_feet_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"drag-one-s-feet","title":"Drag One\'s Feet","koreanPronunciation":"드래그 원스 피트","tags":["관용구"],"meaning":"어떤 일을 고의로 지연시키거나 느리게 행동하는 것을 의미합니다","description":"이 표현은 문자 그대로 발을 질질 끌며 걷는 모습에서 유래했습니다. 주로 어떤 일이나 결정에 대해 망설이거나, 하기 싫어서 고의적으로 행동을 늦출 때 사용됩니다. 이는 책임을 회피하거나, 불편한 상황을 피하려는 심리를 나타내기도 합니다. 종종 부정적인 의미로 쓰이며, 생산성 저하 또는 기회 상실로 이어질 수 있습니다.","examples":[{"en":"The government is dragging its feet on implementing the new environmental regulations.","ko":"정부는 새로운 환경 규제 이행에 시간을 끌고 있습니다."},{"en":"If you keep dragging your feet on this project, we\'ll miss the deadline.","ko":"이 프로젝트에 계속 시간을 끌면 마감일을 놓칠 거예요."},{"en":"She tends to drag her feet when it comes to doing chores she dislikes.","ko":"그녀는 싫어하는 집안일을 할 때 시간을 끄는 경향이 있습니다."},{"en":"Don\'t drag your feet; we need to make a decision quickly.","ko":"시간 끌지 마세요; 우리는 빨리 결정을 내려야 합니다."}],"related":[{"slug":"procrastinate","title":"Procrastinate","type":"synonym","note":"\'drag one\'s feet\'는 종종 의도적인 지연이나 망설임을 포함하지만, \'procrastinate\'는 단순히 일을 미루는 것을 의미합니다."},{"slug":"dawdle","title":"Dawdle","type":"synonym","note":"목표 없이 시간을 낭비하며 꾸물거리는 행동을 강조합니다."},{"slug":"dilly-dally","title":"Dilly-dally","type":"synonym","note":"꾸물거리거나 시간을 낭비하는 것을 의미하며, 비격식적이고 유쾌한 뉘앙스를 가집니다."},{"slug":"expedite","title":"Expedite","type":"antonym","note":"\'drag one\'s feet\'와 반대로 일을 신속하게 처리하고 가속화하는 것을 의미합니다."},{"slug":"hasten","title":"Hasten","type":"antonym","note":"서두르거나 가속화하는 행동으로, \'drag one\'s feet\'와 대조됩니다."}],"date":"2025-11-18T00:00"}');
;// ./blog/when-pigs-fly/content.json
const when_pigs_fly_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"when-pigs-fly","title":"When Pigs Fly","koreanPronunciation":"웬 피그스 플라이","tags":["관용구"],"meaning":"절대 일어나지 않을 일이거나 가능성이 거의 없는 상황을 비유하는 의미입니다.","description":"이 표현은 돼지가 날아다니는 것이 불가능한 것처럼, 어떤 일이 절대 일어날 수 없다는 것을 강조할 때 사용됩니다. 주로 비현실적이거나 터무니없는 기대에 대해 회의적인 반응을 보이거나 비꼬는 뉘앙스로 쓰입니다.","examples":[{"en":"He said he\'d clean his room when pigs fly.","ko":"그는 돼지가 날 때 방을 청소하겠다고 말했다 (즉, 절대 안 하겠다는 뜻)."},{"en":"I\'ll believe you\'re getting a promotion when pigs fly.","ko":"네가 승진한다는 건 돼지가 날 때나 믿을게."},{"en":"She\'ll apologize for her mistake when pigs fly.","ko":"그녀가 자신의 실수에 대해 사과하는 건 절대 없을 거야."},{"en":"My boss giving us a raise? When pigs fly!","ko":"우리 사장님이 월급을 올려준다고? 어림없는 소리!"}],"related":[{"slug":"not-a-snowball-s-chance-in-hell","title":"Not A Snowball\'s Chance In Hell","type":"synonym","note":"지옥에 눈덩이가 있을 리 없다는 뜻으로, 가능성이 전혀 없음을 강조합니다."},{"slug":"a-cold-day-in-hell","title":"A Cold Day In Hell","type":"synonym","note":"지옥이 추워지는 것처럼 불가능한 일을 나타냅니다."},{"slug":"impossible-feat","title":"Impossible Feat","type":"synonym","note":"이룰 수 없는 위업, 불가능한 일을 지칭하는 일반적인 표현입니다."}],"date":"2026-03-01T00:00"}');
;// ./blog/neglect-one-s-duties/content.json
const neglect_one_s_duties_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"neglect-one-s-duties","title":"Neglect One\'s Duties","koreanPronunciation":"네글렉트 원스 듀티스","tags":["연어","자주 쓰는 표현"],"meaning":"본인의 책임이나 해야 할 일을 소홀히 하거나 하지 않는 것을 의미합니다","description":"이 표현은 특정 개인이나 단체가 자신에게 부여된 의무, 책임 또는 임무를 제대로 수행하지 않거나 아예 무시하는 상황을 묘사할 때 사용됩니다. 이는 부주의, 게으름, 무관심 등 다양한 이유로 발생할 수 있으며, 종종 부정적인 결과를 초래합니다. 예를 들어, 직원이 업무를 태만히 하거나, 부모가 자녀를 제대로 돌보지 않거나, 정부 관료가 공공의 의무를 저버릴 때 이 표현을 쓸 수 있습니다.","examples":[{"en":"He was fired for consistently neglecting his duties.","ko":"그는 지속적으로 자신의 임무를 태만히 하여 해고되었다."},{"en":"Many people criticized the mayor for neglecting her duties during the crisis.","ko":"많은 사람들이 시장이 위기 동안 자신의 의무를 소홀히 한 것에 대해 비난했다."},{"en":"A good leader never neglects his or her duties, even when faced with difficulties.","ko":"좋은 지도자는 어려움에 직면하더라도 자신의 임무를 절대 소홀히 하지 않는다."},{"en":"Neglecting one\'s duties can have serious consequences for the entire team.","ko":"자신의 임무를 게을리하는 것은 팀 전체에 심각한 결과를 초래할 수 있다."}],"related":[{"slug":"shirk-one-s-responsibilities","title":"Shirk One\'s Responsibilities","type":"synonym","note":"책임을 회피하거나 게을리하는 것에 중점"},{"slug":"fail-to-carry-out-one-s-duties","title":"Fail to Carry Out One\'s Duties","type":"synonym","note":"직접적으로 임무를 수행하지 못함을 의미"},{"slug":"slack-off","title":"Slack Off","type":"synonym","note":"업무나 노력에 태만해지는 비격식적인 표현"},{"slug":"fulfill-one-s-duties","title":"Fulfill One\'s Duties","type":"antonym","note":"자신의 의무를 충실히 이행하다"},{"slug":"carry-out-one-s-responsibilities","title":"Carry Out One\'s Responsibilities","type":"antonym","note":"자신의 책임을 수행하다"}],"date":"2025-10-12T00:01"}');
;// ./blog/speak-ones-mind/content.json
const speak_ones_mind_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"speak-ones-mind","title":"Speak One\'s Mind","koreanPronunciation":"스피크 원스 마인드","tags":["관용구","자주 쓰는 표현"],"meaning":"자신의 생각이나 의견을 솔직하고 거리낌 없이 말하다는 의미입니다.","description":"이 표현은 다른 사람의 반응을 신경 쓰지 않고 자신의 솔직한 견해나 감정을 표현하는 것을 의미합니다. 때로는 듣는 사람이 불편해할 수 있는 내용이라도 자신의 신념이나 주장을 명확하게 밝히는 용기 있는 행동을 나타낼 때 사용됩니다. 일반적으로 긍정적인 의미로 쓰여 용기나 진실성을 강조하지만, 지나치게 직설적이어서 예의 없게 비춰질 수도 있는 상황에서도 쓰일 수 있습니다.","examples":[{"en":"She always speaks her mind, which sometimes gets her into trouble.","ko":"그녀는 항상 자신의 생각을 솔직하게 말하는데, 때로는 그것 때문에 곤란을 겪기도 한다."},{"en":"Don\'t be afraid to speak your mind if you disagree with the decision.","ko":"그 결정에 동의하지 않는다면, 주저하지 말고 솔직하게 말하세요."},{"en":"He spoke his mind about the new company policy during the meeting.","ko":"그는 회의에서 새로운 회사 정책에 대해 자신의 의견을 솔직하게 말했다."},{"en":"It\'s important to speak your mind respectfully, even when expressing a strong opinion.","ko":"강한 의견을 표현할 때도 정중하게 자신의 생각을 말하는 것이 중요합니다."}],"related":[{"slug":"call-a-spade-a-spade","title":"Call A Spade A Spade","type":"synonym","note":"어떤 상황이나 사람을 직설적이고 솔직하게 있는 그대로 표현할 때 사용됩니다."},{"slug":"tell-it-like-it-is","title":"Tell It Like It Is","type":"synonym","note":"상황을 꾸밈없이 솔직하게, 객관적으로 말하는 것을 강조합니다."},{"slug":"not-mince-words","title":"Not Mince Words","type":"synonym","note":"불쾌하거나 불편한 진실이라도 회피하거나 에둘러 말하지 않고 직설적으로 전달할 때 사용됩니다."},{"slug":"sugarcoat-something","title":"Sugarcoat Something","type":"antonym","note":"불쾌하거나 부정적인 것을 더 좋게 보이거나 들리도록 꾸며서 말하는 것을 의미합니다."},{"slug":"hold-one-s-tongue","title":"Hold One\'s Tongue","type":"antonym","note":"말하고 싶은 것이 있어도 자제하고 침묵을 지키는 것을 나타냅니다."}],"date":"2025-08-30T00:01"}');
;// ./blog/rush-to-judgment/content.json
const rush_to_judgment_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"rush-to-judgment","title":"Rush to Judgment","koreanPronunciation":"러시 투 저지먼트","tags":["관용구","자주 쓰는 표현"],"meaning":"성급하게 결론을 내리거나 충분한 정보 없이 판단하는 것의 의미입니다.","description":"이 표현은 어떤 상황이나 사람에 대해 모든 사실을 고려하거나 충분히 생각할 시간을 갖지 않고, 성급하게 부정적인 결정을 내리거나 의견을 형성하는 행위를 묘사할 때 사용됩니다. 대개 이러한 성급한 판단이 오해나 잘못된 결론으로 이어질 수 있음을 경고하는 뉘앙스를 담고 있습니다.","examples":[{"en":"We shouldn\'t rush to judgment before we hear all the facts.","ko":"모든 사실을 듣기 전에 성급하게 판단해서는 안 됩니다."},{"en":"The media was accused of rushing to judgment about the scandal.","ko":"언론은 그 스캔들에 대해 성급하게 판단했다는 비난을 받았습니다."},{"en":"It\'s easy to rush to judgment, but it\'s important to be patient.","ko":"성급하게 판단하기는 쉽지만, 인내심을 갖는 것이 중요합니다."},{"en":"Don\'t rush to judgment; wait for the investigation results.","ko":"성급하게 판단하지 마세요; 조사 결과를 기다리세요."}],"related":[{"slug":"jump-to-conclusions","title":"Jump to Conclusions","note":"비슷하게 성급하게 결론을 내린다는 의미입니다."},{"slug":"leap-to-conclusions","title":"Leap to Conclusions","note":"Jump to conclusions와 같은 의미를 가집니다."},{"slug":"hasty-decision","title":"Hasty Decision","note":"충분한 숙고 없이 내려진 성급한 결정 자체를 의미합니다."},{"slug":"snap-judgment","title":"Snap Judgment","note":"깊이 생각하지 않고 즉시 내리는 판단을 의미합니다."}],"date":"2025-08-09T00:00"}');
;// ./blog/stand-firm/content.json
const stand_firm_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"stand-firm","title":"Stand Firm","koreanPronunciation":"스탠드 펌","tags":["자주 쓰는 표현","구동사"],"meaning":"자신의 입장이나 의견을 굽히지 않고 굳건히 지키는 것을 의미합니다","description":"이 표현은 압력, 반대 또는 어려움에도 불구하고 자신의 원칙, 신념, 결정 또는 위치를 굳건히 고수하는 행위를 묘사합니다. 이는 주로 의지와 결단력을 나타내며, 포기하지 않고 버티는 강인한 태도를 강조할 때 사용됩니다.","examples":[{"en":"Despite intense criticism, the CEO decided to stand firm on her decision to restructure the company.","ko":"강력한 비판에도 불구하고, CEO는 회사를 재편성하려는 자신의 결정에 굳건히 맞서기로 했다."},{"en":"We must stand firm against injustice and fight for what is right.","ko":"우리는 불의에 맞서 굳건히 버티고 옳은 것을 위해 싸워야 합니다."},{"en":"Even when faced with a difficult choice, it\'s important to stand firm on your values.","ko":"어려운 선택에 직면했을 때에도 자신의 가치관을 굳건히 지키는 것이 중요합니다."},{"en":"The government needs to stand firm on its policy to protect the environment.","ko":"정부는 환경 보호 정책을 굳건히 지켜야 합니다."}],"related":[{"slug":"hold-one-s-ground","title":"Hold One\'s Ground","type":"synonym","note":"어려움 속에서도 자신의 위치나 주장을 고수하다."},{"slug":"stick-to-one-s-guns","title":"Stick to One\'s Guns","type":"synonym","note":"비판이나 압력에도 불구하고 자신의 의견이나 믿음을 굽히지 않다."},{"slug":"dig-in-one-s-heels","title":"Dig In One\'s Heels","type":"synonym","note":"자신의 입장을 굽히지 않고 완강하게 버티다."},{"slug":"give-in","title":"Give In","type":"antonym","note":"압력이나 요청에 굴복하거나 동의하다."}],"date":"2025-11-20T00:01"}');
;// ./blog/let-off-the-hook/content.json
const let_off_the_hook_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"let-off-the-hook","title":"Let Off The Hook","koreanPronunciation":"렛 오프 더 훅","tags":["구동사","관용구"],"meaning":"책임을 면하게 해주거나 곤경에서 벗어나게 해주는 의미입니다","description":"이 표현은 어떤 사람이 저지른 잘못이나 의무에 대해 책임을 지지 않도록 해주거나, 어려운 상황이나 처벌을 면하게 해줄 때 사용됩니다. 원래 낚시에 걸린 물고기를 놓아주는 모습에서 유래한 비유적인 표현으로, 주로 부담이나 비난에서 벗어나게 해주는 상황에 쓰입니다.","examples":[{"en":"The teacher let him off the hook for not doing his homework because he was sick.","ko":"선생님은 그가 아팠기 때문에 숙제를 하지 않은 것에 대해 책임을 면해주었다."},{"en":"I thought I would have to work late, but my boss let me off the hook.","ko":"야근해야 할 줄 알았는데, 사장님이 나를 자유롭게 해주셨다."},{"en":"After a long negotiation, the company was finally let off the hook for the environmental fine.","ko":"긴 협상 끝에 회사는 마침내 환경 벌금에서 벗어나게 되었다."},{"en":"Don\'t expect your parents to always let you off the hook; you need to face consequences sometimes.","ko":"부모님이 항상 너의 책임을 면해주리라 기대하지 마라; 때로는 결과에 직면해야 한다."},{"en":"He tried to let his friend off the hook, but the evidence was too strong.","ko":"그는 친구를 곤경에서 벗어나게 하려 했지만, 증거가 너무 확실했다."}],"related":[{"slug":"give-a-pass","title":"Give a Pass","type":"synonym","note":"누군가에게 규칙이나 의무를 면해주어 허용하다"},{"slug":"forgive-someone","title":"Forgive Someone","type":"synonym","note":"누군가의 잘못을 용서하다"},{"slug":"exempt-from-responsibility","title":"Exempt From Responsibility","type":"synonym","note":"책임이나 의무에서 면제하다"},{"slug":"hold-accountable","title":"Hold Accountable","type":"antonym","note":"누군가에게 책임을 묻다"},{"slug":"punish-someone","title":"Punish Someone","type":"antonym","note":"누군가에게 벌을 주다"}],"date":"2026-03-10T00:00"}');
;// ./blog/speak-frankly/content.json
const speak_frankly_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"speak-frankly","title":"Speak Frankly","koreanPronunciation":"스피크 프랭클리","tags":["자주 쓰는 표현","관용구"],"meaning":"가감 없이 솔직하게 말하거나, 자신의 의견이나 생각을 숨김없이 표현하다는 의미입니다.","description":"이 표현은 어떤 주제나 상황에 대해 진실을 이야기하거나, 자신의 생각과 감정을 정직하게 드러내는 것을 의미합니다. 대화에서 투명하고 솔직한 태도를 강조할 때 사용되며, 때로는 불편하거나 민감한 문제에 대해 직접적으로 소통할 필요가 있을 때 주로 쓰입니다. 상대방에게 솔직함을 요청하거나 자신이 솔직하게 말하겠다는 의지를 표현할 때 활용될 수 있습니다.","examples":[{"en":"We need to speak frankly about the company\'s financial situation if we want to find a solution.","ko":"해결책을 찾으려면 회사의 재정 상황에 대해 솔직하게 이야기해야 합니다."},{"en":"I appreciate you speaking frankly with me about your concerns; it helps a lot.","ko":"걱정하는 바에 대해 저에게 솔직하게 말해줘서 감사합니다. 큰 도움이 됩니다."},{"en":"It\'s important to speak frankly, even if the truth is difficult to hear.","ko":"진실을 듣기 어렵더라도 솔직하게 말하는 것이 중요합니다."},{"en":"Can we speak frankly for a moment? I have something important to discuss regarding your performance.","ko":"잠시 솔직하게 이야기할 수 있을까요? 당신의 업무 성과에 대해 중요한 할 말이 있습니다."},{"en":"She decided to speak frankly with her boss about the demanding workload.","ko":"그녀는 과도한 업무량에 대해 상사에게 솔직하게 이야기하기로 결정했습니다."}],"related":[{"slug":"tell-it-like-it-is","title":"Tell It Like It Is","type":"synonym","note":"상황을 있는 그대로, 직설적으로 말하는 것을 강조합니다."},{"slug":"mince-no-words","title":"Mince No Words","type":"synonym","note":"꾸밈없이 솔직하게, 돌려 말하지 않고 직접적으로 표현하는 것을 의미합니다."},{"slug":"be-straightforward","title":"Be Straightforward","type":"synonym","note":"복잡하게 돌리지 않고 직접적이고 명확하게 말하거나 행동하는 것을 뜻합니다."},{"slug":"call-a-spade-a-spade","title":"Call a Spade a Spade","type":"synonym","note":"어떤 것을 숨김없이 있는 그대로 부르거나 말하는 것을 의미하며, 때로는 무례하게 들릴 수도 있습니다."}],"date":"2025-08-30T00:01"}');
;// ./blog/clean-up-your-act/content.json
const clean_up_your_act_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"clean-up-your-act","title":"Clean Up Your Act","koreanPronunciation":"클린 업 유어 액트","tags":["관용구","자주 쓰는 표현"],"meaning":"행동이나 태도를 개선하고 올바르게 하다 또는 문제를 해결하다는 의미입니다","description":"이 표현은 주로 누군가의 행동이나 태도가 바람직하지 않거나 무책임할 때, 이를 고치고 더 나은 방식으로 행동하라고 촉구할 때 사용됩니다. 비유적으로 마치 지저분한 것을 깨끗하게 치우듯이 자신의 나쁜 습관이나 문제를 해결하라는 의미를 담고 있습니다. 일상생활, 직장, 개인적인 관계 등 다양한 상황에서 사용될 수 있습니다.","examples":[{"en":"If you don\'t clean up your act, you\'ll lose your job.","ko":"네 행동을 개선하지 않으면, 일자리를 잃을 거야."},{"en":"The coach told the team they needed to clean up their act if they wanted to win.","ko":"코치는 이기려면 팀이 행동을 개선해야 한다고 말했다."},{"en":"After getting into trouble, he promised to clean up his act and focus on his studies.","ko":"문제를 일으킨 후, 그는 자신의 행동을 개선하고 학업에 집중하겠다고 약속했다."},{"en":"It\'s time for this company to clean up its act and become more ethical.","ko":"이 회사는 이제 행동을 개선하고 더 윤리적으로 변해야 할 때입니다."}],"related":[{"slug":"mend-your-ways","title":"Mend Your Ways","type":"synonym","note":"나쁜 행동이나 습관을 고치고 더 나은 사람이 되다"},{"slug":"shape-up","title":"Shape Up","type":"synonym","note":"행동이나 성과를 개선하다"},{"slug":"straighten-up","title":"Straighten Up","type":"synonym","note":"행동을 바르게 하거나 진지하게 하다"},{"slug":"let-oneself-go","title":"Let Oneself Go","type":"antonym","note":"자신을 방치하고 외모나 행동에 신경 쓰지 않다"}],"date":"2025-11-02T00:00"}');
;// ./blog/burn-the-candle-at-both-ends/content.json
const burn_the_candle_at_both_ends_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"burn-the-candle-at-both-ends","title":"Burn the Candle at Both Ends","koreanPronunciation":"번 더 캔들 앳 보스 엔즈","tags":["관용구"],"meaning":"아침 일찍부터 밤늦게까지 과도하게 일하거나 활동하여 체력이나 에너지를 소모하는 것을 비유적으로 이르는 의미입니다.","description":"이 표현은 촛불의 양쪽 끝을 모두 태우면 촛불이 훨씬 더 빨리 소모되는 모습에서 유래했습니다. 이는 사람이 잠을 줄이고 쉬지 않으며 너무 많은 일을 하거나 과도한 활동을 하여 몸과 마음이 몹시 지치고 탈진하는 상황을 묘사할 때 사용됩니다. 주로 건강을 해치거나 효율성을 떨어뜨릴 수 있는 무리한 생활 방식에 대한 경고의 의미를 담고 있습니다.","examples":[{"en":"She\'s been burning the candle at both ends to finish this project on time.","ko":"그녀는 이 프로젝트를 제때 끝내기 위해 밤낮없이 일하고 있습니다."},{"en":"If you keep burning the candle at both ends, you\'ll eventually burn out.","ko":"계속 밤낮없이 일하면 결국 지쳐 쓰러질 거야."},{"en":"He used to burn the candle at both ends studying for exams, but now he tries to balance his life.","ko":"그는 예전에 시험공부를 위해 밤낮없이 공부했지만, 이제는 생활의 균형을 맞추려고 노력합니다."},{"en":"Working two jobs and taking night classes, she\'s definitely burning the candle at both ends.","ko":"두 가지 일을 하고 야간 수업을 들으니, 그녀는 정말 밤낮없이 일하고 있습니다."}],"related":[{"slug":"work-like-a-dog","title":"Work Like a Dog","type":"synonym","note":"매우 힘들고 고되게 일하다"},{"slug":"run-oneself-ragged","title":"Run Oneself Ragged","type":"synonym","note":"몹시 지치도록 일하거나 활동하다"},{"slug":"overdo-it","title":"Overdo It","type":"synonym","note":"지나치게 하다, 무리하다"},{"slug":"take-a-load-off","title":"Take a Load Off","type":"antonym","note":"한숨 돌리다, 쉬다"},{"slug":"unwind","title":"Unwind","type":"antonym","note":"긴장을 풀다, 휴식을 취하다"}],"date":"2026-04-08T00:01"}');
;// ./blog/knuckle-under/content.json
const knuckle_under_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"knuckle-under","title":"Knuckle Under","koreanPronunciation":"너클 언더","tags":["관용구","구동사","자주 쓰는 표현"],"meaning":"굴복하거나, 마지못해 받아들이거나, 권위에 복종하는 것의 의미입니다.","description":"이 표현은 저항을 멈추고 다른 사람의 권위나 요구에 따르거나, 곤경에 처한 상황에서 마지못해 항복하거나 포기하는 행동을 묘사할 때 사용됩니다. 주로 압력이나 어려움 때문에 어쩔 수 없이 순응할 때 쓰입니다.","examples":[{"en":"After weeks of protesting, the students finally had to knuckle under to the school\'s new rules.","ko":"몇 주간 시위한 후, 학생들은 결국 학교의 새로운 규칙에 굴복해야 했다."},{"en":"The small business refused to knuckle under to the larger corporation\'s demands, even if it meant losing some profit.","ko":"그 작은 사업체는 약간의 이익을 잃더라도 대기업의 요구에 굴복하기를 거부했다."},{"en":"He knew he had to knuckle under and apologize if he wanted to keep his job after the argument.","ko":"그는 논쟁 후에 직업을 유지하고 싶다면 굴복하고 사과해야 한다는 것을 알았다."},{"en":"We can\'t just knuckle under every time they make a new threat; we need to stand firm.","ko":"그들이 새로운 위협을 가할 때마다 우리가 굴복할 수는 없습니다; 우리는 단호해야 합니다."}],"related":[{"slug":"give-in","title":"Give In","type":"synonym","note":"마지못해 동의하거나 굴복할 때 사용됩니다."},{"slug":"yield","title":"Yield","type":"synonym","note":"압력이나 요청에 의해 마침내 굴복하는 것을 의미합니다."},{"slug":"submit","title":"Submit","type":"synonym","note":"다른 사람의 권위나 통제에 복종하는 것을 의미합니다."},{"slug":"stand-firm","title":"Stand Firm","type":"antonym","note":"어려움이나 압력에도 불구하고 자신의 입장이나 결정을 고수하는 것을 의미합니다."},{"slug":"resist","title":"Resist","type":"antonym","note":"어떤 것에 반대하거나 그것을 막기 위해 노력하는 것을 의미합니다."}],"date":"2025-11-20T00:00"}');
;// ./blog/let-the-cat-out-of-the-bag/content.json
const let_the_cat_out_of_the_bag_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"let-the-cat-out-of-the-bag","title":"Let the Cat Out of the Bag","koreanPronunciation":"렛 더 캣 아웃 오브 더 백","tags":["관용구"],"meaning":"비밀을 누설하다, 무심코 진실을 말하다 의미입니다.","description":"이 표현은 실수로 또는 의도치 않게 비밀 정보를 밝히거나, 아직 공개되어서는 안 될 소식을 퍼뜨릴 때 사용됩니다. 마치 고양이가 자루에서 나와 숨겨져 있던 것이 드러나는 모습에 비유하여, 비밀이 밝혀지는 상황을 묘사합니다.","examples":[{"en":"I accidentally let the cat out of the bag about Sarah\'s surprise party.","ko":"나는 실수로 사라의 깜짝 파티에 대해 비밀을 누설해버렸다."},{"en":"Don\'t let the cat out of the bag yet; it\'s supposed to be a secret until tomorrow.","ko":"아직 비밀을 누설하지 마세요; 내일까지는 비밀로 하기로 되어 있어요."},{"en":"He was trying to keep his promotion a secret, but his wife let the cat out of the bag.","ko":"그는 승진을 비밀로 하려 했지만, 그의 아내가 비밀을 누설해버렸다."},{"en":"If you let the cat out of the bag too early, it might ruin the whole plan.","ko":"너무 일찍 비밀을 누설하면 전체 계획을 망칠 수도 있습니다."}],"related":[{"slug":"give-away-the-secret","title":"Give Away the Secret","type":"synonym","note":"직접적으로 비밀을 누설하다는 의미입니다."},{"slug":"blurt-out","title":"Blurt Out","type":"synonym","note":"생각 없이 불쑥 말하다, 비밀을 무심코 발설하는 뉘앙스입니다."},{"slug":"keep-it-under-wraps","title":"Keep It Under Wraps","type":"antonym","note":"비밀로 간직하다, 숨기다라는 반대 의미의 표현입니다."}],"date":"2025-09-18T00:00"}');
;// ./blog/go-with-the-flow/content.json
const go_with_the_flow_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"go-with-the-flow","title":"Go With The Flow","koreanPronunciation":"고 위드 더 플로우","tags":["관용구","자주 쓰는 표현"],"meaning":"주어진 상황이나 다른 사람들의 행동에 저항하지 않고 순응하는 것을 의미합니다.","description":"이 표현은 강물의 흐름에 몸을 맡기듯이, 어떤 상황이나 다른 사람들의 의견에 순응하고 저항하지 않으며 자연스럽게 따라가는 태도를 묘사합니다. 특히 변화에 유연하게 대처하거나, 계획 없이 상황에 맞춰 행동할 때 사용됩니다. 고집을 부리거나 불필요하게 대립하기보다 조화롭게 어울리는 것을 강조합니다.","examples":[{"en":"I don\'t have strong preferences for dinner, so I\'ll just go with the flow.","ko":"저녁 식사에 특별한 선호는 없으니, 저는 그냥 흐름에 따를게요."},{"en":"When you travel to a new country, it\'s often best to go with the flow and experience things as they come.","ko":"새로운 나라를 여행할 때는 종종 흐름에 따르고 상황이 벌어지는 대로 경험하는 것이 가장 좋습니다."},{"en":"The team had no fixed agenda, so everyone decided to go with the flow and see what ideas emerged.","ko":"팀은 정해진 안건이 없었기 때문에, 모두 흐름에 맡기고 어떤 아이디어가 나올지 지켜보기로 결정했습니다."},{"en":"Don\'t try to control everything; sometimes it\'s healthier to just go with the flow.","ko":"모든 것을 통제하려고 하지 마세요. 때로는 그저 흐름에 맡기는 것이 더 건강합니다."},{"en":"He\'s very adaptable; he can always go with the flow no matter what happens.","ko":"그는 매우 적응력이 좋습니다. 어떤 일이 일어나든 항상 흐름에 따를 수 있습니다."}],"related":[{"slug":"adjust","title":"Adjust","type":"synonym","note":"상황에 맞춰 자신을 바꾸는 일반적인 행동을 나타냅니다."},{"slug":"conform","title":"Conform","type":"synonym","note":"규칙, 표준 또는 다른 사람들의 기대에 순응하는 것을 의미합니다."},{"slug":"swim-against-the-tide","title":"Swim Against The Tide","type":"antonym","note":"대부분의 사람들과 반대되는 행동이나 의견을 고수하는 것을 의미합니다."},{"slug":"buck-the-trend","title":"Buck The Trend","type":"antonym","note":"널리 퍼진 경향이나 유행에 역행하거나 저항하는 것을 의미합니다."}],"date":"2025-11-15T00:00"}');
