const object_to_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"object-to","title":"Object To","koreanPronunciation":"오브젝트 투","tags":["구동사"],"meaning":"무언가에 반대하거나 이의를 제기한다는 의미입니다.","description":"이 표현은 특정 계획, 아이디어, 행동 등에 대해 부정적인 의견을 표명하거나 반대 입장을 분명히 할 때 사용됩니다. 공식적이거나 비공식적인 상황 모두에서 사용될 수 있으며, 동의하지 않음을 나타내는 명확한 방식입니다. 주로 \'나는 ~에 반대한다\' 또는 \'누가 ~에 반대할 수 있겠는가\'와 같은 형태로 쓰입니다.","examples":[{"en":"I object to the proposed changes in the schedule.","ko":"저는 제안된 일정 변경에 반대합니다."},{"en":"She strongly objected to his rude comments.","ko":"그녀는 그의 무례한 발언에 강력히 반대했습니다."},{"en":"Many people object to the new policy because it limits their freedom.","ko":"많은 사람들이 자유를 제한하는 새 정책에 반대합니다."},{"en":"Does anyone object to our moving forward with this plan?","ko":"누구 이 계획을 진행하는 것에 반대하는 사람 있나요?"}],"related":[{"slug":"disagree-with","title":"Disagree With","type":"synonym","note":"일반적으로 의견이나 생각에 동의하지 않을 때 사용됩니다."},{"slug":"oppose","title":"Oppose","type":"synonym","note":"어떤 것에 적극적으로 반대하거나 저항하는 것을 의미합니다."},{"slug":"protest-against","title":"Protest Against","type":"synonym","note":"어떤 결정이나 상황에 대해 공식적으로 또는 공개적으로 불만을 표현할 때 사용됩니다."}],"date":"2025-11-17T00:00"}');
;// ./blog/torn-between/content.json
const torn_between_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"torn-between","title":"Torn Between","koreanPronunciation":"토른 비트윈","tags":["관용구","자주 쓰는 표현"],"meaning":"두 가지 이상의 선택지나 감정 사이에서 망설이거나 어떤 것을 선택해야 할지 혼란스러운 상황에 있음을 나타내는 의미입니다.","description":"이 표현은 주로 두 가지 매력적이거나 서로 상충되는 선택지, 혹은 감정 앞에서 어떤 것을 선택해야 할지 혼란스럽거나 내적으로 갈등하는 상태를 묘사할 때 사용됩니다. 어떤 결정을 내려야 할지 어려움을 겪고 있거나 마음이 이리저리 흔들릴 때 쓸 수 있습니다.","examples":[{"en":"I\'m torn between accepting the job offer in New York and staying close to my family.","ko":"나는 뉴욕의 일자리 제안을 받아들일지 가족 곁에 머무를지 갈등하고 있어."},{"en":"She\'s torn between pursuing her passion for art and choosing a more stable career.","ko":"그녀는 예술에 대한 열정을 따를지 아니면 더 안정적인 직업을 선택할지 고민 중이다."},{"en":"The company is torn between investing in new technology or expanding its current market.","ko":"그 회사는 새로운 기술에 투자할지 아니면 현재 시장을 확장할지 고민하고 있다."},{"en":"He was torn between loyalty to his friend and telling the truth.","ko":"그는 친구에 대한 충성심과 진실을 말하는 것 사이에서 갈등했다."}],"related":[{"slug":"on-the-fence","title":"On The Fence","type":"synonym","note":"두 가지 선택지 사이에서 결정을 내리지 못하고 망설이는 상태를 의미합니다."},{"slug":"hesitate","title":"Hesitate","type":"synonym","note":"어떤 행동이나 결정을 주저하거나 망설이는 것을 의미합니다."},{"slug":"make-a-decision","title":"Make A Decision","type":"antonym","note":"망설임 없이 결정을 내리는 것을 의미합니다."},{"slug":"commit-fully","title":"Commit Fully","type":"antonym","note":"특정 선택이나 경로에 완전히 전념하는 것을 의미합니다."}],"date":"2025-09-29T00:00"}');
;// ./blog/keep-a-secret/content.json
const keep_a_secret_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"keep-a-secret","title":"Keep a Secret","koreanPronunciation":"킵 어 시크릿","tags":["관용구","자주 쓰는 표현"],"meaning":"비밀을 지키고 다른 사람에게 말하지 않는다는 의미입니다.","description":"이 표현은 누군가에게 들었거나 알게 된 중요한 정보나 개인적인 내용을 다른 사람에게 발설하지 않고 지키는 것을 의미합니다. 신뢰와 약속의 중요성을 강조할 때 사용되며, 특히 친구나 동료 사이에서 비밀 유지를 요청하거나 약속할 때 자주 쓰입니다. 어떤 정보가 공개되어서는 안 될 때 쓰는 표현입니다.","examples":[{"en":"Can you keep a secret? I have something important to tell you.","ko":"비밀을 지켜줄 수 있니? 너에게 중요한 얘기가 있어."},{"en":"She\'s good at keeping secrets, so you can trust her with your confession.","ko":"그녀는 비밀을 잘 지키니, 네 고백을 믿고 말해도 돼."},{"en":"It\'s hard to keep a secret when everyone is trying to guess what happened.","ko":"모두가 무슨 일이 있었는지 알아내려 할 때 비밀을 지키는 것은 어렵다."},{"en":"I promised to keep his secret, no matter what.","ko":"무슨 일이 있어도 그의 비밀을 지키겠다고 약속했어."}],"related":[{"slug":"keep-mum","title":"Keep Mum","type":"synonym","note":"어떤 것에 대해 아무 말도 하지 않고 침묵을 지킨다는 의미"},{"slug":"zip-ones-lips","title":"Zip One\'s Lips","type":"synonym","note":"비밀을 지키기 위해 입을 다물거나 아무 말도 하지 않겠다는 의미"},{"slug":"let-the-cat-out-of-the-bag","title":"Let the Cat Out of the Bag","type":"antonym","note":"비밀을 무심코 누설하거나 예상치 못하게 폭로한다는 의미"}],"date":"2025-09-18T00:01"}');
;// ./blog/bite-the-bullet/content.json
const bite_the_bullet_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"bite-the-bullet","title":"Bite the Bullet","koreanPronunciation":"바이트 더 불렛","tags":["관용구"],"meaning":"싫지만 어쩔 수 없이 힘들거나 불쾌한 상황을 감내하는 것을 의미합니다.","description":"이 표현은 원래 19세기 군사 용어에서 유래한 것으로, 마취 없이 수술을 받아야 할 때 환자들이 고통을 견디기 위해 총알을 물었던 것에서 비롯되었습니다. 오늘날에는 어떤 어려운 상황이나 불쾌한 일을 어쩔 수 없이 받아들이고 감내해야 할 때 사용됩니다.","examples":[{"en":"I had to bite the bullet and work extra hours to finish the project on time.","ko":"프로젝트를 제시간에 끝내기 위해 추가 근무를 감수해야 했다."},{"en":"She decided to bite the bullet and tell her boss about the mistake.","ko":"그녀는 용기를 내어 상사에게 실수에 대해 말하기로 결정했다."},{"en":"Sometimes in life, you just have to bite the bullet and do what\'s necessary.","ko":"인생에서는 때때로 싫어도 필요한 일을 감수해야 할 때가 있다."},{"en":"Paying for the repairs was expensive, but we had to bite the bullet.","ko":"수리 비용이 비쌌지만, 우리는 감수해야만 했다."}],"related":[{"slug":"tough-it-out","title":"Tough It Out","type":"synonym","note":"어려운 상황을 참고 견디다."},{"slug":"grin-and-bear-it","title":"Grin and Bear It","type":"synonym","note":"불평 없이 힘든 상황을 받아들이다."},{"slug":"face-the-music","title":"Face the Music","type":"synonym","note":"자신의 행동에 대한 불쾌한 결과를 받아들이다."}],"date":"2025-07-04T19:06"}');
;// ./blog/grit-ones-teeth/content.json
const grit_ones_teeth_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"grit-ones-teeth","title":"Grit One\'s Teeth","koreanPronunciation":"그릿 원스 티스","tags":["관용구","자주 쓰는 표현"],"meaning":"고통이나 분노를 참거나, 어려운 상황을 견뎌내려는 결심을 보일 때 \'이를 악물다\'라는 의미입니다.","description":"이 표현은 물리적으로 이를 꽉 무는 행위에서 유래하여, 비유적으로는 매우 불쾌하거나 고통스러운 상황을 인내심을 가지고 견뎌내겠다는 강한 의지를 나타냅니다. 보통 어떤 일을 마지못해 하거나, 힘든 과정을 겪을 때 사용됩니다. 고통스러운 순간을 참아내거나, 싫지만 해야 하는 일을 할 때 이를 악무는 모습에서 그 의미가 확장되었습니다.","examples":[{"en":"She had to grit her teeth and bear the pain of the injection.","ko":"그녀는 이를 악물고 주사 고통을 견뎌야 했다."},{"en":"I had to grit my teeth and finish the report even though I was exhausted.","ko":"나는 너무 지쳤지만 이를 악물고 보고서를 마쳐야 했다."},{"en":"He gritted his teeth and pushed through the final kilometers of the marathon.","ko":"그는 이를 악물고 마라톤의 마지막 몇 킬로미터를 달렸다."},{"en":"Sometimes you just have to grit your teeth and get through it.","ko":"때로는 그저 이를 악물고 해내야만 한다."}],"related":[{"slug":"bite-the-bullet","title":"Bite the Bullet","type":"synonym","note":"고통스럽거나 불쾌한 일을 억지로 감수하다는 의미로, \'grit one\'s teeth\'와 유사하게 어려운 상황을 인내할 때 사용됩니다."},{"slug":"steel-oneself","title":"Steel Oneself","type":"synonym","note":"어려운 상황이나 도전에 대비해 마음을 단단히 먹고 준비하다는 의미입니다."},{"slug":"tough-it-out","title":"Tough It Out","type":"synonym","note":"힘들고 어려운 상황을 끝까지 견뎌내고 버티다는 의미로, \'grit one\'s teeth\'가 강조하는 인내와 유사합니다."},{"slug":"bear-down","title":"Bear Down","type":"synonym","note":"무언가를 해내기 위해 힘껏 집중하거나 노력하다는 의미로, 물리적인 노력과 이를 악무는 행위와 연결될 수 있습니다."}],"date":"2025-07-04T19:06"}');
