const bite_off_more_than_one_can_chew_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"bite-off-more-than-one-can-chew","title":"Bite Off More Than One Can Chew","koreanPronunciation":"바이트 오프 모어 댄 원 캔 츄","tags":["관용구","자주 쓰는 표현"],"meaning":"자신이 감당할 수 있는 것보다 더 많은 일이나 책임을 맡는다는 의미입니다","description":"이 표현은 개인이 자신의 능력이나 자원보다 과도한 목표나 임무를 설정하여 결국 어려움에 처하거나 실패할 위험이 있음을 경고할 때 사용됩니다. 욕심을 부리거나 자신의 한계를 간과하여 곤경에 빠지는 상황을 비유적으로 나타냅니다. 주로 스스로 감당하기 어려운 일을 떠맡았을 때 후회하거나 조언할 때 쓰입니다.","examples":[{"en":"I think I bit off more than I could chew by taking on three big projects at once.","ko":"세 가지 큰 프로젝트를 동시에 맡은 것은 내가 감당할 수 있는 것보다 더 많은 일을 벌인 것 같아요."},{"en":"Don\'t bite off more than you can chew when starting a new business; start small.","ko":"새로운 사업을 시작할 때는 감당할 수 있는 것보다 더 많은 일을 벌이지 마세요; 작게 시작하세요."},{"en":"She bit off more than she could chew by trying to organize the entire charity event by herself.","ko":"그녀는 혼자서 전체 자선 행사를 조직하려다가 감당할 수 있는 것보다 더 많은 일을 벌였습니다."},{"en":"Many students bite off more than they can chew by enrolling in too many advanced courses.","ko":"많은 학생들이 너무 많은 고급 과정에 등록하여 감당할 수 있는 것보다 더 많은 일을 벌입니다."}],"related":[{"slug":"overcommit","title":"Overcommit","type":"synonym","note":"직접적으로 \'과도하게 약속하다\'는 의미로, 너무 많은 일을 떠맡아 부담을 지는 상황과 유사합니다."},{"slug":"take-on-too-much","title":"Take On Too Much","type":"synonym","note":"말 그대로 \'너무 많은 것을 떠맡다\'는 의미로, \'감당할 수 있는 것 이상을 하려 한다\'와 가깝습니다."},{"slug":"play-it-safe","title":"Play It Safe","type":"antonym","note":"위험을 감수하기보다 안전한 방법을 택하여 감당 가능한 범위 내에서 행동하는 것을 의미합니다."},{"slug":"know-ones-limits","title":"Know One\'s Limits","type":"antonym","note":"자신의 한계를 알고 그 안에서 행동하는 것으로, 과도하게 일을 벌이지 않는 것과 대조됩니다."}],"date":"2025-08-29T00:01"}');
;// ./blog/get-ahead-of-oneself/content.json
const get_ahead_of_oneself_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"get-ahead-of-oneself","title":"Get Ahead Of Oneself","koreanPronunciation":"겟 어헤드 오브 원셀프","tags":["관용구","자주 쓰는 표현"],"meaning":"너무 앞서나가거나, 아직 일어나지 않은 일에 대해 미리 기대하거나 걱정하는 의미입니다.","description":"이 표현은 어떤 일이 완전히 확정되거나 발생하기도 전에 너무 일찍 결론을 내리거나, 과도하게 계획을 세우거나, 들뜨는 행동을 묘사할 때 사용됩니다. 주로 신중하지 못하거나 성급한 태도를 지적할 때 쓰이며, 때로는 과도한 자신감으로 인해 실수를 저지를 수 있음을 경고하는 뉘앙스도 포함합니다.","examples":[{"en":"Don\'t get ahead of yourself; we haven\'t even won the first round yet.","ko":"너무 앞서가지 마세요; 아직 1라운드도 이기지 못했어요."},{"en":"She was getting ahead of herself, planning the wedding before he even proposed.","ko":"그는 프러포즈도 하기 전에 결혼 계획을 세우며 너무 앞서가고 있었다."},{"en":"Let\'s not get ahead of ourselves. We need to focus on completing this step first.","ko":"우리 너무 앞서가지 맙시다. 먼저 이 단계를 완료하는 데 집중해야 해요."},{"en":"I know you\'re excited, but try not to get ahead of yourself with the celebration plans.","ko":"당신이 신난 건 알지만, 축하 계획으로 너무 앞서가지 않도록 노력하세요."}],"related":[{"slug":"jump-the-gun","title":"Jump The Gun","type":"synonym","note":"너무 일찍 시작하거나 성급하게 행동하다."},{"slug":"put-the-cart-before-the-horse","title":"Put The Cart Before The Horse","type":"synonym","note":"일의 순서를 뒤바꿔서 잘못 처리하다."},{"slug":"wait-and-see","title":"Wait And See","type":"antonym","note":"결과가 어떻게 될지 지켜보며 기다리다."},{"slug":"think-before-you-act","title":"Think Before You Act","type":"antonym","note":"행동하기 전에 신중하게 생각하다."}],"date":"2025-11-28T00:00"}');
;// ./blog/feel-unwell/content.json
const feel_unwell_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"feel-unwell","title":"Feel Unwell","koreanPronunciation":"필 언웰","tags":["자주 쓰는 표현"],"meaning":"몸이 좋지 않거나 아픈 상태를 나타내는 의미입니다.","description":"이 표현은 건강이 좋지 않거나 병이 났을 때 사용하는 일반적인 말입니다. 감기, 두통, 소화 불량 등 다양한 증상으로 인해 불편함을 느낄 때 \'feel unwell\'이라고 말할 수 있습니다. 일상생활에서 자신의 건강 상태를 설명할 때 흔히 사용됩니다.","examples":[{"en":"I\'m feeling unwell, so I think I should go home early.","ko":"몸이 좋지 않아서 일찍 집에 가야 할 것 같아요."},{"en":"After eating the suspicious food, she started to feel unwell.","ko":"그녀는 의심스러운 음식을 먹은 후 몸이 좋지 않기 시작했습니다."},{"en":"If you feel unwell, please let me know immediately.","ko":"만약 몸이 좋지 않으시면 즉시 저에게 알려주세요."},{"en":"He had been feeling unwell for a few days before he finally saw a doctor.","ko":"그는 의사를 찾아가기 전 며칠 동안 몸이 좋지 않았습니다."}],"related":[{"slug":"feel-sick","title":"Feel Sick","type":"synonym","note":"일반적으로 아프다고 느낄 때 사용하는 표현입니다."},{"slug":"be-under-the-weather","title":"Be Under the Weather","type":"synonym","note":"몸이 약간 좋지 않거나 기분이 저조할 때 사용하는 비유적인 표현입니다."},{"slug":"feel-poorly","title":"Feel Poorly","type":"synonym","note":"몸이 좋지 않다고 느끼는 다소 격식 있는 표현입니다."},{"slug":"feel-well","title":"Feel Well","type":"antonym","note":"몸이 건강하고 기분 좋다고 느낄 때 사용합니다."}],"date":"2025-09-01T00:00"}');
;// ./blog/cry-wolf/content.json
const cry_wolf_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"cry-wolf","title":"Cry Wolf","koreanPronunciation":"크라이 울프","tags":["관용구"],"meaning":"사람들이 더 이상 믿지 않게 만드는 방식으로 거짓 경고를 하거나 거짓 도움을 요청하는 것을 의미입니다.","description":"이 표현은 이솝 우화 \'양치기 소년과 늑대\'에서 유래했습니다. 양치기 소년이 재미로 늑대가 나타났다고 거짓말을 하여 마을 사람들이 여러 번 속았고, 결국 진짜 늑대가 나타났을 때는 아무도 그를 믿지 않아 양들이 잡아먹혔다는 이야기에서 비롯되었습니다. 따라서 \'Cry wolf\'는 거짓말이나 과장된 경고로 인해 사람들이 결국 신뢰를 잃게 되는 상황을 묘사할 때 사용됩니다.","examples":[{"en":"He cried wolf so many times about being sick that his boss didn\'t believe him when he actually had the flu.","ko":"그는 아프다고 너무 자주 거짓말을 해서, 정말 독감에 걸렸을 때 상사가 그를 믿지 않았다."},{"en":"If you keep crying wolf about every minor problem, people won\'t take you seriously when a real crisis happens.","ko":"모든 사소한 문제에 대해 계속해서 거짓 경고를 한다면, 진짜 위기가 닥쳤을 때 아무도 당신을 진지하게 받아들이지 않을 것이다."},{"en":"The politician was accused of crying wolf to gain public sympathy, making exaggerated claims about threats to the nation.","ko":"그 정치인은 대중의 동정을 얻기 위해 국가에 대한 위협에 대해 과장된 주장을 하며 거짓 경고를 했다는 비난을 받았다."}],"related":[{"slug":"false-alarm","title":"False Alarm","type":"synonym","note":"실제 위험이 아닌데도 위험 상황이라고 알리는 행위를 의미합니다."},{"slug":"exaggerate","title":"Exaggerate","type":"synonym","note":"실제보다 더 크게 부풀리거나 과장하는 행위를 의미하지만, \'cry wolf\'처럼 신뢰를 잃는 결과에 초점을 두지는 않습니다."},{"slug":"be-truthful","title":"Be Truthful","type":"antonym","note":"거짓말하지 않고 사실만을 말하는 것을 의미합니다."},{"slug":"be-credible","title":"Be Credible","type":"antonym","note":"말이나 행동이 믿을 수 있고 신뢰를 받는 상태를 의미합니다."}],"date":"2025-09-30T00:00"}');
;// ./blog/refresh-ones-memory/content.json
const refresh_ones_memory_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"refresh-ones-memory","title":"Refresh One\'s Memory","koreanPronunciation":"리프레시 원스 메모리","tags":["관용구","자주 쓰는 표현"],"meaning":"잊었거나 희미해진 기억을 되살리거나 상기시키는 것의 의미입니다.","description":"이 표현은 특정한 정보나 사건에 대한 기억이 흐릿하거나 잊혔을 때, 그것을 다시 명확하게 떠올리기 위해 노력하는 상황을 묘사할 때 사용됩니다. 주로 과거의 사실, 이름, 날짜 등을 기억해 내려고 할 때 쓰이며, 어떤 것을 다시 배우거나 복습하는 것과는 약간 다르게 이미 알고 있던 것을 되찾는다는 뉘앙스가 강합니다.","examples":[{"en":"I need to refresh my memory on those legal terms before the meeting.","ko":"회의 전에 그 법률 용어들을 다시 기억해야 해."},{"en":"Can you refresh my memory? What was her name again?","ko":"다시 기억나게 해줄래? 그녀 이름이 뭐였지?"},{"en":"Reading old notes always helps me refresh my memory of the lectures.","ko":"오래된 필기를 읽는 것은 항상 강의 내용을 다시 기억하는 데 도움이 돼."},{"en":"He looked at the photo album to refresh his memory of their vacation.","ko":"그는 휴가 기억을 되살리기 위해 사진 앨범을 보았다."},{"en":"Let me check my calendar to refresh my memory about the appointment.","ko":"약속에 대해 다시 확인하기 위해 내 달력을 확인해볼게."}],"related":[{"slug":"jog-ones-memory","title":"Jog One\'s Memory","type":"synonym","note":"매우 유사한 의미로, 기억을 돕거나 되살리다."},{"slug":"recall","title":"Recall","type":"synonym","note":"좀 더 공식적이거나 일반적인 \'기억해내다\'라는 의미."},{"slug":"remind-someone","title":"Remind Someone","type":"synonym","note":"누군가에게 특정 정보를 상기시켜주다."},{"slug":"forget","title":"Forget","type":"antonym"}],"date":"2025-12-03T00:00"}');
;// ./blog/go-the-extra-mile/content.json
const go_the_extra_mile_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"go-the-extra-mile","title":"Go The Extra Mile","koreanPronunciation":"고 디 엑스트라 마일","tags":["관용구","자주 쓰는 표현"],"meaning":"기대 이상으로 노력하거나 더 많은 것을 하는 것을 의미합니다","description":"이 표현은 어떤 목표를 달성하거나 누군가를 돕기 위해 필요한 것 이상으로 시간, 노력, 에너지를 투자하는 것을 나타냅니다. 단순히 의무를 넘어서 자발적으로 더 열심히 일하거나 더 많은 도움을 제공할 때 사용됩니다. 이는 흔히 긍정적인 결과나 보상으로 이어집니다.","examples":[{"en":"She always goes the extra mile for her clients, which is why they trust her so much.","ko":"그녀는 항상 고객을 위해 한층 더 노력하며, 이것이 고객들이 그녀를 그렇게 신뢰하는 이유입니다."},{"en":"To truly succeed in this project, we need to go the extra mile and pay attention to every detail.","ko":"이 프로젝트에서 진정으로 성공하려면, 우리는 한층 더 노력하여 모든 세부 사항에 주의를 기울여야 합니다."},{"en":"The hotel staff went the extra mile to make our stay comfortable and memorable.","ko":"호텔 직원들은 우리의 숙박을 편안하고 기억에 남게 하기 위해 특별히 더 노력했습니다."},{"en":"If you want to stand out, you have to be willing to go the extra mile.","ko":"두각을 나타내고 싶다면, 한층 더 노력할 의지가 있어야 합니다."}],"related":[{"slug":"go-above-and-beyond","title":"Go Above And Beyond","type":"synonym","note":"기대치나 요구사항을 훨씬 넘어서는 노력을 의미합니다."},{"slug":"bend-over-backwards","title":"Bend Over Backwards","type":"synonym","note":"어떤 일을 위해 극도로 노력하거나 희생하는 것을 강조합니다."},{"slug":"do-the-bare-minimum","title":"Do The Bare Minimum","type":"antonym","note":"최소한의 노력만 하는 것을 의미합니다."}],"date":"2025-09-05T00:00"}');
