const come_across_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"come-across","title":"Come Across","koreanPronunciation":"컴 어크로스","tags":["구동사","자주 쓰는 표현"],"meaning":"우연히 마주치거나, 어떤 인상이나 방식으로 보인다는 의미입니다.","description":"이 표현은 주로 두 가지 의미로 사용됩니다. 첫째, \'우연히 발견하다\' 또는 \'우연히 만나다\'라는 뜻으로, 예상치 못하게 무언가나 누군가를 접하게 될 때 사용합니다. 둘째, \'특정한 인상을 주다\' 또는 \'어떻게 보이다\'라는 뜻으로, 어떤 사람이나 사물이 다른 사람에게 어떤 느낌이나 인상을 주는 방식을 설명할 때 사용됩니다. 예를 들어, \'He comes across as very confident\'는 \'그는 매우 자신감 있는 사람처럼 보인다\'는 뜻입니다.","examples":[{"en":"I came across an old photo of my grandmother in the attic.","ko":"다락방에서 할머니의 오래된 사진을 우연히 발견했어요."},{"en":"She comes across as a very kind and understanding person.","ko":"그녀는 매우 친절하고 이해심 많은 사람처럼 보여요."},{"en":"While browsing the bookstore, I came across a fascinating book.","ko":"서점을 둘러보다가 우연히 매력적인 책을 발견했어요."},{"en":"His message didn\'t come across very clearly during the meeting.","ko":"그의 메시지는 회의 중에 명확하게 전달되지 않았어요."}],"related":[{"slug":"bump-into","title":"Bump Into","type":"synonym","note":"\'우연히 만나다\' 또는 \'우연히 마주치다\'의 의미로 \'come across\'와 유사하게 사용됩니다."},{"slug":"stumble-upon","title":"Stumble Upon","type":"synonym","note":"\'우연히 발견하다\' 또는 \'우연히 마주치다\'의 의미로 \'come across\'의 발견 의미와 가깝습니다."},{"slug":"seem-to-be","title":"Seem to Be","type":"synonym","note":"\'어떤 것처럼 보이다\'라는 의미로, \'come across\'의 \'어떤 인상을 주다\'는 의미와 비슷하게 사용될 수 있습니다."}],"date":"2025-07-05T18:20"}');
;// ./blog/sick-as-a-dog/content.json
const sick_as_a_dog_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"sick-as-a-dog","title":"Sick as a Dog","koreanPronunciation":"식 애즈 어 도그","tags":["관용구","자주 쓰는 표현"],"meaning":"매우 심하게 아프거나 몸이 좋지 않음을 비유적으로 표현하는 의미입니다","description":"이 표현은 개가 아플 때 심하게 앓거나 구토하는 모습을 보이는 것에서 유래했습니다. 사람이 매우 심하게 아프거나 몸이 불편하여 고통스러워할 때 사용됩니다. 보통 감기, 독감, 식중독 등으로 인해 몸져눕다시피 할 정도로 심각한 상태를 묘사할 때 자주 쓰입니다.","examples":[{"en":"After eating that suspicious seafood, I was sick as a dog all night.","ko":"그 의심스러운 해산물을 먹은 후에, 저는 밤새도록 몸져누울 정도로 몹시 아팠어요."},{"en":"She caught the flu and has been sick as a dog for the past three days.","ko":"그녀는 독감에 걸려 지난 사흘 동안 내내 몹시 아팠어요."},{"en":"Don\'t come to work if you\'re sick as a dog; you\'ll infect everyone.","ko":"몸이 몹시 아프다면 출근하지 마세요; 모두에게 전염시킬 거예요."},{"en":"He looked sick as a dog after the roller coaster ride.","ko":"그는 롤러코스터를 탄 후에 몹시 아파 보였습니다."}],"related":[{"slug":"under-the-weather","title":"Under the Weather","type":"synonym","note":"\'sick as a dog\'보다 덜 심각하며, 단순히 몸이 좀 안 좋은 상태를 의미합니다."},{"slug":"feeling-poorly","title":"Feeling Poorly","type":"synonym","note":"몸이 안 좋은 상태를 좀 더 완곡하게 표현하는 말입니다."},{"slug":"green-around-the-gills","title":"Green Around the Gills","type":"synonym","note":"주로 구토할 것 같거나 창백한 안색으로 아파 보이는 것을 묘사할 때 사용됩니다."}],"date":"2025-09-01T00:00"}');
;// ./blog/push-one-s-luck/content.json
const push_one_s_luck_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"push-one-s-luck","title":"Push One\'s Luck","koreanPronunciation":"푸시 원스 럭","tags":["관용구","자주 쓰는 표현"],"meaning":"이미 좋은 상황이나 운이 따르는 상황에서 과도하게 더 많은 것을 바라거나 불필요한 위험을 감수하여 결국에는 안 좋은 결과를 초래할 수 있는 행동을 하다의미입니다.","description":"이 표현은 어떤 사람이 성공적이거나 유리한 상황에 있음에도 불구하고, 현재의 좋은 운이나 성공에 만족하지 않고 더 큰 이득을 얻기 위해 무리하거나 불필요한 위험을 감수하는 것을 묘사합니다. 이는 종종 좋은 운이 오래가지 않거나 욕심을 부리다가 일을 그르칠 수 있다는 경고의 의미로 사용됩니다. 예를 들어, 카지노에서 계속 이기는데도 멈추지 않고 더 크게 베팅하는 상황이나, 이미 마감 기한을 넘겨서 용서받았는데 또다시 마감 기한을 넘기려 할 때 이 표현을 쓸 수 있습니다.","examples":[{"en":"You\'ve won two games in a row; don\'t push your luck by betting on the third.","ko":"연속으로 두 번이나 이겼으니, 세 번째 게임에 걸어서 운을 시험하지 마라."},{"en":"He decided to go home after winning a small amount, not wanting to push his luck.","ko":"그는 소액을 딴 후 운을 시험하고 싶지 않아 집으로 돌아가기로 결정했다."},{"en":"She had already gotten away with being late twice, so she didn\'t want to push her luck again.","ko":"그녀는 이미 두 번이나 지각하고도 넘어갔으니, 또다시 운을 시험하고 싶지 않았다."},{"en":"Don\'t push your luck by asking for another extension; your boss is already annoyed.","ko":"더 이상의 연장을 요구해서 운을 시험하지 마라. 네 상사는 이미 짜증 나 있다."}],"related":[{"slug":"bite-off-more-than-one-can-chew","title":"Bite Off More Than One Can Chew","type":"synonym","note":"감당할 수 있는 것보다 더 많은 일을 맡는다는 점에서 유사하지만, \'push one\'s luck\'은 특히 좋은 운을 과신하여 무리하게 일을 진행하는 뉘앙스가 강합니다."},{"slug":"take-a-risk","title":"Take a Risk","type":"synonym","note":"위험을 감수하는 행동이라는 점에서 유사하나, \'push one\'s luck\'은 이미 유리하거나 좋은 상황에서 더 큰 욕심을 위해 불필요한 위험을 감수할 때 주로 쓰입니다."},{"slug":"play-it-safe","title":"Play It Safe","type":"antonym","note":"위험을 회피하고 안전하게 행동하는 것으로, \'push one\'s luck\'의 반대되는 의미입니다."}],"date":"2026-04-01T00:00"}');
;// ./blog/stab-someone-in-the-back/content.json
const stab_someone_in_the_back_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"stab-someone-in-the-back","title":"Stab Someone In The Back","koreanPronunciation":"스탭 썸원 인 더 백","tags":["관용구","자주 쓰는 표현"],"meaning":"뒤에서 남을 배신하거나 해를 입히는 것을 비유적으로 이르는 의미입니다.","description":"이 표현은 누군가가 신뢰하거나 의지하는 사람의 뒤에서 몰래 그 사람에게 해를 가하거나 배신하는 행위를 비유적으로 나타냅니다. 특히 친한 친구, 동료, 가족 등 가까운 관계에서 믿음을 저버리는 행위에 사용됩니다. 문자 그대로 칼로 등을 찌르는 듯한 극심한 배신감을 강조하는 표현입니다.","examples":[{"en":"I can\'t believe he stabbed me in the back after all I did for him.","ko":"내가 그를 위해 해준 모든 일 후에 그가 나를 배신했다는 것을 믿을 수 없어."},{"en":"She felt completely betrayed when her best friend stabbed her in the back by spreading rumors.","ko":"가장 친한 친구가 소문을 퍼뜨려 그녀를 배신했을 때 그녀는 완전히 배신감을 느꼈다."},{"en":"Don\'t stab your colleagues in the back if you want to succeed in this company.","ko":"이 회사에서 성공하고 싶다면 동료들을 배신하지 마세요."},{"en":"The politician was accused of stabbing his party in the back by secretly working with the opposition.","ko":"그 정치인은 몰래 야당과 협력함으로써 당을 배신했다는 비난을 받았다."}],"related":[{"slug":"betray-someone","title":"Betray Someone","type":"synonym","note":"더 일반적인 배신 행위를 지칭합니다."},{"slug":"double-cross-someone","title":"Double-Cross Someone","type":"synonym","note":"특히 합의나 약속을 어기고 배신하는 것을 의미합니다."},{"slug":"sell-someone-out","title":"Sell Someone Out","type":"synonym","note":"개인의 이득을 위해 남을 팔아넘기거나 배신하는 것을 의미합니다."},{"slug":"have-someones-back","title":"Have Someone\'s Back","type":"antonym","note":"누군가를 지지하고 보호하며 돕는 것을 의미합니다."},{"slug":"stand-by-someone","title":"Stand By Someone","type":"antonym","note":"어려운 시기에 누군가를 돕고 지지하며 충성하는 것을 의미합니다."}],"date":"2025-08-25T00:00"}');
