const take_off_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"take-off","title":"Take Off","koreanPronunciation":"테이크 오프","tags":["구동사","자주 쓰는 표현"],"meaning":"비행기가 이륙하는 것, 갑자기 인기를 얻는 것, 또는 떠나는 것을 의미합니다.","description":"이 표현은 상황에 따라 다양한 의미로 쓰입니다. 기본적으로 비행기가 활주로를 떠나 하늘로 오를 때 쓰이고, 어떤 것이 갑자기 성공하거나 인기를 얻을 때, 또는 사람이 어떤 장소를 떠날 때도 사용됩니다. 문맥에 따라 뜻이 달라지므로 주의가 필요합니다.","examples":[{"en":"The plane took off at 8 a.m. sharp.","ko":"비행기가 8시에 정확히 이륙했다."},{"en":"Her career really took off after the movie.","ko":"그녀의 경력은 그 영화 이후로 급성장했다."},{"en":"Let’s take off before it gets too late.","ko":"너무 늦기 전에 떠나자."},{"en":"Sales took off once the new product launched.","ko":"신제품 출시 후 판매가 급증했다."},{"en":"The rocket took off successfully.","ko":"로켓이 성공적으로 발사됐다."}],"related":[{"slug":"lift-off","title":"Lift off","type":"synonym"},{"slug":"blast-off","title":"Blast off","type":"synonym"},{"slug":"depart","title":"Depart","type":"synonym"},{"slug":"skyrocket","title":"Skyrocket","type":"synonym"},{"slug":"catch-on","title":"Catch on","type":"synonym"}],"date":"2025-06-04T15:45"}');
