const on_a_shoestring_budget_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"on-a-shoestring-budget","title":"On a Shoestring Budget","koreanPronunciation":"온 어 슈스트링 버짓","tags":["관용구","자주 쓰는 표현"],"meaning":"매우 적은 돈으로, 빠듯한 예산으로 무언가를 한다는 의미입니다","description":"이 표현은 문자 그대로 신발 끈(shoestring)에 묶인 예산처럼 매우 적은 돈을 가지고 있음을 비유적으로 나타냅니다. 주로 돈이 부족하거나 예산이 매우 제한적인 상황에서 어떤 일을 계획하거나 실행할 때 사용됩니다. 최소한의 비용으로 최대한의 효과를 내려는 상황을 설명할 때 적합합니다.","examples":[{"en":"We managed to travel all across Europe on a shoestring budget.","ko":"우리는 빠듯한 예산으로 유럽 전역을 여행할 수 있었습니다."},{"en":"He started his business on a shoestring budget and built it into a success.","ko":"그는 적은 예산으로 사업을 시작하여 성공시켰습니다."},{"en":"They decorated their new apartment on a shoestring budget, but it looks fantastic.","ko":"그들은 빠듯한 예산으로 새 아파트를 장식했지만, 아주 멋져 보입니다."},{"en":"The film was made on a shoestring budget but received critical acclaim.","ko":"그 영화는 초저예산으로 제작되었지만 비평가들의 찬사를 받았습니다."}],"related":[{"slug":"make-ends-meet","title":"Make Ends Meet","type":"synonym","note":"간신히 생활비를 벌다"},{"slug":"be-strapped-for-cash","title":"Be Strapped For Cash","type":"synonym","note":"돈이 궁하다, 현금이 부족하다"},{"slug":"cut-costs","title":"Cut Costs","type":"synonym","note":"비용을 절감하다"}],"date":"2025-07-19T04:07"}');
