const wear_your_heart_on_your_sleeve_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"wear-your-heart-on-your-sleeve","title":"Wear Your Heart On Your Sleeve","koreanPronunciation":"웨어 유어 하트 온 유어 슬리브","tags":["관용구"],"meaning":"자신의 감정을 숨기지 않고 솔직하게 드러낸다는 의미입니다","description":"이 표현은 자신의 감정이나 생각을 다른 사람들에게 숨김없이 솔직하게 표현하는 사람을 묘사할 때 사용됩니다. 마치 심장을 소매에 달고 다니는 것처럼 모든 사람이 그들의 감정을 볼 수 있다는 비유에서 유래했으며, 감정적으로 개방적이고 투명하다는 뜻을 내포합니다.","examples":[{"en":"She always wears her heart on her sleeve, so you always know how she\'s feeling.","ko":"그녀는 항상 자신의 감정을 솔직하게 드러내서, 그녀가 어떻게 느끼는지 늘 알 수 있어요."},{"en":"It\'s hard for him to hide his emotions because he wears his heart on his sleeve.","ko":"그는 감정을 숨기지 못하고 솔직하게 드러내는 편이라 감정을 숨기기가 어렵습니다."},{"en":"Sometimes wearing your heart on your sleeve can make you vulnerable.","ko":"때때로 자신의 감정을 솔직하게 드러내는 것은 당신을 취약하게 만들 수 있습니다."},{"en":"As an artist, she felt it was important to wear her heart on her sleeve in her work.","ko":"예술가로서 그녀는 자신의 작품에 감정을 솔직하게 담는 것이 중요하다고 느꼈습니다."}],"related":[{"slug":"be-an-open-book","title":"Be An Open Book","type":"synonym","note":"비밀 없이 모든 것을 드러내는 사람을 의미합니다."},{"slug":"lay-your-cards-on-the-table","title":"Lay Your Cards On The Table","type":"synonym","note":"계획이나 의도를 솔직하게 밝힐 때 사용됩니다."},{"slug":"keep-a-poker-face","title":"Keep A Poker Face","type":"antonym","note":"감정을 드러내지 않고 무표정한 얼굴을 유지하는 것을 의미합니다."},{"slug":"keep-it-to-yourself","title":"Keep It To Yourself","type":"antonym","note":"비밀이나 감정을 다른 사람에게 말하지 않고 혼자 간직하는 것을 의미합니다."}],"date":"2025-12-02T00:00"}');
