const have_second_thoughts_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"have-second-thoughts","title":"Have Second Thoughts","koreanPronunciation":"해브 세컨드 쏘츠","tags":["관용구"],"meaning":"결정이나 의견에 대해 다시 생각하거나 의구심을 갖게 되는 것을 의미합니다.","description":"이 표현은 어떤 결정이나 계획을 세운 후에 그것이 과연 옳은 선택이었는지 의심하거나 후회하는 마음이 드는 상황을 묘사할 때 사용됩니다. 주로 새로운 정보나 관점이 생겼을 때, 또는 시간이 지나면서 마음이 변할 때 쓰입니다.","examples":[{"en":"I was going to buy the car, but then I had second thoughts.","ko":"그 차를 사려고 했었는데, 나중에 다시 생각해 보니 망설여졌어."},{"en":"She\'s having second thoughts about moving to another city.","ko":"그녀는 다른 도시로 이사 가는 것에 대해 재고하고 있어요."},{"en":"Are you sure about this decision, or are you having second thoughts?","ko":"이 결정에 대해 확신하시나요, 아니면 재고하고 계신가요?"},{"en":"He almost quit his job, but then he had second thoughts and decided to stay.","ko":"그는 일을 그만둘 뻔했지만, 다시 생각해 보니 머무르기로 결정했습니다."}],"related":[{"slug":"reconsider","title":"Reconsider","note":"어떤 결정이나 의견에 대해 다시 생각하다는 일반적인 의미."},{"slug":"waver","title":"Waver","note":"결심이나 의지가 흔들리거나 망설이는 상태를 나타냅니다."},{"slug":"back-out","title":"Back Out","note":"약속이나 합의에서 마음을 바꿔 물러나다."},{"slug":"change-ones-mind","title":"Change One\'s Mind","note":"이전의 의견이나 결정을 바꾸다."}],"date":"2025-08-18T00:00"}');
