const come_out_of_nowhere_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"come-out-of-nowhere","title":"Come Out Of Nowhere","koreanPronunciation":"컴 아웃 오브 노웨어","tags":["관용구","자주 쓰는 표현"],"meaning":"예기치 않게 갑자기 나타나거나 발생한다는 의미입니다","description":"이 표현은 어떤 사람, 사물, 사건 등이 예상치 못하게 등장하거나 발생하는 상황을 묘사할 때 사용됩니다. 전혀 예측할 수 없었던 곳에서 갑자기 나타났음을 강조하며, 주로 놀라움이나 예상 밖의 상황을 표현할 때 쓰입니다.","examples":[{"en":"The car came out of nowhere and almost hit me!","ko":"그 차가 갑자기 나타나서 저를 칠 뻔했어요!"},{"en":"Her new album came out of nowhere and topped the charts.","ko":"그녀의 새 앨범은 갑자기 등장해서 차트 1위를 차지했습니다."},{"en":"The idea for the story just came out of nowhere while I was walking.","ko":"이야기 아이디어가 걷다가 갑자기 떠올랐어요."},{"en":"He seemed to come out of nowhere to win the race, surprising everyone.","ko":"그는 갑자기 나타나서 경주에서 우승한 것 같았고, 모두를 놀라게 했습니다."}],"related":[{"slug":"appear-out-of-the-blue","title":"Appear Out Of The Blue","type":"synonym","note":"갑자기, 예상치 못하게 나타나다"},{"slug":"pop-up","title":"Pop Up","type":"synonym","note":"불쑥 나타나거나 갑자기 생겨나다"},{"slug":"materialize","title":"Materialize","type":"synonym","note":"예상치 못하게 또는 마법처럼 나타나다"}],"date":"2026-03-09T00:01"}');
;// ./blog/proceed-cautiously/content.json
const proceed_cautiously_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"proceed-cautiously","title":"Proceed Cautiously","koreanPronunciation":"프로시드 코셔슬리","tags":["자주 쓰는 표현","문장"],"meaning":"조심스럽게 진행하다, 신중하게 나아가다라는 의미입니다","description":"이 표현은 어떤 행동이나 계획을 실행할 때 서두르지 않고, 위험을 피하며, 신중하게 접근해야 함을 강조합니다. 잠재적인 문제나 위험을 충분히 고려하고 모든 단계를 주의 깊게 살펴볼 것을 권고할 때 사용됩니다.","examples":[{"en":"When dealing with sensitive information, it\'s always best to proceed cautiously.","ko":"민감한 정보를 다룰 때는 항상 조심스럽게 진행하는 것이 가장 좋습니다."},{"en":"The lawyer advised his client to proceed cautiously with the new business venture.","ko":"변호사는 의뢰인에게 새로운 사업 벤처에 대해 신중하게 진행하라고 조언했습니다."},{"en":"After the previous failure, the team decided to proceed cautiously with the next phase of the project.","ko":"이전 실패 후, 팀은 프로젝트의 다음 단계를 조심스럽게 진행하기로 결정했습니다."},{"en":"The doctor told the patient to proceed cautiously with the new medication and observe any side effects.","ko":"의사는 환자에게 새로운 약물을 조심스럽게 사용하고 부작용을 관찰하라고 말했습니다."}],"related":[{"slug":"exercise-caution","title":"Exercise Caution","type":"synonym","note":"미리 조심하거나 신중함을 보이는 행위를 의미합니다."},{"slug":"tread-carefully","title":"Tread Carefully","type":"synonym","note":"조심스럽게 행동하거나 발언하는 것을 강조합니다."},{"slug":"be-prudent","title":"Be Prudent","type":"synonym","note":"미래를 위해 현명하고 신중하게 판단하는 태도를 나타냅니다."},{"slug":"rush-in","title":"Rush In","type":"antonym","note":"생각 없이 서두르거나 섣부르게 행동하는 것을 의미합니다."},{"slug":"leap-before-you-look","title":"Leap Before You Look","type":"antonym","note":"결과를 생각하지 않고 섣부르게 행동하는 것을 비유적으로 이릅니다."}],"date":"2025-11-28T00:00"}');
;// ./blog/gain-an-advantage/content.json
const gain_an_advantage_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"gain-an-advantage","title":"Gain An Advantage","koreanPronunciation":"게인 언 어드밴티지","tags":["자주 쓰는 표현"],"meaning":"어떤 상황에서 다른 사람들보다 유리한 위치를 차지하거나 이점을 얻는 것을 의미합니다.","description":"이 표현은 경쟁이나 협상 등 다양한 상황에서 우위를 점하거나 더 나은 결과를 얻기 위해 노력하는 행동을 설명할 때 사용됩니다. 전략적인 우위를 확보하거나 단순히 특정 상황에서 더 나은 기회를 포착하는 것을 나타낼 수 있습니다. 주로 긍정적인 맥락에서 쓰이지만, 때로는 불공정한 방법으로 이득을 취하는 경우를 암시할 수도 있습니다.","examples":[{"en":"We need to gain an advantage over our competitors by innovating our products.","ko":"우리는 제품 혁신을 통해 경쟁사들보다 우위를 점해야 합니다."},{"en":"Studying abroad can help you gain an advantage in the global job market.","ko":"해외 유학은 글로벌 취업 시장에서 당신에게 이점을 줄 수 있습니다."},{"en":"The team tried to gain an advantage by studying their opponent\'s weaknesses.","ko":"그 팀은 상대방의 약점을 연구하여 우위를 차지하려고 노력했습니다."},{"en":"By waking up early, she gains an advantage in productivity before others even start their day.","ko":"일찍 일어남으로써, 그녀는 다른 사람들이 하루를 시작하기도 전에 생산성에서 이점을 얻습니다."}],"related":[{"slug":"have-the-upper-hand","title":"Have The Upper Hand","type":"synonym","note":"어떤 상황에서 통제권이나 우위를 가지고 있음을 나타냅니다."},{"slug":"get-the-edge","title":"Get The Edge","type":"synonym","note":"경쟁에서 약간의 우위를 점하거나 유리한 위치를 얻는 것을 의미합니다."},{"slug":"take-the-lead","title":"Take The Lead","type":"synonym","note":"경쟁이나 활동에서 앞서나가거나 주도권을 잡는 것을 의미합니다."},{"slug":"lose-an-advantage","title":"Lose An Advantage","type":"antonym","note":"가지고 있던 유리한 위치나 이점을 잃는 것을 의미합니다."},{"slug":"fall-behind","title":"Fall Behind","type":"antonym","note":"다른 사람들보다 뒤처지거나 뒤떨어지는 것을 의미합니다."}],"date":"2025-09-25T00:00"}');
;// ./blog/figure-out/content.json
const figure_out_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"figure-out","title":"Figure Out","koreanPronunciation":"피겨 아웃","tags":["구동사"],"meaning":"알아내다, 이해하다, 해결하다는 의미입니다.","description":"이 표현은 어떤 문제나 상황, 개념을 생각하고 분석해서 해결하거나 이해할 때 사용됩니다. 수학 문제를 풀거나 사람의 감정을 이해하려고 하거나, 기술적인 문제를 해결할 때 등 다양하게 쓰일 수 있습니다. 비격식적이고 실용적인 표현으로, 미국 영어에서 특히 많이 사용됩니다.","examples":[{"en":"I’m trying to figure out how this software works.","ko":"이 소프트웨어가 어떻게 작동하는지 알아보는 중이야."},{"en":"She finally figured out why her phone kept crashing.","ko":"그녀는 왜 핸드폰이 계속 꺼졌는지 마침내 알아냈다."},{"en":"We need to figure out a way to cut costs.","ko":"비용을 줄일 방법을 찾아야 해."},{"en":"Don’t worry, I’ll figure it out.","ko":"걱정 마, 내가 알아서 해결할게."},{"en":"It took me a while to figure him out.","ko":"그 사람을 이해하는 데 시간이 좀 걸렸어."}],"related":[{"slug":"work-out","title":"Work out","type":"synonym"},{"slug":"solve","title":"Solve","type":"synonym"},{"slug":"understand","title":"Understand","type":"synonym"},{"slug":"get-to-the-bottom-of","title":"Get to the bottom of","type":"synonym"},{"slug":"make-sense-of","title":"Make sense of","type":"synonym"}],"date":"2025-06-22T23:50"}');
;// ./blog/variety-is-the-spice-of-life/content.json
const variety_is_the_spice_of_life_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"variety-is-the-spice-of-life","title":"Variety Is the Spice of Life","koreanPronunciation":"버라이어티 이즈 더 스파이스 오브 라이프","tags":["관용구","자주 쓰는 표현"],"meaning":"다양성이 삶을 더 흥미롭고 즐겁게 만든다는 의미입니다.","description":"이 표현은 단조롭거나 반복적인 삶보다는 변화와 다양함을 추구하는 것이 삶을 풍요롭게 한다는 것을 강조합니다. 새로운 경험, 다른 환경, 다양한 사람들과의 교류 등이 인생에 활력과 재미를 더해준다는 뜻으로 사용됩니다. 변화가 지루함을 없애고 삶에 새로운 의미를 부여한다는 긍정적인 메시지를 담고 있습니다.","examples":[{"en":"I love traveling to new countries because variety is the spice of life.","ko":"새로운 나라로 여행 가는 것을 좋아해요, 왜냐하면 다양성이 삶의 묘미이기 때문이죠."},{"en":"Don\'t stick to just one hobby; remember, variety is the spice of life!","ko":"하나의 취미에만 얽매이지 마세요. 다양성이 삶의 활력소라는 것을 기억하세요!"},{"en":"Changing jobs every few years might seem unusual, but for me, variety is the spice of life.","ko":"몇 년마다 직업을 바꾸는 것이 이상해 보일 수도 있지만, 저에게는 다양성이 삶의 활력소입니다."},{"en":"Our chef always tries new ingredients and recipes; he believes variety is the spice of life.","ko":"우리 셰프는 항상 새로운 재료와 레시피를 시도해요. 그는 다양성이 삶의 묘미라고 믿죠."}],"related":[{"slug":"change-of-pace","title":"Change of Pace","type":"synonym","note":"일상적인 루틴에서 벗어나 새로운 것을 시도하는 것을 의미합니다."},{"slug":"keep-things-fresh","title":"Keep Things Fresh","type":"synonym","note":"상황이나 관계를 활기 있고 새롭게 유지하기 위해 변화를 주는 것을 강조합니다."},{"slug":"stick-to-the-routine","title":"Stick to the Routine","type":"antonym","note":"변화 없이 정해진 일상을 고수하는 것을 의미하여, 다양성을 추구하는 것과 대조됩니다."}],"date":"2026-04-03T00:01"}');
;// ./blog/just-in-time/content.json
const just_in_time_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"just-in-time","title":"Just In Time","koreanPronunciation":"저스트 인 타임","tags":["자주 쓰는 표현"],"meaning":"필요한 바로 그 순간에, 또는 늦지 않게 도착하거나 발생한다는 의미입니다","description":"이 표현은 어떤 물건이나 정보, 또는 사람이 필요한 시점에 정확히 맞춰서 제공되거나 나타날 때 사용됩니다. 특히 생산 및 재고 관리 시스템에서 \'적시 생산\'이라는 의미로 널리 쓰이며, 낭비를 줄이고 효율성을 높이는 데 중점을 둡니다. 일반적인 상황에서는 마감 시간에 맞춰 일을 끝내거나, 위기 상황에서 딱 필요한 순간에 도움을 받는 경우에도 적용될 수 있습니다.","examples":[{"en":"The delivery arrived just in time for us to finish the project.","ko":"배송이 프로젝트를 끝내기에 딱 맞춰 도착했다."},{"en":"She managed to submit her report just in time for the deadline.","ko":"그녀는 마감 시간에 맞춰 겨우 보고서를 제출했다."},{"en":"His advice came just in time to prevent a major mistake.","ko":"그의 조언은 큰 실수를 막기에 딱 적절한 때에 나왔다."},{"en":"We implemented the new security measures just in time before the attack.","ko":"우리는 공격이 발생하기 직전에 새로운 보안 조치를 시행했다."}],"related":[{"slug":"in-the-nick-of-time","title":"In the Nick of Time","type":"synonym","note":"매우 촉박한 순간에 무언가를 해낸다는 의미가 강합니다."},{"slug":"on-time","title":"On Time","type":"synonym","note":"정해진 시간이나 예상된 시간에 정확히 맞춰서 발생한다는 일반적인 의미입니다."},{"slug":"punctually","title":"Punctually","type":"synonym","note":"시간을 엄수하여, 늦지 않게 행동한다는 의미입니다."},{"slug":"behind-schedule","title":"Behind Schedule","type":"antonym","note":"정해진 시간보다 늦어져 있다는 의미입니다."},{"slug":"too-late","title":"Too Late","type":"antonym","note":"이미 기회를 놓치거나 필요한 시점을 넘겼다는 의미입니다."}],"date":"2025-09-06T00:00"}');
;// ./blog/leap-to-conclusions/content.json
const leap_to_conclusions_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"leap-to-conclusions","title":"Leap to Conclusions","koreanPronunciation":"립 투 컨클루전스","tags":["관용구","자주 쓰는 표현"],"meaning":"충분한 증거 없이 성급하게 결론을 내리는 것을 의미합니다.","description":"이 표현은 어떤 상황이나 사실에 대해 모든 정보나 증거가 충분히 확보되지 않은 상태에서 너무 빨리 판단하거나 결론을 내리는 행위를 묘사할 때 사용됩니다. 주로 잘못된 이해나 오해를 초래할 수 있음을 경고할 때 쓰이며, 좀 더 신중하게 상황을 파악해야 한다는 의미를 내포합니다.","examples":[{"en":"Don\'t leap to conclusions, let\'s wait for all the facts.","ko":"성급하게 결론 내리지 마세요, 모든 사실이 밝혀질 때까지 기다려봅시다."},{"en":"She tends to leap to conclusions without considering other possibilities.","ko":"그녀는 다른 가능성들을 고려하지 않고 성급하게 결론을 내리는 경향이 있습니다."},{"en":"Before you leap to conclusions, hear my side of the story.","ko":"성급하게 결론 내리기 전에, 제 이야기를 들어보세요."},{"en":"I know it looks bad, but try not to leap to conclusions.","ko":"상황이 안 좋게 보인다는 건 알지만, 성급하게 결론 내리지 않도록 노력하세요."}],"related":[{"slug":"jump-to-conclusions","title":"Jump to Conclusions","note":"거의 동일한 의미로 사용되며, \'leap\'보다 \'jump\'가 더 흔하게 쓰일 수 있습니다."},{"slug":"rush-to-judgment","title":"Rush to Judgment","note":"성급하게 판단을 내리거나 누군가를 단정 짓는 행위를 의미합니다."},{"slug":"make-a-snap-judgment","title":"Make a Snap Judgment","note":"깊이 생각하지 않고 즉흥적으로 판단을 내리는 것을 의미합니다."}],"date":"2025-08-09T00:00"}');
;// ./blog/don-t-rock-the-boat/content.json
const don_t_rock_the_boat_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"don-t-rock-the-boat","title":"Don\'t Rock The Boat","koreanPronunciation":"돈트 락 더 보트","tags":["관용구","자주 쓰는 표현"],"meaning":"안정된 상황을 흔들거나 문제를 일으키지 말라는 의미입니다.","description":"이 표현은 현재의 평화로운 상태나 안정적인 상황을 깨뜨리지 말라고 경고할 때 사용됩니다. 불필요한 논쟁이나 변화를 초래하여 기존의 조화를 해치는 행동을 삼가라는 뜻을 내포하고 있습니다. 특히 팀워크나 조직의 안정성이 중요할 때 자주 쓰입니다.","examples":[{"en":"Things are going smoothly right now, so don\'t rock the boat by bringing up that old argument.","ko":"지금은 일이 순조롭게 진행되고 있으니, 예전 논쟁을 꺼내서 괜히 문제를 일으키지 마세요."},{"en":"The new manager told everyone to be careful and not rock the boat during the transition period.","ko":"새로운 관리자는 전환기 동안 조심하고 문제를 일으키지 말라고 모두에게 말했습니다."},{"en":"I know you want to make changes, but sometimes it\'s better not to rock the boat.","ko":"변화를 원한다는 것을 알지만, 때로는 문제를 일으키지 않는 것이 더 좋습니다."},{"en":"She\'s always careful not to rock the boat at work to maintain peace.","ko":"그녀는 직장에서 평화를 유지하기 위해 항상 문제를 일으키지 않으려 조심합니다."}],"related":[{"slug":"don-t-make-waves","title":"Don\'t Make Waves","type":"synonym","note":"비슷하게 소란이나 문제를 일으키지 말라는 의미로 사용됩니다."},{"slug":"keep-the-peace","title":"Keep The Peace","type":"synonym","note":"갈등 없이 평화로운 상태를 유지하려 노력하는 것을 의미합니다."},{"slug":"stir-the-pot","title":"Stir The Pot","type":"antonym","note":"일부러 문제를 만들거나 상황을 더 복잡하게 만드는 것을 의미합니다."},{"slug":"make-waves","title":"Make Waves","type":"antonym","note":"논란이나 소란을 일으키는 것을 의미합니다."}],"date":"2025-11-05T00:00"}');
;// ./blog/micro-manager/content.json
const micro_manager_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"micro-manager","title":"Micro-Manager","koreanPronunciation":"마이크로 매니저","tags":["자주 쓰는 표현"],"meaning":"사소한 일까지 모두 통제하려 들며 직원들에게 지나치게 간섭하는 관리자를 의미합니다","description":"이 표현은 직원들의 자율성을 존중하지 않고 모든 업무 과정과 결과에 대해 세세하게 지시하고 확인하려는 관리 스타일을 비판적으로 묘사할 때 사용됩니다. 이러한 방식은 직원들의 창의성과 생산성을 저해하며, 불신과 답답함을 유발할 수 있습니다. 마이크로 매니저는 종종 불안감이나 완벽주의적인 성향 때문에 이런 행동을 보일 수 있으며, 팀원들에게는 큰 스트레스 요인이 될 수 있습니다.","examples":[{"en":"My new boss is a complete micro-manager; she wants to approve every single email before it goes out.","ko":"우리 새 상사는 완전 마이크로 매니저야. 이메일 하나하나 나가는 것까지 다 승인받으려고 해."},{"en":"Working for a micro-manager can be exhausting because you feel like you\'re constantly being watched.","ko":"마이크로 매니저 밑에서 일하는 것은 끊임없이 감시당하는 기분이 들어서 지칠 수 있습니다."},{"en":"Good leaders empower their teams, they don\'t act like micro-managers.","ko":"좋은 리더는 팀에 권한을 부여하지, 마이크로 매니저처럼 행동하지 않습니다."},{"en":"He\'s trying to overcome his tendency to be a micro-manager and delegate more tasks.","ko":"그는 마이크로 매니저가 되려는 자신의 경향을 극복하고 더 많은 업무를 위임하려고 노력 중입니다."}],"related":[{"slug":"control-freak","title":"Control Freak","type":"synonym","note":"모든 것을 통제하려 하는 사람을 지칭하는 비슷한 표현"},{"slug":"helicopter-parent","title":"Helicopter Parent","type":"synonym","note":"부모-자녀 관계에서 자녀에게 과도하게 간섭하고 통제하는 유형을 비유적으로 표현"},{"slug":"hands-off-manager","title":"Hands-Off Manager","type":"antonym","note":"직원들에게 자율성을 많이 부여하고 개입을 최소화하는 관리자"},{"slug":"empowerer","title":"Empowerer","type":"antonym","note":"다른 사람에게 권한을 위임하고 자율성을 주어 능력을 발휘하도록 돕는 사람"}],"date":"2025-11-13T00:01"}');
;// ./blog/fall-short/content.json
const fall_short_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"fall-short","title":"Fall Short","koreanPronunciation":"폴 쇼트","tags":["구동사","자주 쓰는 표현"],"meaning":"기대치나 목표에 미치지 못하거나, 부족하거나, 실패하는 것의 의미입니다.","description":"이 표현은 어떤 기준이나 기대에 부합하지 못하거나, 특정 목표에 도달하지 못했을 때 사용됩니다. 주로 노력이나 성과가 충분하지 않았음을 나타낼 때 쓰이며, 아쉬움이나 실망감을 표현할 수 있습니다. 개인의 성과, 프로젝트 결과, 제품의 품질 등 다양한 상황에서 목표에 미치지 못할 경우에 활용됩니다.","examples":[{"en":"His performance fell short of our expectations.","ko":"그의 성과는 우리의 기대에 미치지 못했습니다."},{"en":"The company\'s profits fell short of the projected figures.","ko":"회사의 이익은 예상 수치에 미치지 못했습니다."},{"en":"Despite their best efforts, they fell short of winning the championship.","ko":"최선을 다했음에도 불구하고, 그들은 챔피언십 우승에 실패했습니다."},{"en":"The budget for the project fell short, so we had to cut some features.","ko":"프로젝트 예산이 부족해서 몇 가지 기능을 잘라내야 했습니다."}],"related":[{"slug":"miss-the-mark","title":"Miss The Mark","type":"synonym","note":"목표나 기대를 달성하지 못하다"},{"slug":"come-up-short","title":"Come Up Short","type":"synonym","note":"기대치에 미달하거나 부족하다"},{"slug":"not-measure-up","title":"Not Measure Up","type":"synonym","note":"특정 기준이나 요구 사항을 충족하지 못하다"},{"slug":"live-up-to-expectations","title":"Live Up To Expectations","type":"antonym","note":"기대에 부응하다, 기대만큼 잘 해내다"}],"date":"2026-03-25T00:01"}');
;// ./blog/deliver-the-news/content.json
const deliver_the_news_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"deliver-the-news","title":"Deliver The News","koreanPronunciation":"딜리버 더 뉴스","tags":["관용구","자주 쓰는 표현"],"meaning":"특정 소식, 특히 중요하거나 민감한 소식을 다른 사람에게 전달하는 것을 의미합니다.","description":"이 표현은 단순히 정보를 전달하는 행위를 넘어서, 그 소식이 듣는 사람에게 미칠 영향을 고려하며 신중하게 전달하는 뉘앙스를 포함합니다. 특히 좋지 않거나 충격적인 소식을 전할 때 자주 사용되지만, 좋은 소식을 전할 때도 쓰일 수 있습니다.","examples":[{"en":"Someone has to deliver the news to her parents.","ko":"누군가는 그녀의 부모님께 소식을 전해야 합니다."},{"en":"I hate having to deliver bad news, but it\'s my job.","ko":"나쁜 소식을 전해야 하는 게 정말 싫지만, 제 일이니까요."},{"en":"The doctor delivered the news of his recovery with a smile.","ko":"의사는 그의 회복 소식을 미소와 함께 전했습니다."},{"en":"Who\'s going to deliver the tough news to the team about the budget cuts?","ko":"누가 예산 삭감에 대한 어려운 소식을 팀에 전할 건가요?"},{"en":"It was difficult to deliver the news of the company\'s restructuring.","ko":"회사 구조조정에 대한 소식을 전하기가 어려웠습니다."}],"related":[{"slug":"break-the-news","title":"Break The News","type":"synonym","note":"주로 좋지 않거나 충격적인 소식을 전달할 때 사용됩니다."},{"slug":"inform-someone","title":"Inform Someone","type":"synonym","note":"어떤 사실이나 정보에 대해 누구에게 알려주는 일반적인 표현입니다."},{"slug":"convey-information","title":"Convey Information","type":"synonym","note":"좀 더 형식적이거나 일반적인 맥락에서 정보를 전달하는 행위를 나타냅니다."},{"slug":"bear-bad-news","title":"Bear Bad News","type":"synonym","note":"나쁜 소식을 가지고 오거나 전달하는 것을 의미합니다."}],"date":"2025-12-20T00:00"}');
;// ./blog/the-ball-is-in-your-court/content.json
const the_ball_is_in_your_court_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"the-ball-is-in-your-court","title":"The Ball Is In Your Court","koreanPronunciation":"더 볼 이즈 인 유어 코트","tags":["관용구","자주 쓰는 표현"],"meaning":"이제 상대방이 결정하거나 행동할 차례라는 의미입니다.","description":"이 표현은 테니스나 농구와 같은 구기 종목에서 공이 상대방 코트로 넘어간 상황을 비유합니다. 즉, 특정 상황이나 문제에 대한 다음 행동이나 결정권이 상대방에게 있다는 것을 나타냅니다. 주로 어떤 제안이나 결정 후에 상대방의 응답이나 조치를 기다릴 때 사용됩니다.","examples":[{"en":"I\'ve made my offer; now the ball is in your court.","ko":"제 제안은 했습니다. 이제 당신이 결정할 차례입니다."},{"en":"We\'ve presented all the facts, so the ball is in their court to make a decision.","ko":"우리는 모든 사실을 제시했으니, 이제 그들이 결정을 내릴 차례입니다."},{"en":"After our discussion, the ball is in your court to decide how to proceed.","ko":"우리의 논의 후에, 어떻게 진행할지 결정하는 것은 당신에게 달려 있습니다."},{"en":"I\'ve finished my part of the project; now the ball is in your court to review it.","ko":"저는 프로젝트 제 부분을 마쳤습니다. 이제 당신이 검토할 차례입니다."},{"en":"She sent the proposal to the client. Now the ball is in their court to respond.","ko":"그녀는 고객에게 제안서를 보냈습니다. 이제 그들이 응답할 차례입니다."}],"related":[{"slug":"the-onus-is-on-you","title":"The Onus Is On You","type":"synonym","note":"책임이나 의무가 당신에게 있음을 강조합니다."},{"slug":"its-your-move","title":"It\'s Your Move","type":"synonym","note":"다음 행동을 할 차례가 당신에게 왔다는 의미로, 좀 더 직접적입니다."},{"slug":"have-ones-hands-tied","title":"Have One\'s Hands Tied","type":"antonym","note":"자유롭게 행동하거나 결정할 수 없는 상황을 나타냅니다."}],"date":"2026-02-02T00:00"}');
;// ./blog/blow-a-fuse/content.json
const blow_a_fuse_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"blow-a-fuse","title":"Blow A Fuse","koreanPronunciation":"블로우 어 퓨즈","tags":["관용구","자주 쓰는 표현"],"meaning":"매우 화를 내거나 격분하는 의미입니다","description":"이 표현은 전기 회로의 퓨즈가 과부하로 끊어져 작동을 멈추는 것에 비유하여, 사람이 극도로 화를 내거나 흥분하여 이성을 잃는 모습을 나타냅니다. 주로 갑작스럽고 강렬한 분노를 표현할 때 사용됩니다.","examples":[{"en":"When he found out his car was scratched, he completely blew a fuse.","ko":"그는 차에 흠집이 난 것을 알았을 때 완전히 이성을 잃고 격분했다."},{"en":"Don\'t tell her about the broken vase, or she\'ll blow a fuse.","ko":"그녀에게 깨진 꽃병에 대해 말하지 마세요, 안 그러면 그녀가 격분할 거예요."},{"en":"My dad always blows a fuse when I leave my room messy.","ko":"아빠는 내가 방을 어지럽게 두면 항상 화를 내신다."},{"en":"The manager blew a fuse after seeing the sales report.","ko":"매니저는 판매 보고서를 본 후에 격분했다."}],"related":[{"slug":"hit-the-roof","title":"Hit The Roof","type":"synonym","note":"매우 화가 나다, 격분하다"},{"slug":"go-ballistic","title":"Go Ballistic","type":"synonym","note":"몹시 화를 내다, 격분하다"},{"slug":"lose-one-s-temper","title":"Lose One\'s Temper","type":"synonym","note":"화를 내다, 이성을 잃다"}],"date":"2025-10-02T00:00"}');
;// ./blog/close-but-no-cigar/content.json
const close_but_no_cigar_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"close-but-no-cigar","title":"Close But No Cigar","koreanPronunciation":"클로스 벗 노 시가","tags":["관용구","자주 쓰는 표현"],"meaning":"아깝게도 목표나 성공에 도달하지 못했을 때 사용하는 의미입니다","description":"이 표현은 어떤 시도나 노력이 거의 성공할 뻔했지만, 결국 마지막 단계에서 실패했음을 나타낼 때 사용됩니다. 목표에 아주 근접했지만, 최종적인 성취는 이루지 못했음을 강조합니다. 주로 게임 쇼에서 상품을 거의 획득할 뻔했지만, 마지막 순간에 놓쳤을 때 사회자가 사용하던 문구에서 유래했습니다.","examples":[{"en":"You almost guessed the correct answer, close but no cigar!","ko":"거의 정답을 맞출 뻔했지만, 아깝게도 틀렸네요!"},{"en":"I tried to catch the train, but I missed it by a minute. Close but no cigar.","ko":"기차를 잡으려 했지만, 1분 차이로 놓쳤어요. 아깝게도 실패했네요."},{"en":"He came in second place in the race. Close but no cigar for the gold medal.","ko":"그는 경주에서 2위를 차지했어요. 아깝게도 금메달은 놓쳤네요."},{"en":"We almost closed the deal, but the client decided to go with another company. Close but no cigar.","ko":"거의 계약을 성사시킬 뻔했지만, 고객이 다른 회사와 진행하기로 결정했어요. 아쉽게도 실패했죠."},{"en":"I found a perfect apartment, but it was already rented out. Close but no cigar.","ko":"완벽한 아파트를 찾았지만, 이미 임대된 상태였어요. 아깝게 놓쳤네요."}],"related":[{"slug":"almost-there","title":"Almost There","type":"synonym","note":"목표 달성에 거의 도달했음을 나타내지만, 아직 완전히 성공한 것은 아님을 의미합니다."},{"slug":"missed-by-a-hairs-breadth","title":"Missed By A Hair\'s Breadth","type":"synonym","note":"간발의 차이로 무언가를 놓쳤을 때 사용하며, \'close but no cigar\'와 유사하게 아쉬움을 표현합니다."},{"slug":"come-up-short","title":"Come Up Short","type":"synonym","note":"목표에 미치지 못하거나 예상보다 부족했음을 나타냅니다."},{"slug":"nailed-it","title":"Nailed It","type":"antonym","note":"완벽하게 성공하거나 목표를 정확히 달성했을 때 사용됩니다."},{"slug":"hit-the-bullseye","title":"Hit The Bullseye","type":"antonym","note":"과녁의 중앙을 맞추듯 목표를 정확하고 완벽하게 달성했음을 의미합니다."}],"date":"2026-01-21T00:00"}');
;// ./blog/pay-back/content.json
const pay_back_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"pay-back","title":"Pay Back","koreanPronunciation":"페이 백","tags":["구동사","자주 쓰는 표현"],"meaning":"빌린 돈이나 은혜를 갚거나, 또는 어떤 행동에 대해 복수하는 것을 의미입니다.","description":"이 표현은 크게 두 가지 의미로 사용됩니다. 첫째, 누군가에게 빌린 돈이나 물질적인 것을 돌려주는 것을 의미합니다. 둘째, 누군가에게 당한 일에 대해 똑같이 되갚아주는, 즉 복수나 보복의 의미로 사용될 수 있습니다. 긍정적인 맥락에서는 은혜를 갚는 의미로도 쓰이며, 부정적인 맥락에서는 해를 끼친 것에 대한 응징을 나타냅니다.","examples":[{"en":"I need to pay back the money I borrowed from my brother.","ko":"형에게 빌린 돈을 갚아야 해."},{"en":"She swore to pay him back for betraying her.","ko":"그녀는 자신을 배신한 그에게 복수하겠다고 맹세했다."},{"en":"After all your help, I don\'t know how I can ever pay you back.","ko":"네가 도와준 것에 대해 어떻게 보답해야 할지 모르겠어."},{"en":"He finally paid back his student loans.","ko":"그는 마침내 학자금 대출을 갚았다."},{"en":"Don\'t worry, I\'ll pay you back tomorrow.","ko":"걱정 마, 내일 갚을게."}],"related":[{"slug":"repay","title":"Repay","type":"synonym","note":"주로 금전적인 빚을 갚는 행위에 초점."},{"slug":"get-revenge","title":"Get Revenge","type":"synonym","note":"주로 복수나 보복의 의미에 초점."},{"slug":"return-the-favor","title":"Return the Favor","type":"synonym","note":"누군가에게 받은 도움이나 친절을 되갚는 의미."},{"slug":"settle-a-score","title":"Settle a Score","type":"synonym","note":"과거의 불화나 원한을 갚거나 복수하는 의미."}],"date":"2025-07-21T00:00"}');
