const keep_your_eyes_peeled_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"keep-your-eyes-peeled","title":"Keep Your Eyes Peeled","koreanPronunciation":"킵 유어 아이즈 필드","tags":["관용구","자주 쓰는 표현"],"meaning":"주변을 잘 살피고 주의 깊게 관찰하라는 의미입니다.","description":"이 표현은 무언가를 찾거나 위험에 대비하여 주변을 신중하게 주시해야 할 때 사용됩니다. \'껍질을 벗기다\'는 뜻의 \'peel\'에서 유래하여, 마치 눈꺼풀을 벗겨내듯이 눈을 크게 뜨고 집중하여 보라는 비유적인 의미를 담고 있습니다.","examples":[{"en":"When you\'re in the city, you have to keep your eyes peeled for pickpockets.","ko":"도시에 있을 때는 소매치기를 조심하며 주변을 잘 살펴야 해요."},{"en":"We need to keep our eyes peeled for the exit sign; it\'s easy to miss.","ko":"출구 표지판을 잘 봐야 해. 놓치기 쉬워."},{"en":"The detective told the witnesses to keep their eyes peeled for any unusual cars.","ko":"형사는 증인들에게 특이한 차량이 있는지 주의 깊게 살펴보라고 말했습니다."},{"en":"I\'ll keep my eyes peeled for a good deal on flights.","ko":"항공권 좋은 할인이 있는지 제가 계속 주시할게요."}],"related":[{"slug":"be-on-the-lookout","title":"Be On The Lookout","type":"synonym","note":"특정 위험이나 대상을 경계하며 찾다."},{"slug":"pay-attention","title":"Pay Attention","type":"synonym","note":"주의를 기울이다, 집중하다."},{"slug":"stay-alert","title":"Stay Alert","type":"synonym","note":"경계를 늦추지 않고 깨어 있다."}],"date":"2026-04-02T00:00"}');
