const take_a_risk_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"take-a-risk","title":"Take a Risk","koreanPronunciation":"테이크 어 리스크","tags":["관용구","자주 쓰는 표현"],"meaning":"안 좋은 결과가 초래될 수도 있지만, 동시에 좋은 결과도 기대할 수 있는 어떤 행동을 하는 것을 의미합니다.","description":"이 표현은 불확실한 상황에서 성공이나 이득을 얻기 위해 위험을 감수하는 행위를 설명할 때 사용됩니다. 때로는 모험적인 시도가 큰 보상으로 이어질 수 있음을 암시하기도 합니다. 단순히 위험을 감수하는 것을 넘어, 잠재적인 이점을 위해 기꺼이 위험을 받아들이는 태도를 나타냅니다.","examples":[{"en":"Sometimes you have to take a risk to achieve great success.","ko":"때로는 큰 성공을 이루기 위해 위험을 감수해야 합니다."},{"en":"She decided to take a risk and start her own business.","ko":"그녀는 위험을 감수하고 자신의 사업을 시작하기로 결심했습니다."},{"en":"Investing in the stock market always involves taking a risk.","ko":"주식 시장에 투자하는 것은 항상 위험을 감수하는 것을 포함합니다."},{"en":"He was afraid to take a risk, so he missed out on a great opportunity.","ko":"그는 위험을 감수하는 것을 두려워해서 좋은 기회를 놓쳤습니다."}],"related":[{"slug":"chance-it","title":"Chance It","type":"synonym"},{"slug":"go-out-on-a-limb","title":"Go Out on a Limb","type":"synonym","note":"특히 남들의 반대나 비판을 무릅쓰고 위험한 입장에 서는 것을 의미합니다."},{"slug":"put-ones-neck-on-the-line","title":"Put One\'s Neck on the Line","type":"synonym","note":"자신의 평판이나 안전을 위태롭게 하는 위험을 감수하는 것을 의미합니다."},{"slug":"play-it-safe","title":"Play It Safe","type":"antonym"}],"date":"2025-09-20T00:00"}');
;// ./blog/the-onus-is-on-you/content.json
const the_onus_is_on_you_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"the-onus-is-on-you","title":"The Onus Is On You","koreanPronunciation":"디 오너스 이즈 온 유","tags":["관용구","자주 쓰는 표현"],"meaning":"특정 상황에 대한 책임이나 의무가 당신에게 있다는 의미입니다.","description":"이 표현은 어떤 상황이나 문제에 대한 책임, 의무, 또는 부담이 특정 개인이나 집단에게 있음을 명확히 할 때 사용됩니다. 주로 다른 사람에게 해결책을 찾거나, 행동을 취하거나, 결과에 대한 책임을 지도록 요구할 때 쓰입니다.","examples":[{"en":"The deadline is tomorrow, so the onus is on you to finish the report.","ko":"마감일은 내일이니, 보고서를 끝내는 책임은 당신에게 있습니다."},{"en":"After the manager resigned, the onus was on the team leader to guide the project.","ko":"매니저가 사임한 후, 프로젝트를 이끌 책임은 팀장에게 있었습니다."},{"en":"If you want to achieve your goals, the onus is on you to work hard.","ko":"목표를 달성하고 싶다면, 열심히 노력할 책임은 당신에게 있습니다."},{"en":"They made a promise, so the onus is on them to deliver what they promised.","ko":"그들이 약속했으니, 약속한 것을 이행할 책임은 그들에게 있습니다."},{"en":"The company made the mistake, so the onus is on them to apologize and fix it.","ko":"회사가 실수를 저질렀으니, 사과하고 수정할 책임은 그들에게 있습니다."}],"related":[{"slug":"the-ball-is-in-your-court","title":"The ball is in your court","type":"synonym","note":"다음 행동을 취하거나 결정을 내릴 책임이 당신에게 있다는 의미"},{"slug":"its-up-to-you","title":"It\'s up to you","type":"synonym","note":"선택이나 결정의 책임이 당신에게 있다는 직접적인 표현"},{"slug":"its-your-responsibility","title":"It\'s your responsibility","type":"synonym","note":"어떤 일을 할 의무나 책임이 당신에게 있다는 직접적인 표현"}],"date":"2026-02-02T00:00"}');
;// ./blog/open-up/content.json
const open_up_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"open-up","title":"Open Up","koreanPronunciation":"오픈 업","tags":["구동사","자주 쓰는 표현"],"meaning":"마음이나 감정을 솔직하게 털어놓거나, 사업 등을 시작하거나, 어떤 것에 대한 접근을 허용한다는 의미입니다.","description":"이 표현은 여러 가지 의미로 사용될 수 있습니다. 주로 두 가지 큰 맥락에서 사용되는데, 첫째는 자신의 감정이나 생각, 비밀 등을 타인에게 솔직하게 털어놓는다는 의미입니다. 예를 들어, \'He needs to open up about his problems\'는 그가 자신의 문제에 대해 솔직하게 이야기해야 한다는 뜻입니다. 둘째는 새로운 사업이나 건물을 시작하거나 개방한다는 의미입니다. 예를 들어, \'The new restaurant will open up next month\'는 새 레스토랑이 다음 달에 문을 연다는 뜻입니다. 또한, 어떤 것에 대한 접근을 가능하게 하거나 기회를 제공하는 의미로도 쓰일 수 있습니다.","examples":[{"en":"It\'s hard for him to open up to new people.","ko":"그는 새로운 사람들에게 마음을 여는 것을 어려워합니다."},{"en":"The company plans to open up a new branch in Asia.","ko":"그 회사는 아시아에 새 지점을 열 계획입니다."},{"en":"We need to open up the discussion to include more diverse viewpoints.","ko":"우리는 더 다양한 관점을 포함하기 위해 토론을 개방할 필요가 있습니다."},{"en":"Don\'t be afraid to open up and share what you\'re feeling.","ko":"두려워하지 말고 마음을 열어 당신의 감정을 공유하세요."}],"related":[{"slug":"confide-in-someone","title":"Confide In Someone","type":"synonym","note":"비밀이나 개인적인 이야기를 털어놓다."},{"slug":"bare-your-soul","title":"Bare Your Soul","type":"synonym","note":"가장 깊은 감정이나 비밀을 드러내다."},{"slug":"keep-to-oneself","title":"Keep To Oneself","type":"antonym","note":"자신의 생각이나 감정을 다른 사람에게 말하지 않고 혼자 간직하다."},{"slug":"start-a-new-venture","title":"Start A New Venture","type":"synonym","note":"새로운 사업이나 프로젝트를 시작하다."},{"slug":"be-forthcoming","title":"Be Forthcoming","type":"synonym","note":"정보나 감정을 기꺼이 드러내다."}],"date":"2025-12-02T00:01"}');
;// ./blog/go-to-bed/content.json
const go_to_bed_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"go-to-bed","title":"Go To Bed","koreanPronunciation":"고 투 베드","tags":["자주 쓰는 표현"],"meaning":"잠자리에 들다, 취침하다 의 의미입니다","description":"이 표현은 하루를 마치고 잠을 자기 위해 침실로 가는 행위를 나타냅니다. 매우 기본적인 동사구로 일상생활에서 가장 흔하게 사용되는 표현 중 하나입니다. 주로 피곤하거나 잠을 잘 시간이 되었을 때 사용합니다.","examples":[{"en":"It\'s getting late, I should go to bed.","ko":"늦었으니 이제 자러 가야겠어."},{"en":"Did you go to bed early last night?","ko":"어젯밤에 일찍 잤니?"},{"en":"The children usually go to bed at 9 PM.","ko":"아이들은 보통 밤 9시에 잠자리에 듭니다."},{"en":"I\'m so tired, I just want to go to bed.","ko":"너무 피곤해서 그냥 자러 가고 싶어요."}],"related":[{"slug":"turn-in","title":"Turn In","type":"synonym","note":"잠자리에 들다는 의미로, \'go to bed\'와 유사하게 사용됩니다."},{"slug":"wake-up","title":"Wake Up","type":"antonym","note":"잠에서 깨어나는 것을 의미하는 반대 표현입니다."},{"slug":"get-some-shut-eye","title":"Get Some Shut-Eye","type":"synonym","note":"비격식적으로 잠을 자다, 눈을 좀 붙이다는 의미입니다."}],"date":"2025-10-04T00:00"}');
;// ./blog/go-back-on-ones-word/content.json
const go_back_on_ones_word_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"go-back-on-ones-word","title":"Go Back On One\'s Word","koreanPronunciation":"고 백 온 원스 워드","tags":["관용구","자주 쓰는 표현"],"meaning":"약속이나 한 말을 어기는 것의미입니다.","description":"이 표현은 이전에 했던 약속이나 다짐을 지키지 않거나, 말을 번복하는 상황을 설명할 때 사용됩니다. 주로 신뢰를 저버리는 행위를 강조하며, 부정적인 의미로 쓰이는 경우가 많습니다.","examples":[{"en":"He promised to help me, but he went back on his word at the last minute.","ko":"그는 나를 돕겠다고 약속했지만, 마지막 순간에 약속을 어겼다."},{"en":"If you go back on your word too often, people will stop trusting you.","ko":"약속을 너무 자주 어기면 사람들은 당신을 믿지 않게 될 것이다."},{"en":"The politician went back on his campaign promises after he was elected.","ko":"그 정치인은 당선된 후에 선거 공약을 뒤집었다."},{"en":"It\'s important not to go back on your word if you want to maintain your reputation.","ko":"명성을 유지하고 싶다면 약속을 어기지 않는 것이 중요합니다."}],"related":[{"slug":"break-a-promise","title":"Break A Promise","type":"synonym"},{"slug":"renege-on","title":"Renege On","type":"synonym","note":"주로 계약이나 합의 등을 파기할 때 사용됩니다."},{"slug":"keep-ones-word","title":"Keep One\'s Word","type":"antonym"}],"date":"2025-10-17T00:00"}');
;// ./blog/lounge-around/content.json
const lounge_around_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"lounge-around","title":"Lounge Around","koreanPronunciation":"라운지 어라운드","tags":["구동사","자주 쓰는 표현"],"meaning":"느긋하게 빈둥거리거나 쉬는 것을 의미입니다.","description":"이 표현은 특별한 활동 없이 게으르게 시간을 보내거나 편안하게 쉬는 상황을 묘사할 때 사용됩니다. 주로 여가 시간에 집이나 편안한 장소에서 아무것도 하지 않고 느긋하게 휴식하는 것을 뜻합니다.","examples":[{"en":"On weekends, I love to just lounge around the house.","ko":"주말에는 그저 집에서 빈둥거리는 것을 좋아해요."},{"en":"Instead of going out, let\'s just lounge around and watch movies today.","ko":"나가기보다는 오늘은 그냥 빈둥거리며 영화나 봐요."},{"en":"He spent the whole afternoon lounging around by the pool.","ko":"그는 오후 내내 수영장 옆에서 빈둥거리며 시간을 보냈어요."},{"en":"After a long week, all I want to do is lounge around and do nothing.","ko":"긴 한 주를 보내고 나면, 제가 하고 싶은 것은 그저 빈둥거리며 아무것도 안 하는 것뿐이에요."}],"related":[{"slug":"loaf-around","title":"Loaf Around","type":"synonym","note":"일없이 빈둥거리며 시간을 보내는 것을 의미합니다."},{"slug":"kick-back","title":"Kick Back","type":"synonym","note":"편안하게 휴식을 취하는 것을 의미합니다."},{"slug":"idle-away","title":"Idle Away","type":"synonym","note":"특별한 일 없이 한가로이 시간을 보내는 것을 의미합니다."},{"slug":"get-busy","title":"Get Busy","type":"antonym","note":"바쁘게 움직이거나 활동을 시작하는 것을 의미합니다."}],"date":"2025-11-22T00:01"}');
;// ./blog/get-on-ones-nerves/content.json
const get_on_ones_nerves_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"get-on-ones-nerves","title":"Get On One\'s Nerves","koreanPronunciation":"겟 온 원스 너브스","tags":["관용구","자주 쓰는 표현"],"meaning":"누군가를 계속해서 짜증 나게 하거나 귀찮게 하는 의미입니다.","description":"이 표현은 다른 사람의 행동, 소리, 습관 등이 너무 거슬려서 인내심을 잃게 만들거나 불쾌감을 유발할 때 사용됩니다. \'nerves\'(신경)는 사람의 감각이나 정신적 상태를 나타내며, 그 위에 \'get on\' 한다는 것은 신경을 건드려 자극하거나 흥분시키는 것을 비유적으로 의미합니다. 주로 반복적이고 사소한 일로 인해 발생하는 짜증에 사용됩니다.","examples":[{"en":"That constant tapping sound is really getting on my nerves.","ko":"저 계속되는 두드리는 소리가 정말 신경을 건드려요."},{"en":"His habit of leaving dirty dishes in the sink always gets on my nerves.","ko":"그가 싱크대에 더러운 접시를 남겨두는 습관은 늘 내 신경을 거슬리게 해."},{"en":"Please stop humming, it\'s starting to get on my nerves.","ko":"제발 콧노래 좀 그만 불러, 짜증 나기 시작했어."},{"en":"Her constant complaining began to get on everyone\'s nerves.","ko":"그녀의 끊임없는 불평은 모두의 신경을 건드리기 시작했다."}],"related":[{"slug":"drive-someone-crazy","title":"Drive Someone Crazy","type":"synonym","note":"더 강하게 누군가를 짜증 나게 하거나 미치게 만들 정도로 성가시게 할 때 사용합니다."},{"slug":"rub-someone-the-wrong-way","title":"Rub Someone The Wrong Way","type":"synonym","note":"말이나 행동이 상대방의 기분을 상하게 하거나 불쾌감을 줄 때 사용합니다."},{"slug":"irritate-someone","title":"Irritate Someone","type":"synonym","note":"\\"get on one\'s nerves\\"와 유사하게 누군가를 짜증 나게 하거나 화나게 할 때 사용되는 일반적인 표현입니다."},{"slug":"soothe-someone","title":"Soothe Someone","type":"antonym","note":"누군가를 진정시키고 편안하게 할 때 사용합니다."}],"date":"2026-03-05T00:01"}');
;// ./blog/come-what-may/content.json
const come_what_may_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"come-what-may","title":"Come What May","koreanPronunciation":"컴 왓 메이","tags":["관용구","자주 쓰는 표현"],"meaning":"미래에 어떤 상황이 발생하더라도 흔들림 없이 행동하거나 태도를 유지하겠다는 의미입니다.","description":"이 표현은 미래에 어떤 일이 닥치든 상관없이 어떤 행동을 하거나 어떤 태도를 유지하겠다는 강한 의지를 나타낼 때 사용됩니다. 주로 역경이나 불확실한 상황에 대한 결연한 태도를 강조할 때 쓰이며, \'무슨 일이 있어도\' 또는 \'어떤 어려움이 있더라도\'와 같은 뉘앙스를 가집니다.","examples":[{"en":"I will stand by you, come what may.","ko":"무슨 일이 있어도 당신 곁에 있을 거예요."},{"en":"They decided to pursue their dream, come what may.","ko":"그들은 무슨 일이 있더라도 꿈을 추구하기로 결정했습니다."},{"en":"Come what may, we must continue our efforts.","ko":"무슨 일이 있어도 우리는 노력을 계속해야 합니다."},{"en":"She promised to support him, come what may.","ko":"그녀는 무슨 일이 있더라도 그를 지지하겠다고 약속했습니다."}],"related":[{"slug":"no-matter-what","title":"No Matter What","type":"synonym","note":"이와 거의 동일한 의미로, \'무슨 일이 있어도\' 또는 \'어떻게 되든 상관없이\'를 강조합니다."},{"slug":"whatever-happens","title":"Whatever Happens","type":"synonym","note":"\'무슨 일이 일어나든\'이라는 뜻으로, 미래의 불확실한 상황을 받아들이는 뉘앙스가 있습니다."},{"slug":"through-thick-and-thin","title":"Through Thick and Thin","type":"synonym","note":"좋을 때나 힘들 때나 변함없이 함께 한다는 의미로, 관계나 지지의 끈기를 강조합니다."},{"slug":"rain-or-shine","title":"Rain or Shine","type":"synonym","note":"날씨가 어떻든 상관없이 무언가를 하겠다는 뜻으로, 상황에 관계없이 약속을 지키거나 행동을 강행할 때 사용됩니다."}],"date":"2025-07-20T00:00"}');
;// ./blog/put-someone-in-their-place/content.json
const put_someone_in_their_place_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"put-someone-in-their-place","title":"Put Someone In Their Place","koreanPronunciation":"풋 썸원 인 데어 플레이스","tags":["관용구","자주 쓰는 표현"],"meaning":"건방지거나 무례하게 구는 사람에게 그들의 위치를 상기시키거나 겸손하게 만드는 것을 의미입니다.","description":"이 표현은 주로 다른 사람을 무시하거나 지나치게 거만하게 행동하는 사람에게 적절한 방법으로 그들의 행동이 잘못되었음을 깨닫게 하거나, 그들이 생각하는 것만큼 중요하지 않다는 것을 보여줄 때 사용됩니다. 이는 직접적인 비난보다는 상황을 통해 상대를 제어하는 뉘앙스를 가집니다.","examples":[{"en":"The new manager was a bit arrogant, but his team quickly put him in his place.","ko":"새로운 매니저는 다소 거만했지만, 그의 팀이 빠르게 그를 겸손하게 만들었습니다."},{"en":"She tried to dominate the conversation, but I managed to put her in her place politely.","ko":"그녀는 대화를 지배하려 했지만, 저는 정중하게 그녀를 제자리로 돌려놓을 수 있었습니다."},{"en":"Sometimes you have to put rude customers in their place to maintain respect.","ko":"때로는 무례한 고객들을 제자리로 돌려놓아 존중을 유지해야 합니다."},{"en":"His boss had to put him in his place after he challenged every decision.","ko":"그의 상사는 그가 모든 결정에 도전하자 그를 겸손하게 만들 필요가 있었습니다."},{"en":"Don\'t let him talk down to you; you need to put him in his place.","ko":"그가 당신을 얕보게 두지 마세요. 그를 겸손하게 만들 필요가 있습니다."}],"related":[{"slug":"cut-someone-down-to-size","title":"Cut Someone Down To Size","type":"synonym","note":"누군가의 거만함을 꺾고 현실을 직시하게 만든다는 점에서 유사합니다."},{"slug":"humble-someone","title":"Humble Someone","type":"synonym","note":"직접적으로 누군가를 겸손하게 만든다는 의미를 가집니다."},{"slug":"boost-someone\'s-ego","title":"Boost Someone\'s Ego","type":"antonym","note":"누군가의 자존감을 높여주거나 우쭐하게 만드는 것과 반대됩니다."}],"date":"2026-02-03T00:00"}');
;// ./blog/back-to-the-drawing-board/content.json
const back_to_the_drawing_board_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"back-to-the-drawing-board","title":"Back To The Drawing Board","koreanPronunciation":"백 투 더 드로잉 보드","tags":["관용구","자주 쓰는 표현"],"meaning":"계획이나 시도가 실패하여 처음부터 다시 시작해야 하는 상황을 의미합니다.","description":"이 표현은 어떤 계획이나 프로젝트가 실패하거나 예상대로 진행되지 않았을 때, 근본적으로 다시 생각하고 처음부터 새로운 접근 방식을 찾아 시작해야 함을 나타냅니다. 마치 건축가나 디자이너가 원래의 설계가 잘못되어 드로잉 보드로 돌아가 새롭게 구상하는 모습에서 유래했습니다. 실패를 인정하고 새로운 시작을 할 때 사용됩니다.","examples":[{"en":"Our first attempt to fix the bug failed, so it\'s back to the drawing board.","ko":"버그를 고치려는 우리의 첫 시도는 실패했으니, 처음부터 다시 시작해야 해요."},{"en":"The marketing campaign didn\'t yield the expected results; we\'re back to the drawing board.","ko":"마케팅 캠페인이 예상했던 결과를 내지 못했어요; 처음부터 다시 시작해야 합니다."},{"en":"After the client rejected the design, the team realized it was back to the drawing board.","ko":"고객이 디자인을 거절한 후, 팀은 처음부터 다시 시작해야 한다는 것을 깨달았습니다."},{"en":"We thought we had a perfect solution, but it seems we\'re back to the drawing board.","ko":"우리가 완벽한 해결책을 찾았다고 생각했지만, 처음부터 다시 시작해야 할 것 같아요."}],"related":[{"slug":"back-to-square-one","title":"Back To Square One","note":"다시 원점으로 돌아가 처음부터 시작한다는 점에서 매우 유사합니다."},{"slug":"start-from-scratch","title":"Start From Scratch","note":"아무것도 없는 상태에서 새로 시작한다는 의미입니다."},{"slug":"go-back-to-basics","title":"Go Back To Basics","note":"복잡한 문제가 생겼을 때, 기본 원칙이나 단순한 방법으로 돌아가 해결하려는 태도를 나타냅니다."},{"slug":"re-evaluate","title":"Re-evaluate","note":"상황이나 계획을 재평가하여 새로운 방향을 모색하는 행위를 의미합니다."}],"date":"2025-08-16T00:00"}');
;// ./blog/child-s-play/content.json
const child_s_play_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"child-s-play","title":"Child\'s Play","koreanPronunciation":"차일즈 플레이","tags":["관용구","자주 쓰는 표현"],"meaning":"매우 쉽고 간단한 일을 나타내는 의미입니다","description":"이 표현은 어린아이도 쉽게 할 수 있을 정도로 어떤 일이 아주 쉽고 복잡하지 않음을 강조할 때 사용됩니다. 비유적으로 어려운 일이 전혀 아님을 나타낼 때 쓰입니다.","examples":[{"en":"For a professional like him, this task is child\'s play.","ko":"그와 같은 전문가에게 이 일은 식은 죽 먹기입니다."},{"en":"Learning to code used to seem difficult, but now it\'s child\'s play.","ko":"코딩을 배우는 것이 예전에는 어려워 보였지만, 이제는 식은 죽 먹기입니다."},{"en":"After years of practice, playing this piece is child\'s play for her.","ko":"수년간의 연습 끝에, 이 곡을 연주하는 것은 그녀에게 식은 죽 먹기입니다."},{"en":"Don\'t worry, fixing this computer issue will be child\'s play.","ko":"걱정 마세요, 이 컴퓨터 문제를 고치는 건 아주 쉬울 거예요."}],"related":[{"slug":"a-piece-of-cake","title":"A Piece Of Cake","type":"synonym"},{"slug":"easy-as-pie","title":"Easy As Pie","type":"synonym"},{"slug":"a-walk-in-the-park","title":"A Walk In The Park","type":"synonym"},{"slug":"no-brainer","title":"No-Brainer","note":"생각할 필요도 없이 쉬운 결정이나 일","type":"synonym"}],"date":"2025-07-25T00:00"}');
;// ./blog/take-responsibility/content.json
const take_responsibility_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"take-responsibility","title":"Take Responsibility","koreanPronunciation":"테이크 리스폰서빌리티","tags":["연어","자주 쓰는 표현"],"meaning":"책임을 지거나 맡는다는 의미입니다.","description":"이 표현은 자신의 행동이나 결정에 대해 책임을 인정하고 감수하는 것을 의미합니다. 직장, 학교, 개인 생활 등 여러 상황에서 많이 쓰이며, 성숙하고 신뢰할 만한 태도를 나타낼 때 자주 사용됩니다.","examples":[{"en":"You need to take responsibility for your mistakes.","ko":"자신의 실수에 대해 책임져야 한다."},{"en":"She took responsibility for organizing the event.","ko":"그녀가 행사를 조직하는 책임을 맡았다."},{"en":"It’s important to take responsibility for your own learning.","ko":"자기 주도 학습에 책임을 지는 것이 중요하다."},{"en":"He refused to take responsibility and blamed others.","ko":"그는 책임을 지지 않고 다른 사람을 탓했다."},{"en":"Taking responsibility shows maturity and leadership.","ko":"책임을 지는 것은 성숙함과 리더십을 보여준다."}],"related":[{"slug":"own-up-to","title":"Own up to","type":"synonym"},{"slug":"be-accountable-for","title":"Be accountable for","type":"synonym"},{"slug":"shoulder-the-responsibility","title":"Shoulder the responsibility","type":"synonym"},{"slug":"be-answerable-for","title":"Be answerable for","type":"synonym"},{"slug":"accept-liability","title":"Accept liability","type":"synonym"}],"date":"2025-06-06T15:00"}');
;// ./blog/come-clean/content.json
const come_clean_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"come-clean","title":"Come Clean","koreanPronunciation":"컴 클린","tags":["구동사"],"meaning":"비밀이나 잘못을 고백하거나 자백하는 의미입니다.","description":"이 표현은 보통 숨기고 있던 비밀이나 잘못을 솔직하게 털어놓고 인정할 때 사용됩니다. 죄책감이나 부담감을 덜기 위해 진실을 밝히는 상황에 주로 쓰입니다. 어떤 사실을 더 이상 숨기지 않고 공개적으로 인정하는 행위를 나타냅니다.","examples":[{"en":"It\'s time you came clean about what really happened.","ko":"이제 네가 실제로 무슨 일이 있었는지 솔직하게 털어놓을 때가 되었어."},{"en":"After years of lying, he finally decided to come clean to his family.","ko":"수년간 거짓말을 한 후, 그는 마침내 가족에게 모든 것을 솔직하게 털어놓기로 결정했다."},{"en":"The suspect was urged to come clean and tell the police everything he knew.","ko":"용의자는 솔직하게 털어놓고 자신이 아는 모든 것을 경찰에게 말하라고 촉구받았다."},{"en":"She felt much better after coming clean about her mistake.","ko":"그녀는 자신의 실수를 솔직하게 고백하고 나서 훨씬 기분이 나아졌다."}],"related":[{"slug":"confess","title":"Confess","type":"synonym","note":"비밀이나 잘못을 자백하다"},{"slug":"admit","title":"Admit","type":"synonym","note":"무언가를 인정하다"},{"slug":"disclose-a-secret","title":"Disclose a Secret","type":"synonym","note":"비밀을 폭로하다"},{"slug":"conceal","title":"Conceal","type":"antonym","note":"진실을 숨기다"}],"date":"2025-10-24T00:01"}');
