const look_after_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"look-after","title":"Look After","koreanPronunciation":"룩 애프터","tags":["구동사"],"meaning":"무언가나 누군가를 돌보고, 보살피며, 책임을 지고 관리한다는 의미입니다.","description":"이 표현은 어린이, 노인, 반려동물, 또는 어떤 물건이나 일 등을 잘 챙기고 책임지는 의미로 사용됩니다. 영국 영어에서 특히 자주 쓰이며, 미국 영어에서도 널리 사용됩니다. 상황에 따라 신체적, 정서적, 또는 실질적인 보살핌을 의미할 수 있습니다.","examples":[{"en":"Can you look after my dog while I’m on vacation?","ko":"내가 휴가 가 있는 동안 내 개 좀 봐줄 수 있어?"},{"en":"She stayed home to look after her sick grandmother.","ko":"그녀는 아픈 할머니를 돌보기 위해 집에 머물렀다."},{"en":"It\'s your job to look after the equipment.","ko":"장비를 관리하는 건 네 일이야."},{"en":"They hired a nanny to look after the children.","ko":"그들은 아이들을 돌볼 보모를 고용했다."},{"en":"You should look after yourself more—you’re always working late.","ko":"자신을 좀 더 챙겨야 해—너 항상 늦게까지 일하잖아."}],"related":[{"slug":"take-care-of","title":"Take care of","type":"synonym"},{"slug":"watch-over","title":"Watch over","type":"synonym"},{"slug":"care-for","title":"Care for","type":"synonym"},{"slug":"tend-to","title":"Tend to","type":"synonym"},{"slug":"be-responsible-for","title":"Be responsible for","type":"synonym"}],"date":"2025-06-25T23:20"}');
;// ./blog/lazy-bones/content.json
const lazy_bones_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"lazy-bones","title":"Lazy Bones","koreanPronunciation":"레이지 본즈","tags":["관용구","자주 쓰는 표현","속어"],"meaning":"게으르거나 나태한 사람을 친근하게, 또는 때로는 꾸짖듯이 부르는 의미입니다.","description":"이 표현은 일하거나 노력하는 것을 피하는 사람을 비공식적으로 지칭할 때 사용됩니다. 주로 어린이에게 장난스럽게 말하거나, 성인에게도 가볍게 농담조로 사용하는 경우가 많습니다. \'게으름뱅이\'와 같은 의미로 쓰이며, 주로 행동이 느리거나 쉬기를 좋아하는 사람에게 쓰입니다.","examples":[{"en":"Come on, lazy bones, it\'s time to get up and start your day!","ko":"이 게으름뱅이야, 이제 일어나서 하루를 시작할 시간이야!"},{"en":"My brother is such a lazy bones; he never helps with the chores around the house.","ko":"우리 오빠는 정말 게으름뱅이야; 집안일을 전혀 돕지 않아."},{"en":"Stop being a lazy bones and help me finish this project!","ko":"게으름 피우지 말고 이 프로젝트 끝내는 것 좀 도와줘!"}],"related":[{"slug":"couch-potato","title":"Couch Potato","type":"synonym","note":"주로 소파에 앉아 TV를 보며 시간을 보내는 게으른 사람을 의미합니다."},{"slug":"slacker","title":"Slacker","type":"synonym","note":"해야 할 일을 회피하거나 게으름을 피우는 사람을 나타냅니다."},{"slug":"hard-worker","title":"Hard Worker","type":"antonym","note":"부지런하고 열심히 일하는 사람을 의미합니다."}],"date":"2026-02-01T00:01"}');
;// ./blog/fail-to-achieve/content.json
const fail_to_achieve_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"fail-to-achieve","title":"Fail To Achieve","koreanPronunciation":"페일 투 어치브","tags":["자주 쓰는 표현"],"meaning":"목표나 목적을 달성하지 못함을 의미입니다.","description":"이 표현은 어떤 목표, 목적, 또는 기대치를 달성하거나 이루지 못했음을 나타냅니다. 주로 노력했음에도 불구하고 원하는 결과를 얻지 못했을 때 사용됩니다. 계획했던 바를 성공적으로 완료하지 못하거나 특정 기준에 미치지 못했을 때 이 표현을 쓸 수 있습니다.","examples":[{"en":"Despite their best efforts, the team failed to achieve their sales target this quarter.","ko":"최선을 다했음에도 불구하고, 팀은 이번 분기 판매 목표를 달성하지 못했습니다."},{"en":"The project failed to achieve the desired results due to budget constraints.","ko":"예산 제약 때문에 그 프로젝트는 원하는 결과를 달성하지 못했습니다."},{"en":"Many startups fail to achieve profitability in their first few years.","ko":"많은 스타트업이 초기 몇 년 동안 수익성을 달성하지 못합니다."},{"en":"She felt disappointed after failing to achieve her personal best in the race.","ko":"그녀는 경주에서 개인 최고 기록을 달성하지 못하자 실망감을 느꼈습니다."}],"related":[{"slug":"miss-the-mark","title":"Miss The Mark","type":"synonym","note":"목표나 기대에 미치지 못함을 의미합니다."},{"slug":"come-up-short","title":"Come Up Short","type":"synonym","note":"필요한 만큼의 결과나 수준에 도달하지 못함을 의미합니다."},{"slug":"achieve-success","title":"Achieve Success","type":"antonym","note":"원하는 목표나 결과를 성공적으로 달성함을 의미합니다."},{"slug":"meet-expectations","title":"Meet Expectations","type":"antonym","note":"기대치나 기준에 부합하거나 그 이상을 달성함을 의미합니다."},{"slug":"reach-a-goal","title":"Reach A Goal","type":"antonym","note":"특정한 목표를 성취하거나 도달함을 의미합니다."}],"date":"2026-03-25T00:00"}');
;// ./blog/take-revenge/content.json
const take_revenge_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"take-revenge","title":"Take Revenge","koreanPronunciation":"테이크 리벤지","tags":["관용구","자주 쓰는 표현"],"meaning":"누군가에게 복수하거나 앙갚음하는 것을 의미합니다","description":"이 표현은 자신에게 해를 가했거나 불공정한 대우를 한 사람에게 보복하는 행위를 묘사합니다. 이는 주로 부정적인 맥락에서 사용되며, 갈등을 해결하기보다는 악화시키는 결과를 초래할 수 있습니다.","examples":[{"en":"After losing the game, he vowed to take revenge in the next match.","ko":"경기에 진 후, 그는 다음 경기에서 복수하겠다고 맹세했다."},{"en":"She decided to take revenge on her ex-boyfriend for betraying her.","ko":"그녀는 자신을 배신한 전 남자친구에게 복수하기로 결심했다."},{"en":"The superhero always tries to take revenge on the villains who harm innocent people.","ko":"그 슈퍼히어로는 항상 무고한 사람들을 해치는 악당들에게 복수하려고 한다."},{"en":"Taking revenge often leads to a cycle of endless conflict.","ko":"복수하는 것은 종종 끝없는 갈등의 순환으로 이어진다."}],"related":[{"slug":"get-even","title":"Get Even","type":"synonym","note":"비슷한 의미로, 특히 동등하게 앙갚음하여 \'본전\'을 찾는 느낌을 강조합니다."},{"slug":"settle-a-score","title":"Settle a Score","type":"synonym","note":"오래된 불화나 원한을 해소하는 의미로, 종종 복수를 통해 이루어집니다."},{"slug":"pay-back","title":"Pay Back","type":"synonym","note":"빚을 갚듯이 상대방에게 보복하는 것을 의미하며, 주로 부정적인 행동에 대한 응징으로 사용됩니다."},{"slug":"avenge","title":"Avenge","type":"synonym","note":"다른 사람이나 자신에게 가해진 불의나 해악에 대해 복수하다는 동사입니다."}],"date":"2025-07-21T00:00"}');
;// ./blog/cut-someone-down-to-size/content.json
const cut_someone_down_to_size_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"cut-someone-down-to-size","title":"Cut Someone Down To Size","koreanPronunciation":"컷 섬원 다운 투 사이즈","tags":["관용구"],"meaning":"누군가의 자만심을 꺾고 그들의 실제 위치나 중요성을 깨닫게 하는 의미입니다.","description":"이 표현은 어떤 사람이 지나치게 자만하거나 오만할 때, 그들에게 현실을 직시하게 하여 겸손하게 만들거나 그들의 위세를 꺾는 상황에서 사용됩니다. 주로 비판이나 혹독한 대우를 통해 상대방의 기를 죽이는 뉘앙스를 가집니다.","examples":[{"en":"His boss finally cut him down to size after he kept boasting about his achievements.","ko":"그의 상사는 그가 계속해서 자신의 성과를 자랑하자 마침내 그의 기를 꺾었다."},{"en":"A little failure might cut her down to size and teach her some humility.","ko":"작은 실패가 그녀의 자만심을 꺾고 겸손함을 가르칠지도 모른다."},{"en":"Don\'t let his arrogance bother you; someone will eventually cut him down to size.","ko":"그의 오만함에 신경 쓰지 마세요. 결국 누군가가 그의 기를 꺾을 거예요."},{"en":"The coach had to cut the star player down to size after he started disrespecting his teammates.","ko":"코치는 스타 선수가 팀원들을 무시하기 시작하자 그의 자만심을 꺾어야 했다."}],"related":[{"slug":"put-someone-in-their-place","title":"Put Someone In Their Place","type":"synonym","note":"상대방의 오만함이나 무례함을 제지하여 마땅한 위치를 깨닫게 하는 직접적인 행동을 강조합니다."},{"slug":"humble-someone","title":"Humble Someone","type":"synonym","note":"누군가를 겸손하게 만들거나 자만심을 꺾는 포괄적인 의미를 가집니다."},{"slug":"build-someone-up","title":"Build Someone Up","type":"antonym","note":"상대방의 자신감이나 자존감을 높여주는 의미로, \'cut someone down to size\'와 반대되는 상황입니다."}],"date":"2026-02-03T00:00"}');
;// ./blog/see-the-glass-half-full/content.json
const see_the_glass_half_full_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"see-the-glass-half-full","title":"See the Glass Half Full","koreanPronunciation":"씨 더 글라스 하프 풀","tags":["관용구","자주 쓰는 표현"],"meaning":"어떤 상황을 긍정적이고 낙관적인 관점에서 바라보는 것을 의미입니다.","description":"이 표현은 사물을 긍정적인 면에서 바라보고, 어려운 상황에서도 희망적이거나 좋은 점을 찾아내려는 낙관적인 태도를 묘사할 때 사용됩니다. 비유적으로, 물이 절반 채워진 컵을 보고 \'절반이나 차 있다\'고 생각하는 긍정적인 시각을 의미하며, 부정적인 면보다는 긍정적인 면에 초점을 맞추는 사람에게 주로 쓰입니다.","examples":[{"en":"Despite the challenges, she always tries to see the glass half full and maintain a positive attitude.","ko":"어려움에도 불구하고, 그녀는 항상 긍정적으로 생각하며 낙관적인 태도를 유지하려고 노력합니다."},{"en":"In tough times, it\'s important to try and see the glass half full to keep your spirits up.","ko":"힘든 시기에는 기운을 북돋기 위해 긍정적으로 생각하려고 노력하는 것이 중요합니다."},{"en":"He\'s an incredible optimist; he truly sees the glass half full no matter what happens.","ko":"그는 대단한 낙천주의자입니다; 무슨 일이 일어나든 정말 긍정적으로 생각합니다."},{"en":"Instead of complaining, let\'s try to see the glass half full and focus on the opportunities.","ko":"불평하는 대신, 긍정적으로 생각하며 기회에 집중해 봅시다."},{"en":"My grandmother always taught me to see the glass half full, even on rainy days.","ko":"우리 할머니는 항상 비 오는 날에도 긍정적으로 생각하라고 가르치셨어요."}],"related":[{"slug":"look-on-the-bright-side","title":"Look on the Bright Side","type":"synonym","note":"어떤 상황의 긍정적인 면을 보려고 노력하다"},{"slug":"silver-lining","title":"Silver Lining","type":"synonym","note":"불행 속의 한 줄기 희망, 긍정적인 면"},{"slug":"be-an-optimist","title":"Be an Optimist","type":"synonym","note":"낙천주의자가 되다"},{"slug":"make-the-best-of-it","title":"Make the Best of It","type":"synonym","note":"주어진 상황에서 최선을 다하다"}],"date":"2025-07-08T04:31"}');
;// ./blog/off-the-hook/content.json
const off_the_hook_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"off-the-hook","title":"Off The Hook","koreanPronunciation":"오프 더 훅","tags":["관용구","속어","자주 쓰는 표현"],"meaning":"(곤경이나 책임에서) 벗어나 자유로운 상태이거나, (음악, 파티 등이) 매우 훌륭하고 신나는 것을 의미합니다.","description":"이 표현은 크게 두 가지 의미로 사용됩니다. 첫 번째는 어떤 곤경이나 책임, 비난 등에서 벗어나 자유로운 상태를 뜻합니다. 주로 누군가가 처벌이나 어려운 상황을 모면했을 때 쓰입니다. 두 번째는 비격식적으로 음악, 파티, 또는 어떤 경험이 \\"매우 훌륭하고\\", \\"신나고\\", \\"끝내준다\\"고 묘사할 때 사용됩니다. 후자의 의미는 주로 젊은 층에서 구어체로 많이 쓰입니다.","examples":[{"en":"I thought I was going to get fired, but the boss let me off the hook.","ko":"나는 해고당할 줄 알았는데, 사장님이 나를 곤경에서 벗어나게 해주셨어."},{"en":"They found the real culprit, so I\'m finally off the hook.","ko":"진범을 찾아서 나는 마침내 책임을 면하게 되었다."},{"en":"That new album is totally off the hook!","ko":"그 새 앨범 정말 끝내준다!"},{"en":"The party last night was off the hook, everyone had a great time.","ko":"어젯밤 파티는 정말 최고였고, 모두 즐거운 시간을 보냈어."},{"en":"This food is off the hook, I need the recipe!","ko":"이 음식 진짜 대박이다, 레시피 좀 알려줘!"}],"related":[{"slug":"let-off-the-hook","title":"Let Off The Hook","type":"synonym","note":"\'Off the hook\'의 상태를 만드는 행위를 나타냅니다."},{"slug":"get-away-with","title":"Get Away With","type":"synonym","note":"나쁜 행동에 대한 처벌을 피하는 의미에서 비슷합니다."},{"slug":"top-notch","title":"Top-Notch","type":"synonym","note":"\'아주 훌륭한\'이라는 의미에서 비슷합니다."},{"slug":"out-of-this-world","title":"Out Of This World","type":"synonym","note":"\'믿을 수 없을 정도로 좋은\'이라는 의미에서 비슷합니다."}],"date":"2026-03-10T00:00"}');
;// ./blog/stroke-of-luck/content.json
const stroke_of_luck_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"stroke-of-luck","title":"Stroke Of Luck","koreanPronunciation":"스트로크 오브 럭","tags":["관용구"],"meaning":"예상치 못하게 찾아온 행운을 의미합니다","description":"이 표현은 갑작스럽거나 우연히 발생한 긍정적인 사건이나 결과를 설명할 때 사용됩니다. 주로 어려운 상황에서 뜻밖의 좋은 일이 생겼을 때 쓰이며, 노력보다는 운에 의한 것임을 강조합니다. 복권 당첨, 우연한 만남, 문제 해결 등 다양한 맥락에서 사용될 수 있습니다.","examples":[{"en":"Finding that lost wallet was a real stroke of luck.","ko":"잃어버린 지갑을 찾은 건 정말 행운이었어."},{"en":"It was a stroke of luck that we arrived just before the store closed.","ko":"가게 문 닫기 직전에 도착한 것은 정말 운이 좋았어."},{"en":"Getting that scholarship was a huge stroke of luck for me.","ko":"그 장학금을 받은 것은 나에게 엄청난 행운이었어."},{"en":"By a stroke of luck, the doctor had a last-minute cancellation.","ko":"운 좋게도 의사가 마지막 순간에 예약을 취소한 환자가 있었다."},{"en":"The sudden rain was a stroke of luck for the farmers.","ko":"갑작스러운 비는 농부들에게 행운이었다."}],"related":[{"slug":"lucky-break","title":"Lucky Break","type":"synonym","note":"뜻밖의 행운이나 기회를 나타냅니다."},{"slug":"windfall","title":"Windfall","type":"synonym","note":"뜻밖의 큰 이득이나 소득을 의미합니다."},{"slug":"godsend","title":"Godsend","type":"synonym","note":"매우 유용하거나 꼭 필요할 때 나타난 것을 의미합니다."},{"slug":"fluke","title":"Fluke","type":"synonym","note":"우연히 성공하거나 일어난 예상 밖의 일을 지칭하며, 주로 우연성을 강조합니다."}],"date":"2025-07-22T00:00"}');
;// ./blog/diligent-person/content.json
const diligent_person_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"diligent-person","title":"Diligent Person","koreanPronunciation":"딜리전트 퍼슨","tags":["자주 쓰는 표현","연어"],"meaning":"성실하고 부지런하게 맡은 일을 수행하는 사람을 의미합니다","description":"이 표현은 일반적으로 맡은 바 책임을 다하고 꾸준히 노력하며, 근면하고 성실한 태도로 업무나 학업 등에 임하는 사람을 묘사할 때 사용됩니다. 어떤 일을 꾸준히 노력하여 완수하는 긍정적인 특성을 강조하는 표현입니다.","examples":[{"en":"She is a diligent person who always finishes her tasks ahead of schedule.","ko":"그녀는 항상 예정보다 일찍 업무를 마치는 부지런한 사람입니다."},{"en":"Our team needs more diligent people to handle the increasing workload.","ko":"우리 팀은 늘어나는 업무량을 감당할 더 많은 성실한 사람이 필요합니다."},{"en":"Being a diligent person is crucial for success in any field.","ko":"성실한 사람이 되는 것은 어떤 분야에서든 성공하는 데 중요합니다."},{"en":"He was recognized as a diligent person for his consistent efforts and attention to detail.","ko":"그는 꾸준한 노력과 세심함으로 성실한 사람으로 인정받았습니다."}],"related":[{"slug":"hard-worker","title":"Hard Worker","type":"synonym","note":"직설적으로 \'열심히 일하는 사람\'을 의미합니다."},{"slug":"industrious-person","title":"Industrious Person","type":"synonym","note":"‘부지런한’ 또는 ‘근면한’의 의미를 강조합니다."},{"slug":"conscientious-individual","title":"Conscientious Individual","type":"synonym","note":"양심적이고 성실하며, 맡은 바를 꼼꼼히 하는 사람을 지칭합니다."},{"slug":"lazy-person","title":"Lazy Person","type":"antonym","note":"일에 대한 의욕이 없고 게으른 사람을 의미합니다."},{"slug":"slacker","title":"Slacker","type":"antonym","note":"책임을 회피하고 일을 게을리하는 사람을 경멸적으로 지칭할 때 사용됩니다."}],"date":"2026-02-01T00:02"}');
;// ./blog/get-nowhere/content.json
const get_nowhere_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"get-nowhere","title":"Get Nowhere","koreanPronunciation":"겟 노웨어","tags":["관용구","자주 쓰는 표현"],"meaning":"어떤 일을 시도해도 진전을 보지 못하거나 아무것도 성취하지 못하는 의미입니다.","description":"이 표현은 노력이나 시도에도 불구하고 어떠한 긍정적인 결과나 진전도 얻지 못하는 상황을 묘사할 때 사용됩니다. 주로 시간이나 노력을 낭비하는 상황을 나타내며, 답보 상태에 있음을 강조합니다. 해결책을 찾지 못하거나 목표 달성에 실패했을 때 쓰이기도 합니다.","examples":[{"en":"We\'ve been discussing this for an hour, but we\'re getting nowhere.","ko":"한 시간 동안 이 문제에 대해 논의했지만, 아무런 진전도 없습니다."},{"en":"I tried to fix the computer myself, but I just got nowhere.","ko":"컴퓨터를 직접 고치려 했지만, 아무 소용이 없었습니다."},{"en":"If you keep arguing without listening, we\'ll get nowhere.","ko":"상대방의 말을 듣지 않고 계속 논쟁하면, 아무것도 해결되지 않을 겁니다."},{"en":"Despite all their efforts, the team felt like they were getting nowhere with the project.","ko":"모든 노력에도 불구하고, 팀은 프로젝트에서 아무런 진전도 없는 것 같다고 느꼈습니다."}],"related":[{"slug":"go-in-circles","title":"Go In Circles","type":"synonym","note":"반복적인 행동이나 논의로 인해 진전이 없는 상태를 나타냅니다."},{"slug":"spin-one-s-wheels","title":"Spin One\'s Wheels","type":"synonym","note":"노력은 하지만 실질적인 진전을 이루지 못하는 상황을 의미합니다."},{"slug":"make-no-headway","title":"Make No Headway","type":"synonym","note":"어떤 방향으로도 나아가지 못하고 제자리걸음만 하는 것을 뜻합니다."},{"slug":"make-progress","title":"Make Progress","type":"antonym","note":"어떤 목표를 향해 나아가거나 개선이 이루어지는 것을 의미합니다."},{"slug":"move-forward","title":"Move Forward","type":"antonym","note":"현재 상태에서 다음 단계로 나아가거나 발전하는 것을 뜻합니다."}],"date":"2025-12-11T00:00"}');
;// ./blog/right-the-ship/content.json
const right_the_ship_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"right-the-ship","title":"Right The Ship","koreanPronunciation":"라이트 더 쉽","tags":["관용구","자주 쓰는 표현"],"meaning":"안 좋은 상황을 개선하거나 일을 제자리로 돌려놓는다는 의미입니다.","description":"이 표현은 배가 폭풍우나 문제로 인해 기울거나 불안정해졌을 때, 이를 바로잡아 다시 안정적인 상태로 만든다는 물리적인 행위에서 유래했습니다. 비유적으로는 비즈니스, 개인적인 삶, 관계 등 어떤 분야에서든 심각한 문제나 어려움에 처했을 때, 상황을 통제하고 문제를 해결하여 정상적인 상태로 되돌리는 노력을 의미합니다. 주로 리더나 주도적인 역할을 하는 사람이 혼란스러운 상황을 바로잡을 때 사용됩니다.","examples":[{"en":"The company\'s sales were declining rapidly, but the new CEO managed to right the ship within a year.","ko":"회사의 매출이 급격히 감소하고 있었지만, 새로운 CEO는 1년 안에 상황을 바로잡을 수 있었습니다."},{"en":"After a series of poor performances, the coach vowed to right the ship and lead the team to victory.","ko":"연속적인 부진한 경기 후, 코치는 전세를 역전시키고 팀을 승리로 이끌겠다고 맹세했습니다."},{"en":"Our relationship was going through a rough patch, but we worked hard to communicate better and right the ship.","ko":"우리 관계는 힘든 시기를 겪고 있었지만, 우리는 더 잘 소통하고 상황을 바로잡기 위해 노력했습니다."},{"en":"It\'s time for us to take serious action and right the ship before the project completely fails.","ko":"프로젝트가 완전히 실패하기 전에 우리가 심각한 조치를 취하고 상황을 바로잡아야 할 때입니다."}],"related":[{"slug":"turn-things-around","title":"Turn Things Around","type":"synonym","note":"나쁜 상황을 좋은 상황으로 완전히 바꾸다."},{"slug":"get-back-on-track","title":"Get Back On Track","type":"synonym","note":"정상적인 진행 과정이나 경로로 돌아오다."},{"slug":"straighten-out","title":"Straighten Out","type":"synonym","note":"혼란스러운 상황이나 문제를 해결하다."},{"slug":"go-downhill","title":"Go Downhill","type":"antonym","note":"상황이 점점 나빠지다."}],"date":"2026-01-27T00:00"}');
;// ./blog/it-is-what-it-is/content.json
const it_is_what_it_is_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"it-is-what-it-is","title":"It Is What It Is","koreanPronunciation":"잇 이즈 왓 잇 이즈","tags":["문장","자주 쓰는 표현"],"meaning":"어쩔 수 없다, 그냥 그런 거야라는 의미입니다","description":"이 표현은 어떤 상황이 마음에 들지 않더라도 바꿀 수 없음을 인정하고 받아들이자는 의미로 사용됩니다. 아쉬움, 체념, 또는 현실 인정을 담고 있으며, 특히 예상치 못한 문제나 결과 앞에서 자주 사용됩니다. 담담하고 현실적인 뉘앙스를 가지고 있습니다.","examples":[{"en":"We missed the deadline. It is what it is.","ko":"마감일을 놓쳤어. 어쩔 수 없지 뭐."},{"en":"I don’t like the decision, but it is what it is.","ko":"그 결정이 마음에 들진 않지만, 그냥 그런 거지."},{"en":"The weather ruined our plans. Oh well — it is what it is.","ko":"날씨 때문에 계획이 망했어. 뭐, 그냥 그런 거지."},{"en":"Sometimes life isn’t fair. It is what it is.","ko":"가끔 인생은 불공평해. 그냥 그런 거야."},{"en":"They didn’t choose me for the role. It is what it is.","ko":"그들은 나를 그 역할로 뽑지 않았어. 어쩔 수 없지."}],"related":[{"slug":"that\'s-just-how-it-goes","title":"That\'s just how it goes","type":"synonym"},{"slug":"that\'s-life","title":"That\'s life","type":"synonym"},{"slug":"you-can\'t-win-them-all","title":"You can\'t win them all","type":"synonym"},{"slug":"so-be-it","title":"So be it","type":"synonym"},{"slug":"nothing-we-can-do-about-it","title":"Nothing we can do about it","type":"synonym"}],"date":"2025-06-13T13:15"}');
;// ./blog/pick-apart/content.json
const pick_apart_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"pick-apart","title":"Pick Apart","koreanPronunciation":"픽 어파트","tags":["구동사","자주 쓰는 표현"],"meaning":"어떤 것을 매우 면밀하게 조사하거나 분석하여 결점이나 문제점을 찾아내는 의미입니다.","description":"이 표현은 주로 어떤 아이디어, 주장, 글, 또는 작업을 세밀하게 검토하고 비판하며 약점을 찾아내는 상황에서 사용됩니다. 긍정적인 맥락보다는 부정적인 분석이나 비평에 더 가깝게 쓰이며, 무언가를 조목조목 따지거나 파고든다는 뉘앙스를 가집니다.","examples":[{"en":"The critics will inevitably pick apart every aspect of the new movie.","ko":"비평가들은 새 영화의 모든 측면을 필연적으로 샅샅이 분석할 것입니다."},{"en":"She tends to pick apart every suggestion I make, looking for flaws.","ko":"그녀는 내가 하는 모든 제안을 꼬치꼬치 따지며 결점을 찾으려는 경향이 있습니다."},{"en":"It\'s easy to pick apart someone else\'s work, but harder to create your own.","ko":"남의 작업을 낱낱이 파헤치는 것은 쉽지만, 자신만의 것을 창조하는 것은 더 어렵습니다."},{"en":"The lawyer tried to pick apart the witness\'s testimony during cross-examination.","ko":"변호사는 반대 심문 중에 증인의 증언을 낱낱이 파헤치려 했습니다."}],"related":[{"slug":"scrutinize","title":"Scrutinize","type":"synonym","note":"꼼꼼히 조사하다, 면밀히 살피다"},{"slug":"dissect","title":"Dissect","type":"synonym","note":"해부하다, 상세히 분석하다"},{"slug":"critique","title":"Critique","type":"synonym","note":"비평하다, 분석적으로 평가하다"},{"slug":"gloss-over","title":"Gloss Over","type":"antonym","note":"대충 넘어가다, 얼버무리다 (면밀히 조사하지 않고 대강 넘기는 것)"}],"date":"2025-11-19T00:00"}');
;// ./blog/in-short/content.json
const in_short_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"in-short","title":"In Short","koreanPronunciation":"인 쇼트","tags":["자주 쓰는 표현"],"meaning":"요약하자면, 간단히 말하면, 한마디로 말하면 등의 의미입니다","description":"이 표현은 길거나 복잡한 내용을 간략하게 정리하여 핵심만 전달하고 싶을 때 사용됩니다. 주로 대화나 글의 요약 부분에서 핵심적인 결론을 제시하거나, 논의를 마무리할 때 활용됩니다. 불필요한 설명을 생략하고 본질적인 메시지에 집중할 수 있도록 돕습니다.","examples":[{"en":"In short, we need to cut costs and increase revenue.","ko":"간단히 말해서, 우리는 비용을 절감하고 수익을 늘려야 합니다."},{"en":"He explained the whole process, but in short, it\'s quite simple.","ko":"그는 전체 과정을 설명했지만, 요컨대 그것은 꽤 간단합니다."},{"en":"In short, the project was a complete failure.","ko":"한마디로 말해서, 그 프로젝트는 완전히 실패했습니다."},{"en":"Our strategy, in short, is to focus on customer satisfaction.","ko":"요약하자면, 우리의 전략은 고객 만족에 초점을 맞추는 것입니다."}],"related":[{"slug":"to-sum-up","title":"To Sum Up","type":"synonym","note":"논의나 설명을 요약할 때 사용"},{"slug":"in-a-nutshell","title":"In a Nutshell","type":"synonym","note":"아주 간략하게, 핵심만 말할 때 사용"},{"slug":"briefly","title":"Briefly","type":"synonym","note":"간단히, 짧게 말할 때 사용"}],"date":"2026-03-18T00:00"}');
;// ./blog/begin-anew/content.json
const begin_anew_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"begin-anew","title":"Begin Anew","koreanPronunciation":"비긴 어뉴","tags":["자주 쓰는 표현","관용구"],"meaning":"새롭게 시작하거나 다시 시작한다는 의미입니다","description":"이 표현은 이전의 방식이나 상황을 완전히 버리고 새로운 시작을 하거나, 더 나은 방향으로 나아가기 위해 처음부터 다시 시작할 때 사용됩니다. 종종 실패나 어려움 이후에 긍정적인 변화를 도모할 때 쓰입니다.","examples":[{"en":"After losing everything, she decided to begin anew in a different city.","ko":"모든 것을 잃은 후, 그녀는 다른 도시에서 새롭게 시작하기로 결심했습니다."},{"en":"The company chose to begin anew with a completely redesigned product.","ko":"그 회사는 완전히 새로 디자인된 제품으로 다시 시작하기로 결정했습니다."},{"en":"It\'s never too late to begin anew and pursue your dreams.","ko":"새롭게 시작하고 꿈을 좇는 데는 결코 늦지 않습니다."},{"en":"Let\'s forget past mistakes and begin anew with a fresh perspective.","ko":"과거의 실수는 잊고 신선한 관점으로 새롭게 시작합시다."}],"related":[{"slug":"start-over","title":"Start Over","type":"synonym"},{"slug":"turn-a-new-leaf","title":"Turn a New Leaf","type":"synonym","note":"주로 행동이나 태도를 개선하며 새 출발할 때 사용됩니다."},{"slug":"make-a-fresh-start","title":"Make a Fresh Start","type":"synonym"},{"slug":"wipe-the-slate-clean","title":"Wipe the Slate Clean","type":"synonym","note":"과거의 잘못이나 기록을 모두 지우고 새롭게 시작한다는 의미가 강합니다."}],"date":"2025-09-13T00:00"}');
;// ./blog/bite-the-hand-that-feeds-you/content.json
const bite_the_hand_that_feeds_you_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"bite-the-hand-that-feeds-you","title":"Bite The Hand That Feeds You","koreanPronunciation":"바이트 더 핸드 댓 피즈 유","tags":["관용구"],"meaning":"자신에게 도움을 주거나 이익을 제공하는 사람에게 해를 끼치거나 배신한다는 의미입니다","description":"이 표현은 자신에게 경제적, 정신적, 또는 다른 형태의 도움을 주는 사람이나 기관을 해치거나 배신하는 행위를 비유적으로 나타냅니다. 은혜를 잊고 오히려 해를 끼치는 상황을 설명할 때 사용됩니다. 고마움을 모르는 행동이나 배신 행위를 비판적으로 묘사할 때 쓰입니다.","examples":[{"en":"He shouldn\'t bite the hand that feeds him by complaining about his job to the boss who just promoted him.","ko":"그는 자신을 승진시켜준 상사에게 일에 대해 불평하며 은혜를 원수로 갚아서는 안 됩니다."},{"en":"After her parents paid for her education, she started criticizing them publicly, which was truly biting the hand that fed her.","ko":"부모님이 학비를 내주셨는데도 그녀는 부모님을 공개적으로 비난하기 시작했는데, 이는 정말 은혜를 원수로 갚는 행동이었습니다."},{"en":"If you keep biting the hand that feeds you, you will eventually lose all your support.","ko":"계속해서 은혜를 원수로 갚으면 결국 모든 지지자를 잃게 될 것입니다."},{"en":"The politician was accused of biting the hand that feeds him when he turned against his biggest donors.","ko":"그 정치인은 가장 큰 후원자들에게 등을 돌리자 은혜를 원수로 갚았다는 비난을 받았습니다."}],"related":[{"slug":"stab-in-the-back","title":"Stab In The Back","type":"synonym","note":"뒤에서 배신하다는 의미로, 은혜를 원수로 갚는 것과 유사합니다."},{"slug":"look-a-gift-horse-in-the-mouth","title":"Look A Gift Horse In The Mouth","type":"synonym","note":"선물 받은 것을 트집 잡는다는 의미로, 감사함을 모르는 행동과 관련이 있습니다."},{"slug":"show-gratitude","title":"Show Gratitude","type":"antonym","note":"감사함을 표현하다는 의미로, 은혜를 갚는 것과 대조됩니다."}],"date":"2025-08-25T00:00"}');
;// ./blog/play-devils-advocate/content.json
const play_devils_advocate_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"play-devils-advocate","title":"Play Devil\'s Advocate","koreanPronunciation":"플레이 데블스 애드버킷","tags":["관용구","자주 쓰는 표현"],"meaning":"일부러 반대 입장을 취하거나 논쟁을 위해 다른 주장을 펼치는 것의 의미입니다.","description":"이 표현은 특정 의견이나 제안에 대해 의도적으로 반대 입장을 취하거나, 단지 논쟁을 촉발시키기 위해 일부러 반대 주장을 펼치는 행위를 묘사합니다. 이는 주로 토론이나 회의에서 모든 가능성을 탐색하고 아이디어를 철저히 검토하기 위해 사용됩니다. 실제로 그 반대 의견에 동의하지 않더라도, 다른 관점을 제시하여 논의를 심화시키고 잠재적인 문제점을 발견하는 데 도움이 됩니다.","examples":[{"en":"I don\'t actually disagree with you, I\'m just playing devil\'s advocate to make sure we\'ve considered all angles.","ko":"저는 실제로 당신의 의견에 반대하는 것은 아니고, 우리가 모든 각도를 고려했는지 확인하기 위해 일부러 반대 의견을 내는 겁니다."},{"en":"Someone needs to play devil\'s advocate in the meeting to challenge the proposal.","ko":"회의에서 누군가는 그 제안에 이의를 제기하기 위해 악마의 변호인 역할을 해야 합니다."},{"en":"She always plays devil\'s advocate, which can be annoying but often leads to better solutions.","ko":"그녀는 항상 반대 의견을 제시하는데, 때로는 짜증나지만 종종 더 나은 해결책으로 이어집니다."},{"en":"Let me play devil\'s advocate for a moment. What if our budget gets cut?","ko":"제가 잠시 반대 의견을 내볼게요. 만약 우리 예산이 삭감된다면 어떻게 될까요?"}],"related":[{"slug":"raise-an-objection","title":"Raise an Objection","type":"synonym","note":"공식적으로 이의를 제기하다"},{"slug":"critique-a-plan","title":"Critique a Plan","type":"synonym","note":"계획을 비판적으로 검토하다"},{"slug":"challenge-an-idea","title":"Challenge an Idea","type":"synonym","note":"아이디어에 도전하다, 이의를 제기하다"},{"slug":"agree-wholeheartedly","title":"Agree Wholeheartedly","type":"antonym","note":"전적으로 동의하다"},{"slug":"go-along-with","title":"Go Along With","type":"antonym","note":"동의하며 따르다, 동조하다"}],"date":"2025-11-17T00:00"}');
;// ./blog/different-strokes-for-different-folks/content.json
const different_strokes_for_different_folks_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"different-strokes-for-different-folks","title":"Different Strokes For Different Folks","koreanPronunciation":"디프런트 스트록스 포 디프런트 폭스","tags":["관용구","자주 쓰는 표현"],"meaning":"사람마다 취향, 선호, 또는 방식이 다르다는 의미입니다","description":"이 표현은 각 개인이 고유한 선호도, 의견, 행동 방식을 가지고 있음을 인정하는 데 사용됩니다. 어떤 한 가지 접근 방식이나 해결책이 모든 사람에게 적합할 수 없다는 것을 강조하며, 타인의 다름을 이해하고 존중해야 한다는 메시지를 담고 있습니다. 예를 들어, 특정 활동이나 취미가 어떤 사람에게는 즐겁지만 다른 사람에게는 그렇지 않을 수 있다는 상황을 설명할 때 유용하게 쓰입니다.","examples":[{"en":"I love hiking, but my brother prefers reading. Different strokes for different folks, I guess.","ko":"저는 등산을 좋아하지만, 제 동생은 독서를 선호해요. 사람마다 다른가 봐요."},{"en":"Some people learn best by doing, while others prefer to read. Different strokes for different folks.","ko":"어떤 사람들은 직접 해보면서 가장 잘 배우는 반면, 다른 사람들은 읽는 것을 선호합니다. 사람마다 방식이 다르죠."},{"en":"He can\'t stand spicy food, but I love it. Well, different strokes for different folks!","ko":"그는 매운 음식을 정말 싫어하지만, 저는 정말 좋아해요. 뭐, 사람마다 취향이 다르니까요!"},{"en":"Our team members have very different working styles, but that\'s okay. Different strokes for different folks.","ko":"우리 팀원들은 작업 방식이 매우 다르지만 괜찮습니다. 사람마다 다 각자의 방식이 있으니까요."}],"related":[{"slug":"to-each-their-own","title":"To Each Their Own","type":"synonym","note":"각자의 취향이나 선호를 존중한다는 의미로, \'Different strokes for different folks\'와 매우 유사하게 사용됩니다."},{"slug":"variety-is-the-spice-of-life","title":"Variety Is The Spice Of Life","type":"synonym","note":"다양성이 삶을 더욱 풍요롭게 만든다는 의미로, 사람마다 다름을 긍정적으로 받아들이는 맥락에서 유사합니다."},{"slug":"one-size-fits-all","title":"One Size Fits All","type":"antonym","note":"모든 사람에게 적용되는 하나의 해결책이나 접근 방식을 의미하므로, \'사람마다 다르다\'는 의미와 대조됩니다."}],"date":"2026-04-03T00:01"}');
;// ./blog/don-t-judge-a-book-by-its-cover/content.json
const don_t_judge_a_book_by_its_cover_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"don-t-judge-a-book-by-its-cover","title":"Don\'t Judge a Book by Its Cover","koreanPronunciation":"돈트 저지 어 북 바이 잇츠 커버","tags":["관용구","자주 쓰는 표현"],"meaning":"외모나 겉모습만으로 어떤 사람이나 사물을 판단하지 말라는 의미입니다.","description":"이 표현은 어떤 사람이나 사물의 진정한 가치나 특성을 외적인 모습만 보고 섣불리 판단해서는 안 된다는 교훈을 전달합니다. 책의 내용이 겉표지만으로는 알 수 없듯이, 사람이나 상황도 겉으로 보이는 것 이상을 가지고 있을 수 있음을 강조할 때 사용됩니다.","examples":[{"en":"She may seem shy, but don\'t judge a book by its cover; she\'s actually very outgoing once you get to know her.","ko":"그녀는 수줍어 보일지 모르지만, 겉만 보고 판단하지 마세요. 알고 보면 그녀는 매우 외향적입니다."},{"en":"The restaurant looks old from the outside, but don\'t judge a book by its cover. Their food is amazing!","ko":"그 식당은 겉으로 보기에는 낡아 보이지만, 겉모습만으로 판단하지 마세요. 음식은 정말 맛있습니다!"},{"en":"My grandmother always taught me, \\"Don\'t judge a book by its cover.\\"","ko":"우리 할머니는 항상 \\"겉모습만 보고 판단하지 마라\\"고 가르치셨습니다."},{"en":"He seemed a bit intimidating at first, but I quickly learned not to judge a book by its cover.","ko":"그는 처음에는 좀 위협적으로 보였지만, 곧 겉모습만으로 판단하지 않는 법을 배웠습니다."}],"related":[{"slug":"appearances-can-be-deceiving","title":"Appearances Can Be Deceiving","type":"synonym","note":"겉모습이 사람을 속일 수 있다는 의미로, \'don\'t judge a book by its cover\'와 유사한 교훈을 줍니다."},{"slug":"there-is-more-than-meets-the-eye","title":"There Is More Than Meets The Eye","type":"synonym","note":"겉으로 보이는 것 이상의 무언가가 있다는 의미로, 사물의 깊이나 복잡성을 나타낼 때 사용됩니다."},{"slug":"never-judge-a-man-until-you-have-walked-a-mile-in-his-moccasins","title":"Never Judge a Man Until You Have Walked a Mile in His Moccasins","type":"synonym","note":"다른 사람의 입장이 되어보기 전에는 그를 판단하지 말라는 의미로, 공감의 중요성을 강조합니다."}],"date":"2025-07-07T03:15"}');
;// ./blog/in-trouble/content.json
const in_trouble_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"in-trouble","title":"In Trouble","koreanPronunciation":"인 트러블","tags":["자주 쓰는 표현","관용구"],"meaning":"곤경에 처하거나 문제가 발생한 상태를 의미합니다","description":"이 표현은 어떤 어려움이나 문제 상황에 직면했을 때 사용됩니다. 주로 부정적인 상황에서 쓰이며, 법적 문제, 재정적 어려움, 대인 관계의 갈등 등 다양한 종류의 곤란한 상태를 나타낼 수 있습니다. 이 표현은 보통 동사 \'be\'와 함께 \'be in trouble\' 형태로 사용됩니다.","examples":[{"en":"He\'s in big trouble if he doesn\'t finish the report by tomorrow.","ko":"내일까지 보고서를 끝내지 못하면 그는 큰 곤경에 처할 것이다."},{"en":"After she broke the vase, she knew she was in trouble with her parents.","ko":"그녀는 꽃병을 깬 후 부모님께 혼날 것을 알았다."},{"en":"The company is in trouble because of declining sales.","ko":"판매 부진으로 회사는 어려움에 처해 있다."},{"en":"I think I\'m in trouble; I lost my wallet.","ko":"지갑을 잃어버려서 곤란한 상황인 것 같아요."}],"related":[{"slug":"in-hot-water","title":"In Hot Water","type":"synonym","note":"비난이나 처벌을 받을 위험에 처한 상황을 비유적으로 표현합니다."},{"slug":"in-a-fix","title":"In a Fix","type":"synonym","note":"곤란한 상황이나 문제에 직면했음을 나타냅니다."},{"slug":"in-a-predicament","title":"In a Predicament","type":"synonym","note":"어렵거나 난처한 상황에 처했음을 의미합니다."},{"slug":"out-of-the-woods","title":"Out of the Woods","type":"antonym","note":"위험하거나 어려운 상황에서 벗어났음을 의미합니다."},{"slug":"safe-and-sound","title":"Safe and Sound","type":"antonym","note":"안전하고 무사한 상태를 나타냅니다."}],"date":"2026-03-29T00:01"}');
