const pull_an_all_nighter_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"pull-an-all-nighter","title":"Pull An All-Nighter","koreanPronunciation":"풀 언 올 나이터","tags":["자주 쓰는 표현","관용구"],"meaning":"밤을 새워 일하거나 공부하는 것을 의미합니다.","description":"이 표현은 시험, 과제, 업무 마감 등 특정 목표를 달성하기 위해 밤새도록 잠을 자지 않고 일하거나 공부하는 행위를 나타낼 때 사용됩니다. 주로 피곤하거나 힘들지만 목표를 위해 기꺼이 밤샘을 감수하는 상황에서 쓰입니다.","examples":[{"en":"I had to pull an all-nighter to finish my presentation on time.","ko":"프레젠테이션을 제시간에 끝내기 위해 밤샘을 해야만 했다."},{"en":"She pulled an all-nighter studying for her final exam and now she\'s exhausted.","ko":"그녀는 기말고사를 위해 밤샘 공부를 했고, 지금은 지쳐있다."},{"en":"Let\'s try not to pull an all-nighter if we can help it.","ko":"가능하다면 밤샘은 하지 않도록 노력하자."},{"en":"The developers pulled an all-nighter to fix the bug before the launch.","ko":"개발자들은 출시 전에 버그를 고치기 위해 밤샘 작업을 했다."}],"related":[{"slug":"burn-the-midnight-oil","title":"Burn The Midnight Oil","type":"synonym","note":"밤늦게까지 열심히 일하거나 공부하는 것을 의미하는 유사한 표현입니다."},{"slug":"stay-up-all-night","title":"Stay Up All Night","type":"synonym","note":"이 표현은 밤새도록 잠들지 않고 깨어있는 상태를 직접적으로 나타냅니다."},{"slug":"cram-for-an-exam","title":"Cram For An Exam","type":"synonym","note":"시험을 앞두고 단기간에 집중적으로 벼락치기 공부를 하는 것을 의미하며, 종종 \'밤샘\'을 동반합니다."},{"slug":"work-around-the-clock","title":"Work Around The Clock","type":"synonym","note":"24시간 내내 쉬지 않고 일하는 것을 의미하며, \'밤샘\'보다 더 광범위한 연속적인 작업을 나타냅니다."}],"date":"2025-07-12T19:13"}');
