const measure_up_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"measure-up","title":"Measure Up","koreanPronunciation":"메저 업","tags":["구동사","자주 쓰는 표현"],"meaning":"어떤 기준이나 기대에 부합하거나 그에 미치다, 혹은 충분히 유능하거나 성공적이라는 의미입니다","description":"이 표현은 주로 개인의 능력, 성과, 또는 제품의 품질 등이 특정 기준, 기대치, 또는 다른 사람과의 비교를 통해 충분한지 여부를 나타낼 때 사용됩니다. 긍정적인 맥락에서는 \'충분히 잘하다\', \'합격점을 받다\'의 의미로, 부정적인 맥락에서는 \'기대에 못 미치다\', \'부족하다\'의 의미로 쓰일 수 있습니다. 종종 어떤 시험이나 경쟁에서 요구되는 자격을 충족시키는 것을 의미하기도 합니다.","examples":[{"en":"He worked hard to measure up to his parents\' high expectations.","ko":"그는 부모님의 높은 기대에 부응하기 위해 열심히 노력했다."},{"en":"Does the new software really measure up to industry standards?","ko":"새 소프트웨어가 정말 업계 표준에 부합할까요?"},{"en":"She felt she could never measure up to her older sister\'s academic achievements.","ko":"그녀는 언니의 학업 성취에 결코 미치지 못할 것이라고 생각했다."},{"en":"After years of training, he finally measured up for the Olympic team.","ko":"수년간의 훈련 끝에 그는 드디어 올림픽 팀에 나설 자격을 갖추었다."},{"en":"I hope my performance will measure up to what the boss expects.","ko":"내 실적이 사장님이 기대하는 바에 부합하기를 바란다."}],"related":[{"slug":"meet-the-standard","title":"Meet The Standard","type":"synonym"},{"slug":"be-up-to-par","title":"Be Up To Par","type":"synonym"},{"slug":"qualify","title":"Qualify","type":"synonym"},{"slug":"fall-short","title":"Fall Short","type":"antonym","note":"주어진 기준이나 기대에 미치지 못할 때 사용합니다."},{"slug":"not-make-the-cut","title":"Not Make The Cut","type":"antonym","note":"어떤 선택이나 경쟁에서 탈락하거나 기준에 미달할 때 사용합니다."}],"date":"2025-12-26T00:00"}');
