const appearances_can_be_deceiving_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"appearances-can-be-deceiving","title":"Appearances Can Be Deceiving","koreanPronunciation":"어피어런시스 캔 비 디시빙","tags":["관용구","자주 쓰는 표현"],"meaning":"겉모습이 실제와 다를 수 있다는 의미입니다","description":"이 표현은 사람이나 사물의 외관이 실제 본질이나 내부 상태와는 다를 수 있다는 경고나 깨달음을 나타낼 때 사용됩니다. 겉으로 보이는 것이 항상 진실을 반영하는 것은 아니므로, 섣부른 판단을 경계하고 신중하게 살펴봐야 함을 강조합니다. 종종 눈에 보이는 것에만 의존하지 말고, 더 깊이 있는 본질을 파악하려는 태도가 필요함을 일깨워 줍니다.","examples":[{"en":"Don\'t judge a book by its cover; appearances can be deceiving.","ko":"겉모습만 보고 판단하지 마세요; 겉모습은 속일 수 있습니다."},{"en":"The old house looked abandoned, but appearances can be deceiving; it was beautifully renovated inside.","ko":"그 낡은 집은 버려진 것처럼 보였지만, 겉모습은 속일 수 있습니다; 안은 아름답게 리모델링되어 있었습니다."},{"en":"He seemed shy at first, but appearances can be deceiving. He\'s actually quite outgoing once you get to know him.","ko":"그는 처음에는 수줍어 보였지만, 겉모습은 속일 수 있습니다. 알고 보면 그는 꽤 외향적입니다."},{"en":"The product looks cheap, but don\'t be fooled, appearances can be deceiving; it\'s very durable.","ko":"그 제품은 싸구려처럼 보이지만, 속지 마세요. 겉모습은 속일 수 있습니다. 그것은 매우 튼튼합니다."}],"related":[{"slug":"don-t-judge-a-book-by-its-cover","title":"Don\'t Judge a Book by Its Cover","type":"synonym"},{"slug":"all-that-glitters-is-not-gold","title":"All That Glitters Is Not Gold","type":"synonym","note":"겉으로 화려해 보이는 것이 실제로는 가치 없을 수 있음을 의미합니다."},{"slug":"looks-can-be-deceiving","title":"Looks Can Be Deceiving","type":"synonym","note":"\'Appearances Can Be Deceiving\'와 거의 동일한 의미의 줄임말입니다."},{"slug":"still-waters-run-deep","title":"Still Waters Run Deep","type":"synonym","note":"조용하고 겉으로 드러나지 않는 사람이 사실은 깊은 생각이나 감정을 가질 수 있음을 의미합니다."}],"date":"2025-07-07T03:15"}');
;// ./blog/to-each-their-own/content.json
const to_each_their_own_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"to-each-their-own","title":"To Each Their Own","koreanPronunciation":"투 이치 데어 오운","tags":["자주 쓰는 표현","관용구"],"meaning":"각자 다른 취향이나 의견을 가질 수 있음을 인정하고 존중한다는 의미입니다","description":"이 표현은 사람들마다 선호, 의견, 방식 등이 다를 수 있음을 인정하고, 각자의 선택을 존중해야 한다는 의미를 담고 있습니다. 특정 상황에서 누군가의 취향이나 결정이 자신과 다르더라도, 그것이 틀린 것이 아니라 단지 다를 뿐임을 받아들일 때 사용됩니다. 타인의 개성과 다양성을 인정하는 태도를 나타낼 때 유용합니다.","examples":[{"en":"I don\'t really understand why he likes that music, but to each their own.","ko":"나는 그가 왜 그 음악을 좋아하는지 잘 모르겠지만, 각자 취향이 다른 법이니까."},{"en":"You want pineapple on your pizza? Well, to each their own, I guess.","ko":"피자에 파인애플을 올리고 싶다고? 음, 각자 취향이 다르니 존중해."},{"en":"She prefers working alone, even though I like teamwork. To each their own.","ko":"나는 팀워크를 좋아하는데 그녀는 혼자 일하는 걸 선호해. 각자 방식이 다른 거지."},{"en":"My brother loves to wake up at 5 AM, but I can\'t imagine it. To each their own.","ko":"내 동생은 새벽 5시에 일어나는 것을 좋아하지만, 나는 상상도 못 해. 각자의 방식이 있는 거겠지."}],"related":[{"slug":"different-strokes-for-different-folks","title":"Different Strokes For Different Folks","type":"synonym","note":"사람마다 좋아하는 것이 다르다는 의미를 강조합니다."},{"slug":"there-s-no-accounting-for-taste","title":"There\'s No Accounting For Taste","type":"synonym","note":"취향은 설명하거나 따질 수 없다는 의미로, \'to each their own\'보다 다소 체념적인 뉘앙스를 가질 수 있습니다."},{"slug":"live-and-let-live","title":"Live And Let Live","type":"synonym","note":"타인의 삶의 방식이나 선택을 간섭하지 않고 내버려 둔다는 넓은 의미의 존중을 나타냅니다."}],"date":"2026-04-03T00:01"}');
;// ./blog/be-one-step-ahead/content.json
const be_one_step_ahead_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"be-one-step-ahead","title":"Be One Step Ahead","koreanPronunciation":"비 원 스텝 어헤드","tags":["관용구","자주 쓰는 표현"],"meaning":"다른 사람이나 경쟁자보다 미리 준비하거나 유리한 위치에 있어서 앞서 나간다는 의미입니다.","description":"이 표현은 어떤 상황에서 다른 사람들보다 더 빨리 생각하고 행동하여 유리한 고지를 점하거나 예상되는 문제를 미리 방지하는 능력을 설명할 때 사용됩니다. 경쟁이나 전략이 중요한 상황에서 특히 유용하게 쓰이며, 미리 계획하고 준비하는 것의 중요성을 강조합니다. 선수를 치거나, 한 수 앞서 나가는 상황을 묘사할 때 자주 쓰입니다.","examples":[{"en":"Our marketing team always tries to be one step ahead of the competition by constantly innovating.","ko":"우리 마케팅 팀은 끊임없이 혁신하여 항상 경쟁사보다 한 발 앞서 나가려고 노력합니다."},{"en":"She\'s a brilliant chess player; she\'s always one step ahead, anticipating her opponent\'s moves.","ko":"그녀는 뛰어난 체스 선수예요. 항상 상대방의 수를 예상하며 한 수 앞서 나갑니다."},{"en":"To succeed in the fast-paced tech industry, you need to be one step ahead of market trends.","ko":"급변하는 기술 산업에서 성공하려면 시장 동향보다 한 발 앞서 나가야 합니다."},{"en":"The detective was always one step ahead of the criminals, which helped him solve the case quickly.","ko":"그 형사는 항상 범인들보다 한 수 앞섰고, 그 덕분에 사건을 빠르게 해결할 수 있었습니다."},{"en":"We need to analyze future risks to ensure we\'re always one step ahead of potential problems.","ko":"우리는 잠재적인 문제보다 항상 한 발 앞서 나가기 위해 미래의 위험을 분석해야 합니다."}],"related":[{"slug":"stay-ahead-of-the-curve","title":"Stay Ahead of the Curve","type":"synonym","note":"변화하는 상황이나 트렌드에서 앞서 나간다는 의미입니다."},{"slug":"outsmart","title":"Outsmart","type":"synonym","note":"지략이나 교활함으로 다른 사람보다 한 수 위라는 의미입니다."},{"slug":"steal-a-march","title":"Steal a March","type":"synonym","note":"다른 사람이 알아차리지 못하게 미리 유리한 위치를 차지한다는 의미입니다."},{"slug":"on-top-of-things","title":"On Top of Things","type":"synonym","note":"상황을 잘 파악하고 통제하며, 모든 일을 잘 처리하고 있다는 의미입니다."},{"slug":"fall-behind","title":"Fall Behind","type":"antonym","note":"다른 사람이나 일정보다 뒤처진다는 의미입니다."}],"date":"2025-11-06T00:01"}');
;// ./blog/keep-going/content.json
const keep_going_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"keep-going","title":"Keep Going","koreanPronunciation":"킵 고잉","tags":["자주 쓰는 표현","구동사"],"meaning":"어떤 일을 계속 진행하거나 멈추지 않고 지속하다는 의미입니다","description":"이 표현은 특정 활동이나 노력을 중단하지 않고 계속 이어나가거나, 어려운 상황이나 역경에도 불구하고 포기하지 않고 나아가도록 격려할 때 사용됩니다. 목표 달성을 위해 꾸준히 노력하거나, 힘든 시기를 인내하며 극복해야 할 때 유용하게 쓰이는 표현입니다.","examples":[{"en":"Don\'t give up! You\'re doing great, just keep going!","ko":"포기하지 마! 아주 잘하고 있어, 계속해!"},{"en":"It\'s a long marathon, but we have to keep going until the finish line.","ko":"긴 마라톤이지만, 우리는 결승선까지 계속 가야 합니다."},{"en":"Despite the setbacks, she decided to keep going with her project.","ko":"어려움에도 불구하고, 그녀는 프로젝트를 계속 진행하기로 결정했다."},{"en":"When you feel like stopping, remember why you started and keep going.","ko":"멈추고 싶을 때, 왜 시작했는지 기억하고 계속 나아가세요."}],"related":[{"slug":"carry-on","title":"Carry On","type":"synonym","note":"비슷하게 \'계속하다, 지속하다\'의 의미로 사용됩니다."},{"slug":"continue","title":"Continue","type":"synonym","note":"가장 일반적인 \'계속하다\'라는 의미의 동사입니다."},{"slug":"persevere","title":"Persevere","type":"synonym","note":"어려움에도 불구하고 끈기 있게 계속한다는 뉘앙스가 강합니다."},{"slug":"give-up","title":"Give Up","type":"antonym","note":"하던 것을 포기하거나 그만둔다는 의미입니다."},{"slug":"stop","title":"Stop","type":"antonym","note":"단순히 하던 것을 멈춘다는 의미입니다."}],"date":"2025-08-26T00:00"}');
;// ./blog/give-away-the-secret/content.json
const give_away_the_secret_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"give-away-the-secret","title":"Give Away The Secret","koreanPronunciation":"기브 어웨이 더 시크릿","tags":["구동사","관용구","자주 쓰는 표현"],"meaning":"비밀을 누설하거나 밝히는 것을 의미합니다.","description":"이 표현은 다른 사람에게 말해서는 안 되는 정보를 실수로 혹은 의도치 않게 밝히거나 누설할 때 사용됩니다. 주로 숨겨져야 할 사실이 드러나는 상황을 묘사하며, 때로는 조심성 없이 발설하는 경우를 지적할 때 쓰이기도 합니다.","examples":[{"en":"Don\'t give away the secret, it\'s supposed to be a surprise.","ko":"비밀을 누설하지 마, 깜짝 선물이어야 해."},{"en":"His nervous behavior gave away the secret that he was hiding something.","ko":"그의 불안한 행동은 그가 무언가를 숨기고 있다는 비밀을 드러냈다."},{"en":"The child accidentally gave away the secret about the hidden presents.","ko":"아이는 실수로 숨겨진 선물에 대한 비밀을 누설했다."}],"related":[{"slug":"let-the-cat-out-of-the-bag","title":"Let The Cat Out Of The Bag","type":"synonym","note":"비밀을 밝히거나 누설한다는 의미로, 종종 실수로 드러낼 때 사용됩니다."},{"slug":"keep-a-secret","title":"Keep A Secret","type":"antonym","note":"비밀을 지키고 다른 사람에게 말하지 않는다는 반대 의미입니다."},{"slug":"blurt-out","title":"Blurt Out","type":"synonym","note":"무심코, 생각 없이 불쑥 말한다는 의미로, 비밀을 무심코 누설하는 상황과 관련됩니다."}],"date":"2025-09-18T00:01"}');
;// ./blog/lose-control/content.json
const lose_control_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"lose-control","title":"Lose Control","koreanPronunciation":"루즈 컨트롤","tags":["관용구","자주 쓰는 표현"],"meaning":"제어력을 잃거나 감정을 억제하지 못하게 되는 의미입니다.","description":"이 표현은 어떤 상황이나 자신의 감정을 더 이상 관리하거나 억제할 수 없게 되는 상태를 나타냅니다. 물리적인 제어력을 잃는 상황(예: 차량 제어 불능)이나, 분노, 슬픔, 공포 등 강한 감정에 휩싸여 이성적인 판단이나 행동을 하지 못하는 심리적 상태를 모두 포함합니다. 주로 부정적인 의미로 사용되며, 감정의 폭발이나 상황 악화의 결과를 암시합니다.","examples":[{"en":"The driver lost control of the car on the icy road.","ko":"운전자는 빙판길에서 차의 통제력을 잃었습니다."},{"en":"She started to cry and completely lost control of her emotions.","ko":"그녀는 울기 시작하며 감정을 완전히 주체하지 못했습니다."},{"en":"When he heard the bad news, he almost lost control.","ko":"그는 나쁜 소식을 듣고 거의 이성을 잃을 뻔했습니다."},{"en":"The crowd lost control when their favorite band came on stage.","ko":"가장 좋아하는 밴드가 무대에 오르자 군중은 통제 불능 상태가 되었습니다."}],"related":[{"slug":"lose-it","title":"Lose It","type":"synonym","note":"비격식적인 표현으로, 주로 감정을 주체하지 못하고 이성을 잃는 경우에 사용됩니다."},{"slug":"fly-off-the-handle","title":"Fly Off the Handle","type":"synonym","note":"갑자기 화를 내며 통제력을 잃는 상황을 묘사합니다."},{"slug":"snap","title":"Snap","type":"synonym","note":"갑작스러운 감정 폭발이나 정신적인 한계를 넘어설 때 사용됩니다."},{"slug":"keep-calm","title":"Keep Calm","type":"antonym","note":"침착함을 유지하고 평정심을 잃지 않는 것을 의미합니다."},{"slug":"maintain-control","title":"Maintain Control","type":"antonym","note":"자신이나 상황에 대한 통제력을 계속 유지하는 것을 의미합니다."}],"date":"2025-10-02T00:00"}');
;// ./blog/falsify-accounts/content.json
const falsify_accounts_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"falsify-accounts","title":"Falsify Accounts","koreanPronunciation":"펄서파이 어카운츠","tags":["자주 쓰는 표현"],"meaning":"장부나 회계 기록을 부정하게 조작하거나 왜곡하는 것을 의미합니다.","description":"이 표현은 기업이나 개인이 자신의 재정 기록, 특히 회계 장부를 고의로 변경하거나 허위로 작성하여 실제 재정 상태를 속이거나 은폐하는 행위를 나타냅니다. 주로 세금 회피, 투자자 기만, 대출 확보, 또는 내부 비리 숨기기 등의 불법적인 목적으로 이루어지며, 이는 심각한 법적 및 윤리적 문제를 초래할 수 있습니다.","examples":[{"en":"The company was caught trying to falsify accounts to hide their massive debt.","ko":"그 회사는 막대한 빚을 숨기기 위해 장부를 조작하려다 적발되었다."},{"en":"Falsifying accounts is a serious criminal offense and can lead to imprisonment.","ko":"장부 조작은 심각한 형사 범죄이며 투옥될 수 있습니다."},{"en":"Auditors found evidence that the manager had been falsifying expense accounts for years.","ko":"감사관들은 그 관리자가 수년 동안 경비 장부를 조작해왔다는 증거를 발견했다."},{"en":"Many startups feel pressure to falsify accounts to attract more investors.","ko":"많은 스타트업들이 더 많은 투자자를 유치하기 위해 장부를 조작해야 한다는 압박을 느낍니다."}],"related":[{"slug":"cook-the-books","title":"Cook The Books","type":"synonym","note":"회계 장부를 부정하게 조작하다."},{"slug":"doctor-the-books","title":"Doctor The Books","type":"synonym","note":"재정 기록을 속이거나 변경하다."},{"slug":"be-transparent","title":"Be Transparent","type":"antonym","note":"재정 기록을 정직하고 공개적으로 유지하다."}],"date":"2025-12-01T00:00"}');
;// ./blog/throw-a-wrench-in-the-works/content.json
const throw_a_wrench_in_the_works_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"throw-a-wrench-in-the-works","title":"Throw A Wrench In The Works","koreanPronunciation":"스로 어 렌치 인 더 웍스","tags":["관용구","자주 쓰는 표현"],"meaning":"예상치 못한 문제나 방해를 일으켜 계획이나 진행 중인 일을 망치거나 중단시키는 의미입니다.","description":"이 표현은 기계가 잘 작동하고 있을 때 갑자기 렌치(도구)를 던져 넣어 고장을 일으키는 모습에서 유래했습니다. 어떤 계획이나 시스템이 원활하게 진행되다가 예기치 않은 문제나 장애물로 인해 갑자기 멈추거나 혼란에 빠지는 상황을 묘사할 때 사용됩니다. 주로 부정적인 상황에서 쓰이며, 누군가 고의적으로 방해할 때도, 또는 우연히 문제가 발생했을 때도 사용될 수 있습니다.","examples":[{"en":"His sudden resignation really threw a wrench in the works for our project timeline.","ko":"그의 갑작스러운 사임은 우리 프로젝트 일정에 정말 큰 차질을 초래했습니다."},{"en":"The bad weather threw a wrench in the works for our outdoor concert plans.","ko":"궂은 날씨가 우리의 야외 콘서트 계획에 큰 지장을 주었습니다."},{"en":"Don\'t throw a wrench in the works by changing the plan at the last minute.","ko":"마지막 순간에 계획을 변경해서 일을 망치지 마세요."},{"en":"A technical glitch threw a wrench in the works, delaying the entire launch.","ko":"기술적 결함이 전체 출시를 지연시키면서 계획에 차질을 주었습니다."}],"related":[{"slug":"throw-a-monkey-wrench-in-the-works","title":"Throw A Monkey Wrench In The Works","type":"synonym","note":"미국식 표현으로 \'wrench\' 대신 \'monkey wrench\'를 사용합니다."},{"slug":"disrupt","title":"Disrupt","type":"synonym"},{"slug":"hinder","title":"Hinder","type":"synonym"},{"slug":"facilitate","title":"Facilitate","type":"antonym"},{"slug":"smooth-things-over","title":"Smooth Things Over","type":"antonym"}],"date":"2026-03-22T00:00"}');
;// ./blog/sweep-under-the-rug/content.json
const sweep_under_the_rug_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"sweep-under-the-rug","title":"Sweep Under the Rug","koreanPronunciation":"스윕 언더 더 러그","tags":["관용구"],"meaning":"문제나 불쾌한 사실을 숨겨서 다루지 않거나 회피하는 의미입니다.","description":"이 표현은 집에서 청소하기 싫은 먼지나 쓰레기를 카펫이나 러그 밑으로 밀어 넣어 숨기는 행위에서 유래했습니다. 즉, 어떤 문제, 실수, 또는 불편한 상황을 공식적으로 해결하거나 인정하지 않고 대충 덮어두려 할 때 비유적으로 사용됩니다. 주로 비판이나 책임 회피를 목적으로 진실을 은폐하려는 상황에 쓰이며, 문제가 해결되지 않고 숨겨진 채로 남아있음을 암시합니다.","examples":[{"en":"The company tried to sweep the scandal under the rug, but the media found out.","ko":"그 회사는 스캔들을 은폐하려 했지만, 언론이 알아냈다."},{"en":"Don\'t just sweep your problems under the rug; you need to address them.","ko":"문제를 그냥 덮어두지 마세요; 직시하고 해결해야 합니다."},{"en":"Many politicians are accused of sweeping inconvenient truths under the rug.","ko":"많은 정치인들이 불편한 진실을 은폐하려 한다는 비난을 받는다."},{"en":"Ignoring the issue won\'t make it disappear; you can\'t just sweep it under the rug.","ko":"문제를 무시한다고 사라지지 않을 것입니다; 그냥 덮어둘 수는 없습니다."}],"related":[{"slug":"cover-up","title":"Cover Up","type":"synonym","note":"비밀로 하거나 숨기기 위해 노력하는 것."},{"slug":"hush-up","title":"Hush Up","type":"synonym","note":"무언가를 비밀로 유지하려고 애쓰거나 잠재우는 것."},{"slug":"turn-a-blind-eye","title":"Turn a Blind Eye","type":"synonym","note":"고의적으로 문제를 무시하거나 못 본 척하는 것."},{"slug":"bring-to-light","title":"Bring to Light","type":"antonym","note":"숨겨진 사실이나 문제를 드러내어 밝히는 것."}],"date":"2025-08-23T00:00"}');
;// ./blog/seize-the-day/content.json
const seize_the_day_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"seize-the-day","title":"Seize the Day","koreanPronunciation":"시즈 더 데이","tags":["관용구","자주 쓰는 표현"],"meaning":"현재의 순간을 최대한 활용하고 즐기라는 의미입니다","description":"이 표현은 라틴어 \'Carpe Diem\'에서 유래한 것으로, 미래를 걱정하기보다 현재를 즐기고 기회를 포착하라는 뜻을 담고 있습니다. 주어진 시간을 소중히 여기고 적극적으로 삶에 임할 것을 권장할 때 사용됩니다. 후회 없는 삶을 위해 오늘 주어진 기회와 행복을 붙잡으라는 메시지를 전달합니다.","examples":[{"en":"Don\'t wait for the perfect moment, seize the day!","ko":"완벽한 순간을 기다리지 말고, 오늘을 붙잡아!"},{"en":"He decided to seize the day and finally ask her out.","ko":"그는 오늘을 붙잡기로 결심하고 마침내 그녀에게 데이트 신청을 했다."},{"en":"Life is short, so you have to seize the day.","ko":"인생은 짧으니, 오늘을 잡아야 해."},{"en":"After years of hesitation, she finally decided to seize the day and start her own business.","ko":"수년간의 망설임 끝에 그녀는 마침내 오늘을 잡고 자신의 사업을 시작하기로 결심했다."}],"related":[{"slug":"carpe-diem","title":"Carpe Diem","type":"synonym","note":"이 표현의 라틴어 원형으로, 뜻이 거의 같습니다."},{"slug":"live-in-the-present","title":"Live in the Present","type":"synonym","note":"현재에 충실하라는 의미로, \'Seize the Day\'와 맥락을 같이 합니다."},{"slug":"make-the-most-of-it","title":"Make the Most of It","type":"synonym","note":"주어진 상황이나 기회를 최대한 활용하라는 의미입니다."},{"slug":"procrastinate","title":"Procrastinate","type":"antonym","note":"일을 미루고 꾸물거리는 행동으로, \'Seize the Day\'와 반대되는 태도입니다."},{"slug":"put-off-until-tomorrow","title":"Put Off Until Tomorrow","type":"antonym","note":"오늘 할 일을 내일로 미루는 것을 의미합니다."}],"date":"2025-10-28T00:01"}');
