const mess_around_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"mess-around","title":"Mess Around","koreanPronunciation":"메스 어라운드","tags":["구동사","속어","자주 쓰는 표현"],"meaning":"시간을 낭비하거나, 장난을 치거나, 또는 어떤 일에 진지하지 않게 임하는 것의 의미입니다.","description":"이 표현은 주로 여러 가지 상황에서 사용될 수 있습니다. 첫째, \'시간을 낭비하다\' 또는 \'할 일을 하지 않고 빈둥거리다\'는 의미로 쓰입니다. 둘째, \'장난치다\', \'짓궂게 굴다\'와 같이 농담이나 가벼운 행동을 할 때 사용됩니다. 셋째, 무언가를 심각하게 받아들이지 않고 가볍게 다루거나 실험적으로 이것저것 해보는 상황에서도 쓰일 수 있습니다. 맥락에 따라 부정적인 의미(게으름, 무책임)를 가질 수도 있고, 중립적인 의미(가볍게 놀다, 시험해 보다)를 가질 수도 있습니다.","examples":[{"en":"Stop messing around and get to work!","ko":"장난 그만하고 일 시작해!"},{"en":"The kids were just messing around in the park, having fun.","ko":"아이들은 공원에서 그냥 놀고 있었고, 즐거워 보였어요."},{"en":"He likes to mess around with old cars in his garage on weekends.","ko":"그는 주말에 차고에서 낡은 차들을 이것저것 만지며 노는 것을 좋아한다."},{"en":"Don\'t mess around with that broken wire; it could be dangerous.","ko":"그 끊어진 전선 가지고 장난치지 마; 위험할 수 있어."}],"related":[{"slug":"fool-around","title":"Fool Around","type":"synonym","note":"어리석게 행동하거나 장난을 치며 시간을 보내는 것."},{"slug":"dally","title":"Dally","type":"synonym","note":"꾸물거리거나 시간을 낭비하는 것. \'dilly-dally\'보다 격식이 있는 느낌."},{"slug":"procrastinate","title":"Procrastinate","type":"synonym","note":"해야 할 일을 미루고 시간을 낭비하는 것에 중점."},{"slug":"be-serious","title":"Be Serious","type":"antonym","note":"진지하게 행동하고 농담을 하지 않는 것."},{"slug":"get-to-work","title":"Get To Work","type":"antonym","note":"일을 시작하거나 해야 할 일에 집중하는 것."}],"date":"2026-03-11T00:01"}');
;// ./blog/hold-a-grudge/content.json
const hold_a_grudge_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"hold-a-grudge","title":"Hold a Grudge","koreanPronunciation":"홀드 어 그러지","tags":["관용구","자주 쓰는 표현"],"meaning":"과거의 불쾌한 일이나 상처에 대해 계속해서 화를 내거나 앙심을 품는 의미입니다","description":"이 표현은 과거의 불쾌한 사건이나 상대방의 행동으로 인해 생긴 분노, 원한, 불만을 오랫동안 마음속에 품고 잊지 못하는 상태를 나타냅니다. 주로 용서하지 못하고 복수심이나 적대감을 유지할 때 사용됩니다. \'grudge\'는 원한, 앙심을 뜻하며, \'hold\'는 \'붙잡다\', \'유지하다\'의 의미를 가집니다. 따라서 \'앙심을 붙잡고 있다\'는 직역으로 이해할 수 있습니다.","examples":[{"en":"I\'m not one to hold a grudge; I usually forgive and forget.","ko":"저는 앙심을 품는 사람이 아니에요. 보통 용서하고 잊는 편이죠."},{"en":"She\'s still holding a grudge against him for what he said last year.","ko":"그녀는 그가 작년에 한 말 때문에 여전히 앙심을 품고 있어요."},{"en":"It\'s unhealthy to hold a grudge; it only hurts yourself in the long run.","ko":"앙심을 품는 것은 건강에 좋지 않습니다. 결국 자신만 해칠 뿐이죠."},{"en":"You need to let go and stop holding a grudge.","ko":"잊고 앙심을 품는 것을 그만둬야 해."}],"related":[{"slug":"bear-a-grudge","title":"Bear a Grudge","type":"synonym"},{"slug":"resent","title":"Resent","type":"synonym","note":"더 넓은 의미의 분개나 원망"},{"slug":"let-go","title":"Let Go","type":"antonym","note":"앙심을 놓아주다"},{"slug":"move-on","title":"Move On","type":"antonym","note":"과거의 불화를 잊고 나아가다"}],"date":"2026-03-12T00:00"}');
;// ./blog/in-the-dark/content.json
const in_the_dark_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"in-the-dark","title":"In The Dark","koreanPronunciation":"인 더 다크","tags":["관용구","자주 쓰는 표현"],"meaning":"어떤 상황이나 정보에 대해 전혀 알지 못하는 상태를 의미입니다.","description":"이 표현은 중요한 정보나 사실을 알지 못하거나, 특정 상황의 진행 과정에 대해 무지한 상태를 나타낼 때 사용됩니다. 종종 의도적으로 정보가 차단되어 모르게 되는 경우나 단순히 상황 파악이 안 되는 경우에 쓰이며, 당사자가 답답함을 느끼거나 불리한 입장에 놓일 수 있음을 암시하기도 합니다.","examples":[{"en":"I\'m completely in the dark about the new project. No one has told me anything.","ko":"저는 새 프로젝트에 대해 완전히 깜깜합니다. 아무도 저에게 아무것도 말해주지 않았어요."},{"en":"Don\'t keep me in the dark; please tell me what\'s going on.","ko":"저를 모르게 하지 마세요; 무슨 일인지 알려주세요."},{"en":"The management decided to keep the employees in the dark about the merger until the last minute.","ko":"경영진은 합병에 대해 마지막 순간까지 직원들을 모르게 하기로 결정했습니다."},{"en":"She\'s been left in the dark about her promotion opportunities.","ko":"그녀는 자신의 승진 기회에 대해 전혀 알지 못했습니다."}],"related":[{"slug":"out-of-the-loop","title":"Out Of The Loop","type":"synonym","note":"중요한 정보나 상황에서 제외되어 알지 못하는 상태를 의미합니다."},{"slug":"unaware","title":"Unaware","type":"synonym","note":"어떤 사실이나 상황을 인지하지 못하는 일반적인 상태를 나타냅니다."},{"slug":"in-the-know","title":"In The Know","type":"antonym","note":"어떤 내부 정보나 비밀을 잘 알고 있는 상태를 의미합니다."},{"slug":"up-to-speed","title":"Up To Speed","type":"antonym","note":"최신 정보나 상황을 완전히 파악하고 있는 상태를 의미합니다."}],"date":"2026-02-05T00:00"}');
;// ./blog/get-a-grip/content.json
const get_a_grip_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"get-a-grip","title":"Get A Grip","koreanPronunciation":"겟 어 그립","tags":["자주 쓰는 표현","구동사"],"meaning":"통제력을 되찾거나 침착하게 행동하라는 의미입니다.","description":"이 표현은 보통 감정적으로 동요하거나 혼란스러워하는 사람에게 진정하고 상황을 통제하라는 조언을 할 때 사용됩니다. 자기 자신을 다잡고 이성적으로 생각하라는 의미를 내포합니다. 종종 명령형으로 쓰이며, \'정신 차려\' 또는 \'마음을 가다듬어\'와 유사한 뜻으로 사용됩니다.","examples":[{"en":"Stop panicking and get a grip!","ko":"당황하지 말고 정신 차려!"},{"en":"I know you\'re upset, but you need to get a grip on yourself.","ko":"속상한 건 알지만, 스스로 정신을 가다듬어야 해."},{"en":"He lost his temper, but then he got a grip and apologized.","ko":"그는 화를 냈지만, 이내 정신을 차리고 사과했다."},{"en":"The situation is tough, but we have to get a grip and find a solution.","ko":"상황이 어렵지만, 우리는 침착하게 해결책을 찾아야 합니다."}],"related":[{"slug":"calm-down","title":"Calm Down","type":"synonym"},{"slug":"snap-out-of-it","title":"Snap Out Of It","type":"synonym","note":"갑자기 불쾌한 기분이나 행동을 멈추고 제정신을 차리라는 의미가 강합니다."},{"slug":"keep-your-head","title":"Keep Your Head","type":"synonym","note":"어려운 상황에서도 침착하고 이성적인 태도를 유지하라는 의미입니다."}],"date":"2025-09-19T00:00"}');
;// ./blog/deceive-someone/content.json
const deceive_someone_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"deceive-someone","title":"Deceive Someone","koreanPronunciation":"디시브 섬원","tags":["자주 쓰는 표현"],"meaning":"누군가를 속이거나 기만한다는 의미입니다.","description":"이 표현은 누군가를 속이거나 기만하여 사실과 다른 것을 믿게 만드는 행위를 의미합니다. 주로 거짓말이나 숨겨진 의도를 통해 상대방을 오도할 때 사용됩니다.","examples":[{"en":"He tried to deceive her with a fake story about his past.","ko":"그는 자신의 과거에 대한 가짜 이야기로 그녀를 속이려 했다."},{"en":"Don\'t let appearances deceive you; he\'s not as innocent as he looks.","ko":"겉모습에 속지 마세요; 그는 보이는 것처럼 순진하지 않습니다."},{"en":"The magician deceived the audience with his clever sleight of hand.","ko":"마술사는 교묘한 손놀림으로 관객을 속였다."},{"en":"It\'s wrong to deceive people for personal gain.","ko":"개인적인 이득을 위해 사람들을 속이는 것은 잘못이다."},{"en":"The company was accused of trying to deceive its investors about its financial health.","ko":"그 회사는 재정 상태에 대해 투자자들을 속이려 했다는 비난을 받았다."}],"related":[{"slug":"trick-someone","title":"Trick Someone","type":"synonym","note":"장난스럽거나 교묘하게 속이는 것에 중점을 둡니다."},{"slug":"mislead-someone","title":"Mislead Someone","type":"synonym","note":"잘못된 방향으로 이끌거나 오해하게 만드는 것에 중점을 둡니다."},{"slug":"fool-someone","title":"Fool Someone","type":"synonym","note":"누군가를 바보로 만들거나 어리석게 속이는 것을 의미합니다."},{"slug":"con-someone","title":"Con Someone","type":"synonym","note":"속임수를 써서 돈이나 재산을 가로채는 등의 사기 행위를 의미합니다."},{"slug":"be-honest","title":"Be Honest","type":"antonym","note":"속이지 않고 진실을 말하는 것을 의미합니다."}],"date":"2026-01-05T00:00"}');
;// ./blog/think-critically/content.json
const think_critically_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"think-critically","title":"Think Critically","koreanPronunciation":"띵크 크리티컬리","tags":["자주 쓰는 표현"],"meaning":"어떤 주제나 상황에 대해 깊이 분석하고, 정보를 평가하며, 논리적으로 추론하는 것을 의미입니다.","description":"이 표현은 단순히 정보를 수동적으로 받아들이는 것을 넘어, 그 정보의 타당성, 신뢰성, 그리고 내포된 의미를 의심하고 질문하는 능력을 강조합니다. 문제 해결, 합리적인 의사 결정, 그리고 복잡한 상황을 종합적으로 이해하는 데 필수적인 인지 과정입니다. 개인의 지적 성장뿐만 아니라 학업, 직업 생활, 그리고 사회 전반에서 매우 중요한 역량으로 간주됩니다.","examples":[{"en":"It\'s important to think critically about the news you read online.","ko":"온라인에서 읽는 뉴스에 대해 비판적으로 생각하는 것이 중요합니다."},{"en":"Students should be encouraged to think critically, not just memorize facts.","ko":"학생들은 단순히 사실을 암기하는 것이 아니라 비판적으로 생각하도록 장려되어야 합니다."},{"en":"Before making a big decision, take time to think critically about all the pros and cons.","ko":"중요한 결정을 내리기 전에 모든 장단점을 비판적으로 생각할 시간을 가지세요."},{"en":"A good leader needs to think critically to navigate complex challenges.","ko":"좋은 리더는 복잡한 난관을 헤쳐나가기 위해 비판적으로 생각해야 합니다."}],"related":[{"slug":"analyze-deeply","title":"Analyze Deeply","type":"synonym","note":"정보나 상황을 깊이 파고들어 분석하는 행위"},{"slug":"evaluate-information","title":"Evaluate Information","type":"synonym","note":"주어진 정보의 가치나 신뢰성을 판단하는 행위"},{"slug":"question-assumptions","title":"Question Assumptions","type":"synonym","note":"당연하게 여기는 것들에 대해 의문을 제기하는 행위"},{"slug":"accept-blindly","title":"Accept Blindly","type":"antonym","note":"아무런 비판 없이 정보를 수용하는 태도"},{"slug":"take-at-face-value","title":"Take at Face Value","type":"antonym","note":"겉으로 보이는 그대로를 받아들이고 깊이 생각하지 않는 것"}],"date":"2026-03-17T00:00"}');
