const give_up_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"give-up","title":"Give Up","koreanPronunciation":"기브 업","tags":["구동사","자주 쓰는 표현"],"meaning":"포기하다, 단념하다를 의미입니다","description":"이 표현은 어떤 목표나 노력을 더 이상 계속하지 않겠다고 결정할 때 사용합니다. 어려움이나 실패로 인해 희망을 잃었을 때 많이 쓰이며, 긍정적인 의미보다는 아쉬움이나 체념을 담고 있습니다. 일상생활, 공부, 운동, 인간관계 등 다양한 상황에서 널리 쓰입니다.","examples":[{"en":"I won’t give up until I succeed.","ko":"성공할 때까지 포기하지 않을 거야."},{"en":"Don’t give up on your dreams.","ko":"꿈을 포기하지 마."},{"en":"She gave up smoking last year.","ko":"그녀는 작년에 담배를 끊었어."},{"en":"After several failed attempts, he finally gave up.","ko":"몇 번 실패한 후에 결국 포기했어."},{"en":"Never give up, no matter how hard it gets.","ko":"아무리 힘들어도 절대 포기하지 마."}],"related":[{"slug":"quit","title":"Quit","type":"synonym"},{"slug":"throw-in-the-towel","title":"Throw in the towel","type":"synonym"},{"slug":"call-it-quits","title":"Call it quits","type":"synonym"},{"slug":"surrender","title":"Surrender","type":"synonym"},{"slug":"drop-out","title":"Drop out","type":"synonym"}],"date":"2025-06-08T14:30"}');
;// ./blog/buck-up/content.json
const buck_up_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"buck-up","title":"Buck Up","koreanPronunciation":"벅 업","tags":["구동사","자주 쓰는 표현"],"meaning":"용기를 내거나 기운을 내라는 의미입니다","description":"이 표현은 주로 힘든 상황이나 실망스러운 일을 겪을 때, 기운을 내고 긍정적인 태도를 가지라고 격려할 때 사용됩니다. 누군가 낙담하고 있을 때, 그에게 힘내라고 북돋아 주는 말입니다.","examples":[{"en":"Come on, buck up! It\'s not the end of the world.","ko":"힘내, 벅 업! 세상이 끝난 것도 아니잖아."},{"en":"You need to buck up and face the challenge.","ko":"넌 힘내서 그 도전에 맞서야 해."},{"en":"After a good cry, she decided to buck up and try again.","ko":"한바탕 울고 나서, 그녀는 기운을 내어 다시 시도하기로 결정했다."},{"en":"Don\'t let one mistake get you down, buck up and learn from it.","ko":"한 번의 실수에 낙담하지 마, 힘내서 교훈을 얻어."}],"related":[{"slug":"cheer-up","title":"Cheer Up","note":"더 일반적인 \'힘내\'의 의미"},{"slug":"pull-yourself-together","title":"Pull Yourself Together","note":"마음의 동요를 가라앉히고 침착함을 되찾다"},{"slug":"keep-your-chin-up","title":"Keep Your Chin Up","note":"어려움 속에서도 긍정적인 태도를 유지하다"}],"date":"2025-08-13T00:00"}');
;// ./blog/work-around-the-clock/content.json
const work_around_the_clock_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"work-around-the-clock","title":"Work Around The Clock","koreanPronunciation":"워크 어라운드 더 클락","tags":["관용구","자주 쓰는 표현"],"meaning":"밤낮없이, 즉 하루 24시간 내내 쉬지 않고 계속 일하다는 의미입니다.","description":"이 표현은 하루 24시간 내내, 즉 밤에도 쉬지 않고 계속 일하는 것을 묘사할 때 사용됩니다. 이는 대개 매우 바쁘거나 긴급한 상황에서 강도 높은 노동을 할 때 주로 쓰입니다. 마감 기한을 맞추기 위해, 중요한 프로젝트를 완료하기 위해, 또는 위기 상황에 대처하기 위해 밤샘 작업을 하거나 휴일 없이 일하는 상황을 나타낼 수 있습니다. 이 표현은 극심한 노력과 헌신을 강조할 때 사용됩니다.","examples":[{"en":"We had to work around the clock to finish the project on time.","ko":"우리는 프로젝트를 제시간에 마치기 위해 밤낮없이 일해야 했습니다."},{"en":"During the crisis, emergency services worked around the clock to help people.","ko":"위기 동안, 응급 서비스는 사람들을 돕기 위해 밤낮없이 일했습니다."},{"en":"The factory is working around the clock to meet the sudden increase in demand.","ko":"그 공장은 갑작스러운 수요 증가를 맞추기 위해 24시간 가동하고 있습니다."},{"en":"I\'ve been working around the clock all week, so I\'m completely exhausted.","ko":"저는 이번 주 내내 밤낮없이 일해서 완전히 지쳤습니다."}],"related":[{"slug":"work-tirelessly","title":"Work Tirelessly","type":"synonym","note":"지치지 않고 끊임없이 일하다"},{"slug":"pull-long-hours","title":"Pull Long Hours","type":"synonym","note":"평소보다 오랜 시간 일하다"},{"slug":"take-time-off","title":"Take Time Off","type":"antonym","note":"일에서 휴식을 취하다"},{"slug":"relax-and-unwind","title":"Relax And Unwind","type":"antonym","note":"긴장을 풀고 쉬다"}],"date":"2026-01-24T00:00"}');
