const kiss_up_to_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"kiss-up-to","title":"Kiss Up To","koreanPronunciation":"키스 업 투","tags":["구동사","자주 쓰는 표현","속어"],"meaning":"자신에게 이득을 얻기 위해 다른 사람에게 아첨하거나 비위를 맞추다의 의미입니다.","description":"이 표현은 주로 누군가에게 과도하게 칭찬하거나 아부하여 개인적인 이득을 취하려는 부정적인 뉘앙스를 담고 있습니다. 직장이나 학교 등 위계질서가 있는 상황에서 상사나 선생님에게 잘 보이기 위해 불필요하게 아첨하는 행위를 묘사할 때 자주 사용됩니다. 동사 \'kiss up\' 뒤에 \'to\'가 붙어 \'누구에게\' 아첨하는지 명시합니다.","examples":[{"en":"He\'s always kissing up to the boss to get a promotion.","ko":"그는 승진을 위해 항상 상사에게 아첨하고 있다."},{"en":"I don\'t like how she tries to kiss up to the professor just for a good grade.","ko":"나는 그녀가 좋은 학점을 받으려고 교수님께 아부하는 방식이 싫다."},{"en":"You shouldn\'t have to kiss up to anyone to get what you want; work hard instead.","ko":"원하는 것을 얻기 위해 누구에게도 아첨할 필요는 없습니다; 대신 열심히 일하세요."},{"en":"The new employee was accused of kissing up to the manager.","ko":"새 직원은 부장에게 아첨한다는 비난을 받았다."}],"related":[{"slug":"suck-up-to","title":"Suck Up To","type":"synonym","note":"더 노골적이고 부정적인 의미로 아첨하는 행위를 강조합니다."},{"slug":"flatter","title":"Flatter","type":"synonym","note":"아첨하다는 일반적인 의미로, \'kiss up to\'보다는 덜 부정적일 수 있습니다."},{"slug":"curry-favor-with","title":"Curry Favor With","type":"synonym","note":"호의를 얻으려고 노력하다는 의미로, 아첨과 유사하며 약간 더 격식 있는 표현입니다."},{"slug":"brown-nose","title":"Brown-nose","type":"synonym","note":"매우 저속하고 직접적인 표현으로, 굴욕적으로 아첨하는 것을 의미합니다."}],"date":"2025-11-01T00:00"}');
;// ./blog/build-from-the-ground-up/content.json
const build_from_the_ground_up_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"build-from-the-ground-up","title":"Build From The Ground Up","koreanPronunciation":"빌드 프롬 더 그라운드 업","tags":["관용구","자주 쓰는 표현"],"meaning":"기반부터 새롭게 시작하거나, 아무것도 없는 상태에서 무언가를 창조하는 것을 의미입니다","description":"이 표현은 어떤 프로젝트, 사업, 시스템 등을 완전히 처음부터, 즉 기초부터 쌓아 올린다는 뜻입니다. 기존의 것을 개선하거나 수정하는 것이 아니라, 백지 상태에서 완전히 새로운 것을 만들어나가는 과정을 강조할 때 사용됩니다. 이는 대개 많은 노력과 시간이 필요하다는 뉘앙스를 포함합니다.","examples":[{"en":"We decided to build the entire software from the ground up to ensure its stability.","ko":"안정성을 확보하기 위해 소프트웨어를 완전히 처음부터 개발하기로 결정했습니다."},{"en":"After the fire, they had to build their home from the ground up.","ko":"화재 후에 그들은 집을 처음부터 다시 지어야 했습니다."},{"en":"The startup aimed to build a new business model from the ground up, disrupting the traditional market.","ko":"그 스타트업은 전통 시장을 뒤흔들며 새로운 비즈니스 모델을 처음부터 구축하는 것을 목표로 했습니다."},{"en":"She built her successful company from the ground up with just an idea and a lot of hard work.","ko":"그녀는 아이디어와 많은 노력만으로 성공적인 회사를 처음부터 일구어냈습니다."}],"related":[{"slug":"start-from-scratch","title":"Start From Scratch","note":"아무것도 없는 상태에서 완전히 처음부터 시작하다"},{"slug":"lay-the-groundwork","title":"Lay The Groundwork","note":"성공적인 결과를 위한 기초 작업이나 준비를 하다"},{"slug":"from-square-one","title":"From Square One","note":"실패 후 처음부터 다시 시작하다"}],"date":"2025-08-16T00:00"}');
;// ./blog/spin-ones-wheels/content.json
const spin_ones_wheels_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"spin-ones-wheels","title":"Spin One\'s Wheels","koreanPronunciation":"스핀 원스 휠스","tags":["관용구","자주 쓰는 표현"],"meaning":"노력에도 불구하고 아무런 진전이 없거나 비효율적으로 시간을 보내는 것을 의미합니다.","description":"이 표현은 자동차 바퀴가 빠르게 돌지만 땅을 잡지 못해 앞으로 나아가지 못하고 헛도는 이미지에서 유래했습니다. 어떤 일에 많은 시간과 에너지를 쏟아붓지만 실제적인 성과나 진전을 얻지 못하는 상황, 즉 생산성 없이 제자리걸음만 하는 답답한 상황을 비유할 때 사용됩니다. 주로 노력이 올바른 방향으로 향하지 않거나 효과적이지 않을 때 쓰이며, 시간과 자원을 낭비하고 있음을 강조합니다.","examples":[{"en":"I feel like I\'m just spinning my wheels in this job; I\'m not learning anything new or progressing.","ko":"이 직장에서 제자리걸음만 하는 것 같아요. 새로운 것을 배우거나 발전하지 못하고 있어요."},{"en":"We\'ve been discussing this issue for hours, but we\'re just spinning our wheels. Let\'s take a break and revisit it later.","ko":"몇 시간 동안 이 문제에 대해 논의했지만, 계속 헛바퀴만 돌고 있어요. 잠시 쉬었다가 나중에 다시 논의합시다."},{"en":"If you don\'t have a clear goal, you\'ll end up spinning your wheels without achieving much.","ko":"명확한 목표가 없으면, 많은 것을 이루지 못하고 헛바퀴만 돌게 될 거예요."},{"en":"The project team was spinning its wheels for weeks, unable to make a breakthrough.","ko":"프로젝트 팀은 몇 주 동안 헛바퀴만 돌며 돌파구를 찾지 못했습니다."}],"related":[{"slug":"tread-water","title":"Tread Water","type":"synonym","note":"노력에도 불구하고 제자리에 머물러 있음을 나타냅니다."},{"slug":"go-nowhere","title":"Go Nowhere","type":"synonym","note":"어떤 노력에도 불구하고 진전이 없음을 강조합니다."},{"slug":"make-progress","title":"Make Progress","type":"antonym","note":"꾸준히 발전하고 성과를 내는 것을 의미합니다."},{"slug":"move-forward","title":"Move Forward","type":"antonym","note":"계획이나 목표를 향해 나아가는 것을 나타냅니다."}],"date":"2025-12-11T00:01"}');
;// ./blog/past-its-prime/content.json
const past_its_prime_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"past-its-prime","title":"Past Its Prime","koreanPronunciation":"패스트 잇츠 프라임","tags":["관용구"],"meaning":"최고의 상태나 능력을 이미 지났다는 의미입니다.","description":"이 표현은 사람, 사물 또는 개념이 전성기나 가장 좋았던 시기를 이미 지나서, 이전만큼의 효율성, 매력, 또는 가치를 가지지 못하는 상태를 설명할 때 사용됩니다. 음식의 신선도가 떨어졌거나, 운동선수의 기량이 예전 같지 않거나, 유행이 지난 것을 묘사할 때 자주 쓰입니다.","examples":[{"en":"This old car is definitely past its prime, but it still runs.","ko":"이 낡은 차는 확실히 전성기가 지났지만, 그래도 아직 달릴 수는 있다."},{"en":"Some critics say the director\'s recent films are past their prime, lacking the brilliance of his earlier works.","ko":"일부 비평가들은 그 감독의 최근 영화들이 전성기가 지났고, 초기작의 탁월함이 부족하다고 말한다."},{"en":"I think these apples are past their prime; they\'re getting soft.","ko":"이 사과들은 전성기가 지난 것 같아요; 물러지고 있어요."},{"en":"Even legendary athletes eventually find themselves past their prime.","ko":"전설적인 운동선수들도 결국에는 전성기가 지났다는 것을 알게 된다."}],"related":[{"slug":"over-the-hill","title":"Over The Hill","type":"synonym","note":"주로 사람의 나이가 많아 전성기가 지났을 때 사용됩니다."},{"slug":"on-the-decline","title":"On The Decline","type":"synonym","note":"점차적으로 상태가 안 좋아지는 것을 나타냅니다."},{"slug":"past-its-shelf-life","title":"Past Its Shelf Life","type":"synonym","note":"주로 식품이나 제품의 유통기한이 지났을 때 사용됩니다."},{"slug":"in-its-heyday","title":"In Its Heyday","type":"antonym","note":"가장 번성했던 시기를 의미합니다."},{"slug":"at-its-peak","title":"At Its Peak","type":"antonym","note":"가장 높은 수준이나 전성기에 있음을 의미합니다."}],"date":"2025-09-27T00:00"}');
