const shoot_oneself_in_the_foot_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"shoot-oneself-in-the-foot","title":"Shoot Oneself in the Foot","koreanPronunciation":"슛 원셀프 인 더 풋","tags":["관용구","자주 쓰는 표현"],"meaning":"스스로에게 해를 끼치거나 상황을 악화시키는 행동을 하는 의미입니다.","description":"이 표현은 총으로 자신의 발을 쏴서 스스로에게 상처를 입힌다는 물리적인 행위에서 유래했습니다. 즉, 의도치 않게 혹은 부주의하게 자신의 목표를 방해하거나 자신에게 불리한 결과를 초래하는 행동이나 말을 할 때 사용됩니다. 흔히 후회할 만한 결정이나 어리석은 실수를 저질렀을 때 비유적으로 쓰이며, 자기 꾀에 자기가 넘어가는 상황을 묘사할 때 적절합니다.","examples":[{"en":"He really shot himself in the foot by insulting the interviewer.","ko":"그는 면접관을 모욕함으로써 정말 스스로 무덤을 팠다."},{"en":"Don\'t shoot yourself in the foot by procrastinating on this important project.","ko":"이 중요한 프로젝트를 미루다가 스스로에게 해를 끼치지 마라."},{"en":"The company shot itself in the foot with their recent controversial advertisement.","ko":"그 회사는 최근 논란이 된 광고로 자멸했다."},{"en":"If you keep complaining about your job, you might shoot yourself in the foot and get fired.","ko":"계속 직장에 대해 불평하면, 스스로 발등을 찍고 해고될 수도 있다."},{"en":"Admitting your mistake now would be shooting yourself in the foot.","ko":"지금 실수를 인정하는 것은 자충수가 될 것이다."}],"related":[{"slug":"dig-ones-own-grave","title":"Dig One\'s Own Grave","type":"synonym","note":"스스로의 행동으로 인해 좋지 않은 상황을 만들다."},{"slug":"cut-off-ones-nose-to-spite-ones-face","title":"Cut Off One\'s Nose to Spite One\'s Face","type":"synonym","note":"앙갚음하려다 오히려 자신에게 손해를 끼치다."},{"slug":"self-sabotage","title":"Self-sabotage","type":"synonym","note":"스스로의 성공이나 행복을 방해하는 행동을 하다."},{"slug":"play-ones-cards-right","title":"Play One\'s Cards Right","type":"antonym","note":"기회를 잘 활용하여 성공적으로 상황을 이끌어 나가다."}],"date":"2026-01-30T00:00"}');
;// ./blog/roll-with-the-punches/content.json
const roll_with_the_punches_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"roll-with-the-punches","title":"Roll With the Punches","koreanPronunciation":"롤 위드 더 펀치스","tags":["관용구","자주 쓰는 표현"],"meaning":"어려운 상황이나 비판을 유연하게 받아들이고 적응하며 대처한다는 의미입니다.","description":"이 표현은 권투에서 주먹의 충격을 줄이기 위해 몸을 움직이는 것에서 유래했습니다. 비유적으로는 삶에서 예상치 못한 어려움이나 역경, 비판 등을 만났을 때 이를 회피하거나 좌절하는 대신, 침착하고 유연하게 받아들이며 대처하고 적응하는 태도를 의미합니다. 즉, 어려운 상황에 부딪혔을 때 쉽게 포기하지 않고 끈기 있게 극복해 나가는 자세를 강조합니다.","examples":[{"en":"Life throws a lot of challenges at you, so you need to learn to roll with the punches.","ko":"인생은 많은 어려움을 던져주기 때문에, 유연하게 대처하는 법을 배워야 합니다."},{"en":"He\'s always been good at rolling with the punches, no matter how tough the situation gets.","ko":"그는 상황이 아무리 어려워져도 항상 유연하게 대처하는 데 능숙했습니다."},{"en":"Our team faced unexpected setbacks, but we managed to roll with the punches and still achieve our goals.","ko":"우리 팀은 예상치 못한 난관에 부딪혔지만, 유연하게 대처하여 목표를 달성할 수 있었습니다."}],"related":[{"slug":"adapt-to-change","title":"Adapt to Change","type":"synonym"},{"slug":"go-with-the-flow","title":"Go With the Flow","type":"synonym"},{"slug":"take-it-in-stride","title":"Take It in Stride","type":"synonym"},{"slug":"give-up-easily","title":"Give Up Easily","type":"antonym","note":"쉽게 좌절하거나 포기하는 것"},{"slug":"resist-change","title":"Resist Change","type":"antonym","note":"변화에 저항하거나 적응하지 않으려 하는 것"}],"date":"2025-08-20T00:00"}');
;// ./blog/work-tirelessly/content.json
const work_tirelessly_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"work-tirelessly","title":"Work Tirelessly","koreanPronunciation":"워크 타이어리스리","tags":["자주 쓰는 표현","연어"],"meaning":"지치지 않고 매우 열심히 일하거나 노력하는 것의 의미입니다.","description":"이 표현은 어떤 목표를 달성하기 위해 끊임없이, 그리고 매우 열심히 노력하는 행위를 묘사할 때 사용됩니다. 이는 단순히 열심히 일하는 것을 넘어, 피로를 느끼지 않거나 피로에도 불구하고 꾸준히 노력을 기울이는 끈기와 헌신을 강조합니다. 주로 특정 프로젝트의 마감 기한을 맞추거나, 어려운 목표를 성취하거나, 원하는 결과를 얻기 위해 장기간 동안 집중적인 노동이나 노력을 기울이는 상황에서 사용됩니다.","examples":[{"en":"She worked tirelessly to finish her novel before the deadline.","ko":"그녀는 마감 기한 전에 소설을 끝내기 위해 지칠 줄 모르고 일했습니다."},{"en":"The team worked tirelessly to perfect the new product.","ko":"그 팀은 신제품을 완벽하게 만들기 위해 끊임없이 노력했습니다."},{"en":"He worked tirelessly throughout his career to achieve financial independence.","ko":"그는 재정적 독립을 달성하기 위해 평생 동안 지칠 줄 모르고 일했습니다."},{"en":"Despite the setbacks, they worked tirelessly to rebuild their community.","ko":"좌절에도 불구하고, 그들은 지역 사회를 재건하기 위해 끊임없이 노력했습니다."},{"en":"The volunteers worked tirelessly to help the victims of the disaster.","ko":"자원봉사자들은 재난 희생자들을 돕기 위해 지칠 줄 모르고 봉사했습니다."}],"related":[{"slug":"spare-no-effort","title":"Spare No Effort","type":"synonym","note":"어떤 일을 위해 모든 노력을 아끼지 않는다는 의미입니다."},{"slug":"toil-away","title":"Toil Away","type":"synonym","note":"힘들고 지루한 일을 오랫동안 꾸준히 하는 것을 강조합니다."},{"slug":"labor-intensively","title":"Labor Intensively","type":"synonym","note":"많은 노동력과 노력을 집중적으로 투입하는 것을 의미합니다."},{"slug":"slacken-off","title":"Slacken Off","type":"antonym","note":"일이나 노력을 게을리하거나 늦추는 것을 의미합니다."}],"date":"2026-01-24T00:00"}');
;// ./blog/stay-put/content.json
const stay_put_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"stay-put","title":"Stay Put","koreanPronunciation":"스테이 풋","tags":["구동사","자주 쓰는 표현"],"meaning":"그 자리에 머무르다, 움직이지 않다, 또는 어떤 상황이나 위치에 변함없이 남아있다...의미입니다.","description":"이 표현은 사람이나 사물이 현재 위치에서 움직이지 않고 그대로 머무르거나, 특정 장소나 상태에 변함없이 남아있음을 나타낼 때 사용됩니다. 누군가에게 움직이지 말라고 지시하거나, 어떤 것이 움직이지 않고 가만히 있다는 사실을 설명할 때 주로 쓰입니다. 비유적으로는 특정 직업이나 거주지에 계속 머무르는 상황에도 적용될 수 있습니다.","examples":[{"en":"Please stay put right there, I\'ll be back with your order in a minute.","ko":"그 자리에 그대로 있어 주세요, 주문하신 것 가지고 금방 돌아올게요."},{"en":"The old house stayed put through many storms, a testament to its strong foundation.","ko":"그 오래된 집은 여러 폭풍 속에서도 굳건히 제자리를 지켰는데, 이는 튼튼한 기초 덕분이었다."},{"en":"My doctor advised me to stay put and rest after the surgery.","ko":"의사 선생님은 수술 후에 움직이지 말고 쉬라고 충고하셨다."},{"en":"Despite the tempting job offer, she decided to stay put in her current company.","ko":"매력적인 직업 제안에도 불구하고, 그녀는 현재 회사에 머무르기로 결정했다."}],"related":[{"slug":"remain-in-place","title":"Remain In Place","type":"synonym","note":"물리적으로 제자리에 머무르거나 위치를 유지한다는 뜻으로, \'stay put\'과 유사하게 사용됩니다."},{"slug":"stand-still","title":"Stand Still","type":"synonym","note":"움직이지 않고 가만히 서 있거나 멈춰 있는 상태를 의미합니다."},{"slug":"hold-still","title":"Hold Still","type":"synonym","note":"움직이지 말고 가만히 있으라는 지시로, 사진 촬영 시나 어린이에게 사용됩니다."},{"slug":"move-on","title":"Move On","type":"antonym","note":"다른 곳으로 이동하거나 새로운 상황으로 나아가다는 의미로, \'stay put\'과 반대됩니다."}],"date":"2026-04-06T00:00"}');
;// ./blog/nearing-the-end/content.json
const nearing_the_end_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"nearing-the-end","title":"Nearing The End","koreanPronunciation":"니얼링 더 엔드","tags":["자주 쓰는 표현"],"meaning":"거의 끝나가는, 막바지에 다다른 상태를 의미합니다.","description":"이 표현은 어떤 일이나 과정, 시간, 관계, 또는 존재가 마지막 단계에 이르렀음을 나타낼 때 사용됩니다. 종결이 임박했음을 강조하며, 특정 상황의 끝이 다가오고 있음을 알리는 맥락에서 널리 쓰입니다. 긍정적, 부정적 또는 중립적인 의미로 모두 사용될 수 있습니다.","examples":[{"en":"The long negotiation process is finally nearing the end.","ko":"길었던 협상 과정이 드디어 막바지에 다다르고 있습니다."},{"en":"We are nearing the end of our supplies, so we need to ration them carefully.","ko":"우리는 비축량이 바닥나고 있으니, 신중하게 배급해야 합니다."},{"en":"As the concert was nearing the end, the crowd cheered even louder.","ko":"콘서트가 막바지에 다다르자, 관중들은 더욱 크게 환호했습니다."},{"en":"Her career is nearing the end, but she\'s still very active.","ko":"그녀의 경력은 끝을 향해 가고 있지만, 여전히 매우 활발합니다."}],"related":[{"slug":"approaching-the-end","title":"Approaching The End","type":"synonym","note":"비슷하게, 어떤 것의 끝이 다가오고 있음을 나타냅니다."},{"slug":"coming-to-a-close","title":"Coming To A Close","type":"synonym","note":"특히 행사나 기간 등이 끝나가는 상황을 표현할 때 쓰입니다."},{"slug":"on-the-verge-of-completion","title":"On The Verge Of Completion","type":"synonym","note":"특히 작업이나 프로젝트가 완료되기 직전의 상태를 강조합니다."},{"slug":"just-beginning","title":"Just Beginning","type":"antonym","note":"무언가가 이제 막 시작되었음을 의미합니다."},{"slug":"in-the-early-stages","title":"In The Early Stages","type":"antonym","note":"어떤 과정이나 프로젝트의 초기 단계에 있음을 나타냅니다."}],"date":"2026-01-21T00:01"}');
