const tough_it_out_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"tough-it-out","title":"Tough It Out","koreanPronunciation":"터프 잇 아웃","tags":["구동사","자주 쓰는 표현"],"meaning":"어렵거나 불쾌한 상황을 참고 견디는 것을 의미합니다.","description":"이 표현은 어려운 상황이나 고통을 인내심을 가지고 견뎌내어 극복하는 것을 의미합니다. 주로 불편하거나 힘들지만 피할 수 없는 상황에서 쓰이며, 쉽게 포기하지 않고 끝까지 버텨내는 강인한 정신력을 나타낼 때 사용됩니다.","examples":[{"en":"The hike was tough, but we decided to tough it out and reach the summit.","ko":"등산은 힘들었지만, 우리는 참고 끝까지 버텨서 정상에 오르기로 결정했다."},{"en":"You\'re feeling sick, but you have to tough it out for a few more hours until the meeting ends.","ko":"몸이 안 좋겠지만, 회의가 끝날 때까지 몇 시간 더 참고 견뎌야 해."},{"en":"It\'s a really challenging project, but I\'m going to tough it out and see it through.","ko":"정말 어려운 프로젝트지만, 나는 참고 끝까지 해낼 거야."},{"en":"Despite the pain, the athlete chose to tough it out and finish the race.","ko":"고통스러웠지만, 그 선수는 참고 견뎌서 경주를 끝내기로 했다."}],"related":[{"slug":"grit-ones-teeth","title":"Grit One\'s Teeth","type":"synonym","note":"신체적 고통이나 불쾌함을 참는 데 초점"},{"slug":"hang-in-there","title":"Hang In There","type":"synonym","note":"주로 어려운 상황에서 격려할 때 사용"},{"slug":"ride-out-the-storm","title":"Ride Out the Storm","type":"synonym","note":"힘든 시기를 무사히 넘기는 비유적 표현"}],"date":"2025-07-04T19:06"}');
