const build_connections_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"build-connections","title":"Build Connections","koreanPronunciation":"빌드 커넥션스","tags":["자주 쓰는 표현","연어"],"meaning":"사람들과 관계를 형성하고 유대감을 쌓는 것의 의미입니다.","description":"이 표현은 개인적 혹은 직업적으로 다른 사람들과 유대 관계를 맺고 상호 작용하는 과정을 의미합니다. 신뢰를 구축하고 공통의 관심사를 찾으며 서로를 지지하는 행동들을 포함합니다. 사회적 자본을 늘리고 협력 기회를 창출하는 데 중요하며, 지속적인 소통과 노력이 필요합니다.","examples":[{"en":"Networking events are a great way to build connections in your industry.","ko":"네트워킹 행사는 업계에서 인맥을 쌓는 좋은 방법입니다."},{"en":"As a new manager, it\'s crucial to build connections with your team members.","ko":"신임 관리자로서 팀원들과 유대 관계를 형성하는 것이 매우 중요합니다."},{"en":"Participating in volunteer work helps you build connections with people who share similar values.","ko":"자원봉사 활동에 참여하는 것은 비슷한 가치를 공유하는 사람들과 관계를 맺는 데 도움이 됩니다."},{"en":"Social media can be a useful tool to build connections, but face-to-face interactions are often more impactful.","ko":"소셜 미디어는 관계를 구축하는 데 유용한 도구가 될 수 있지만, 대면 상호작용이 종종 더 효과적입니다."}],"related":[{"slug":"network","title":"Network","type":"synonym","note":"직업적 혹은 사회적 관계망을 형성하는 행위"},{"slug":"forge-relationships","title":"Forge Relationships","type":"synonym","note":"노력하여 강하고 지속적인 관계를 만들다"},{"slug":"establish-rapport","title":"Establish Rapport","type":"synonym","note":"친밀감과 신뢰 관계를 형성하다"},{"slug":"sever-ties","title":"Sever Ties","type":"antonym","note":"관계를 완전히 끊다"},{"slug":"isolate-oneself","title":"Isolate Oneself","type":"antonym","note":"스스로 다른 사람들과 거리를 두어 고립되다"}],"date":"2026-03-23T00:00"}');
