const dig_ones_own_grave_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"dig-ones-own-grave","title":"Dig One\'s Own Grave","koreanPronunciation":"딕 원스 오운 그레이브","tags":["관용구","자주 쓰는 표현"],"meaning":"스스로 해를 끼치거나 자신의 상황을 악화시키는 행동을 하는 것을 의미합니다.","description":"이 표현은 사람이 무모하거나 어리석은 행동으로 인해 스스로에게 해를 입히거나 자신의 파멸을 초래하는 상황을 비유적으로 묘사할 때 사용됩니다. 자신의 무덤을 판다는 직설적인 이미지는 되돌릴 수 없는 해로운 결과를 낳을 행동을 강조합니다. 주로 부정적인 맥락에서 쓰이며, 누군가가 스스로의 잘못된 판단이나 행동으로 인해 궁지에 몰리거나 실패하게 될 때 이 표현을 씁니다.","examples":[{"en":"If you keep procrastinating on this project, you\'ll be digging your own grave with the deadline approaching.","ko":"이 프로젝트를 계속 미루면 마감일이 다가올 때 스스로 무덤을 파는 꼴이 될 거야."},{"en":"Her reckless spending habits are really helping her dig her own grave financially.","ko":"그녀의 무모한 지출 습관은 재정적으로 스스로 무덤을 파는 격이다."},{"en":"Ignoring customer complaints is how many businesses start to dig their own grave.","ko":"고객 불만을 무시하는 것은 많은 기업들이 스스로 무덤을 파기 시작하는 방법이다."}],"related":[{"slug":"shoot-oneself-in-the-foot","title":"Shoot Oneself in the Foot","type":"synonym","note":"스스로 어리석은 행동으로 자신을 해롭게 만드는 것."},{"slug":"sabotage-oneself","title":"Sabotage Oneself","type":"synonym","note":"스스로 자신의 계획이나 노력을 방해하는 것."},{"slug":"self-destruct","title":"Self Destruct","type":"synonym","note":"자멸하다, 스스로 파멸을 초래하다."}],"date":"2026-01-30T00:00"}');
;// ./blog/start-fresh/content.json
const start_fresh_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"start-fresh","title":"Start Fresh","koreanPronunciation":"스타트 프레시","tags":["자주 쓰는 표현"],"meaning":"새롭게 시작하거나, 이전의 실패나 어려움을 뒤로하고 새로운 마음으로 다시 시작하는 의미입니다.","description":"이 표현은 과거의 부정적인 경험이나 결과를 잊고 새로운 기회와 가능성을 향해 나아갈 때 사용됩니다. 특히 실수나 실패 이후에 다시 시작하려는 의지를 강조할 때 자주 쓰이며, 종종 환경 변화(이사, 새 직장 등)와 함께 쓰이기도 합니다.","examples":[{"en":"After the big argument, they decided to start fresh and work on their relationship.","ko":"큰 다툼 후에 그들은 새로 시작하여 관계를 개선하기로 결정했습니다."},{"en":"Let\'s put the past behind us and start fresh on this project.","ko":"과거는 잊고 이 프로젝트를 새로 시작합시다."},{"en":"Moving to a new city was her chance to start fresh.","ko":"새로운 도시로 이사 가는 것은 그녀에게 새롭게 시작할 기회였습니다."},{"en":"I made a lot of mistakes last year, but I\'m determined to start fresh this year.","ko":"작년에 많은 실수를 했지만, 올해는 새로 시작하기로 결심했습니다."}],"related":[{"slug":"turn-over-a-new-leaf","title":"Turn Over a New Leaf","type":"synonym","note":"나쁜 습관을 버리고 새롭게 시작하다는 뉘앙스가 더 강합니다."},{"slug":"make-a-new-start","title":"Make a New Start","type":"synonym"},{"slug":"begin-anew","title":"Begin Anew","type":"synonym"},{"slug":"dwell-on-the-past","title":"Dwell on the Past","type":"antonym","note":"과거의 일에 계속 얽매여 있음을 의미합니다."}],"date":"2025-09-13T00:00"}');
;// ./blog/turn-the-other-cheek/content.json
const turn_the_other_cheek_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"turn-the-other-cheek","title":"Turn The Other Cheek","koreanPronunciation":"턴 디 아더 칙","tags":["관용구","자주 쓰는 표현"],"meaning":"모욕이나 해를 입었을 때 보복하지 않고 관용을 베푸는 것을 의미합니다.","description":"이 표현은 성경에서 유래한 것으로, 누군가 한쪽 뺨을 때리면 다른 뺨마저 내주라는 예수님의 가르침에서 비롯되었습니다. 이는 고통이나 모욕에 대해 폭력으로 대응하지 않고 인내심과 관용을 보여주는 태도를 비유적으로 나타냅니다. 갈등 상황에서 화해와 평화를 지향하며 분노나 복수심을 내려놓는 행위를 강조할 때 사용됩니다.","examples":[{"en":"When his opponent insulted him, he decided to turn the other cheek and walk away.","ko":"상대방이 그를 모욕했을 때, 그는 참고 넘어가기로 하고 자리를 떠났습니다."},{"en":"Instead of fighting back, sometimes it\'s better to turn the other cheek and find a peaceful solution.","ko":"맞서 싸우기보다는, 때로는 참고 넘어가서 평화로운 해결책을 찾는 것이 더 낫습니다."},{"en":"Her philosophy in life is to always turn the other cheek, even when people are unkind.","ko":"그녀의 인생 철학은 사람들이 불친절하게 굴 때조차 항상 참고 용서하는 것입니다."},{"en":"He advised me to turn the other cheek and not let their negativity affect me.","ko":"그는 나에게 참고 넘어가서 그들의 부정적인 태도가 나에게 영향을 미치지 않게 하라고 조언했습니다."}],"related":[{"slug":"rise-above-it","title":"Rise Above It","type":"synonym","note":"갈등이나 불쾌한 상황에 휩쓸리지 않고 초연하게 대처하는 것."},{"slug":"take-the-high-road","title":"Take The High Road","type":"synonym","note":"어려운 상황에서 도덕적으로 더 올바르고 품위 있는 선택을 하는 것."},{"slug":"fight-fire-with-fire","title":"Fight Fire With Fire","type":"antonym","note":"상대방의 공격적인 행동에 똑같이 공격적으로 맞서는 것."},{"slug":"hit-back","title":"Hit Back","type":"antonym","note":"공격이나 비난에 대해 반격하거나 되갚아 주는 것."}],"date":"2026-03-19T00:00"}');
;// ./blog/patch-things-up/content.json
const patch_things_up_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"patch-things-up","title":"Patch Things Up","koreanPronunciation":"패치 띵스 업","tags":["구동사","자주 쓰는 표현"],"meaning":"틀어진 관계나 상황을 개선하거나 화해한다는 의미입니다.","description":"이 표현은 갈등, 오해, 또는 문제로 인해 손상된 관계를 회복하거나, 어려운 상황을 개선하고 바로잡을 때 사용됩니다. 주로 사람들 사이의 관계를 개선하거나 오해를 풀 때 쓰이지만, 비유적으로 어떤 문제나 상황을 해결하여 정상으로 돌려놓을 때도 사용될 수 있습니다.","examples":[{"en":"After their big argument, they decided to meet up and patch things up.","ko":"크게 다툰 후, 그들은 만나서 화해하기로 결정했다."},{"en":"I hope we can patch things up and be friends again soon.","ko":"우리가 곧 화해하고 다시 친구가 될 수 있기를 바란다."},{"en":"The company is trying to patch things up with their customers after the service disruption.","ko":"회사는 서비스 중단 이후 고객들과의 관계를 개선하려고 노력하고 있다."},{"en":"It\'s never too late to try and patch things up with your family.","ko":"가족과 관계를 회복하려 노력하기에 너무 늦은 때란 없다."},{"en":"They managed to patch things up before the trip, so everyone had a good time.","ko":"그들은 여행 전에 관계를 회복하여 모두가 즐거운 시간을 보냈다."}],"related":[{"slug":"make-up","title":"Make Up","type":"synonym","note":"싸운 뒤 화해하다는 의미의 구동사"},{"slug":"reconcile","title":"Reconcile","type":"synonym","note":"화해시키다, 조화시키다"},{"slug":"kiss-and-make-up","title":"Kiss and Make Up","type":"synonym","note":"싸운 후 화해하다는 의미의 관용구"},{"slug":"fall-out","title":"Fall Out","type":"antonym","note":"싸워서 관계가 끊어지거나 사이가 나빠지다"}],"date":"2025-11-16T00:01"}');
;// ./blog/hard-worker/content.json
const hard_worker_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"hard-worker","title":"Hard Worker","koreanPronunciation":"하드 워커","tags":["자주 쓰는 표현","연어"],"meaning":"성실하고 열심히 일하는 사람을 지칭하는 의미입니다.","description":"이 표현은 근면하고 노력을 아끼지 않는 사람을 묘사할 때 사용됩니다. 어떤 일을 맡았을 때 책임감을 가지고 끈기 있게 임하며, 목표 달성을 위해 최선을 다하는 사람에게 이 표현을 쓸 수 있습니다. 긍정적인 의미로 주로 사용되며, 직업 윤리가 강하거나 어떤 분야에서든 꾸준히 노력하는 사람을 칭찬할 때 적합합니다.","examples":[{"en":"She\'s a real hard worker, always the first one in and the last one to leave.","ko":"그녀는 정말 성실한 노력가예요, 항상 가장 먼저 출근하고 가장 늦게 퇴근해요."},{"en":"To succeed in this field, you need to be a hard worker and dedicated.","ko":"이 분야에서 성공하려면 근면하고 헌신적이어야 합니다."},{"en":"My boss appreciates hard workers who take initiative.","ko":"우리 상사는 솔선수범하는 성실한 직원들을 높이 평가합니다."},{"en":"He\'s known as a hard worker in the community, always helping out.","ko":"그는 지역 사회에서 항상 남을 돕는 성실한 사람으로 알려져 있습니다."}],"related":[{"slug":"diligent","title":"Diligent","type":"synonym"},{"slug":"industrious-person","title":"Industrious Person","type":"synonym"},{"slug":"go-getter","title":"Go-Getter","type":"synonym","note":"목표 달성을 위해 적극적으로 행동하는 사람을 강조"},{"slug":"lazy-person","title":"Lazy Person","type":"antonym"},{"slug":"slacker","title":"Slacker","type":"antonym","note":"해야 할 일을 게을리하거나 회피하는 사람을 비격식적으로 지칭"}],"date":"2026-02-01T00:02"}');
