const pack_it_in_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"pack-it-in","title":"Pack It In","koreanPronunciation":"팩 잇 인","tags":["구동사","속어","자주 쓰는 표현"],"meaning":"무언가를 중단하거나 그만둘 때, 특히 어떤 활동이나 직업을 포기할 때 사용되는 표현입니다.","description":"이 표현은 하던 일을 멈추거나 어떤 활동이나 직업을 그만두는 것을 의미합니다. 주로 비공식적인 상황에서 사용되며, 더 이상 계속할 수 없거나 하고 싶지 않을 때 자주 쓰입니다. 때로는 지치거나 좌절해서 포기하거나 은퇴하는 맥락에서도 사용될 수 있습니다.","examples":[{"en":"After years of playing, she decided to pack it in and retire from professional tennis.","ko":"몇 년간 활동한 후, 그녀는 프로 테니스 선수 생활을 그만두기로 결정했다."},{"en":"Come on, pack it in! We need to finish this by tonight.","ko":"자, 그만해! 우리 오늘 밤까지 이거 끝내야 해."},{"en":"The band decided to pack it in after their last album didn\'t sell well.","ko":"밴드는 마지막 앨범이 잘 팔리지 않자 해체하기로 결정했다."},{"en":"It\'s getting late, let\'s pack it in for the day.","ko":"늦었어, 오늘은 이만 마무리하자."}],"related":[{"slug":"knock-off","title":"Knock Off","type":"synonym","note":"주로 하루 일과를 끝낼 때 사용합니다."},{"slug":"throw-in-the-sponge","title":"Throw In The Sponge","type":"synonym","note":"패배를 인정하고 포기한다는 의미가 강합니다."},{"slug":"retire","title":"Retire","type":"synonym","note":"직업이나 활동에서 은퇴하는 것을 의미합니다."},{"slug":"press-on","title":"Press On","type":"antonym","note":"어려움에도 불구하고 계속 진행하는 것을 의미합니다."},{"slug":"push-through","title":"Push Through","type":"antonym","note":"어려운 상황을 극복하고 나아가는 것을 의미합니다."}],"date":"2025-09-12T00:00"}');
