const step_down_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"step-down","title":"Step Down","koreanPronunciation":"스텝 다운","tags":["구동사","자주 쓰는 표현"],"meaning":"(직책이나 지위에서) 물러나다, 사임하다, 퇴위하다 등의 의미입니다.","description":"이 표현은 주로 공적인 지위나 직책에서 자발적으로 또는 압력에 의해 물러나는 상황을 설명할 때 사용됩니다. 권력이나 책임 있는 자리에서 내려오는 것을 의미하며, 개인적인 결정일 수도 있고 특정 사건이나 상황으로 인해 강요될 수도 있습니다.","examples":[{"en":"The CEO was asked to step down after the company\'s poor performance.","ko":"회사 실적 부진으로 CEO는 자리에서 물러나라는 요청을 받았습니다."},{"en":"He decided to step down from his position to spend more time with his family.","ko":"그는 가족과 더 많은 시간을 보내기 위해 자신의 직책에서 물러나기로 결정했습니다."},{"en":"The president will step down at the end of his term.","ko":"대통령은 임기가 끝나면 퇴임할 것입니다."},{"en":"After years of service, the veteran senator announced his plan to step down.","ko":"수년간 봉사한 후, 베테랑 상원의원은 자신의 퇴임 계획을 발표했습니다."}],"related":[{"slug":"resign","title":"Resign","type":"synonym"},{"slug":"retire","title":"Retire","type":"synonym"},{"slug":"abdicate","title":"Abdicate","type":"synonym","note":"주로 왕이나 군주가 왕위를 포기하는 데 사용되는 격식적인 표현입니다."},{"slug":"take-office","title":"Take Office","type":"antonym","note":"공식적인 직책을 맡는다는 의미로 \'step down\'의 반대입니다."}],"date":"2025-10-27T00:00"}');
;// ./blog/praise-someone/content.json
const praise_someone_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"praise-someone","title":"Praise Someone","koreanPronunciation":"프레이즈 썸원","tags":["자주 쓰는 표현"],"meaning":"다른 사람의 좋은 점, 성취, 노력 등을 인정하고 긍정적인 말로 표현하는 것의 의미입니다","description":"이 표현은 누군가의 행동이나 특성에 대해 긍정적인 평가나 찬사를 보내는 행위를 나타냅니다. 주로 상대방의 사기를 북돋우거나, 잘한 일에 대한 격려를 표현할 때 사용됩니다. 칭찬은 개인의 자신감을 높이고 긍정적인 관계를 형성하는 데 중요한 역할을 합니다.","examples":[{"en":"It\'s important to praise your children when they do something well.","ko":"아이들이 무언가를 잘 해냈을 때 칭찬해 주는 것이 중요합니다."},{"en":"The manager always makes sure to praise his team members for their hard work.","ko":"매니저는 항상 팀원들의 노고에 대해 칭찬하는 것을 잊지 않습니다."},{"en":"Don\'t be afraid to praise someone if you genuinely appreciate their efforts.","ko":"누군가의 노력을 진심으로 높이 평가한다면 칭찬하는 것을 두려워하지 마세요."},{"en":"A little praise can go a long way in motivating people.","ko":"작은 칭찬이라도 사람들에게 동기를 부여하는 데 큰 도움이 될 수 있습니다."}],"related":[{"slug":"compliment-someone","title":"Compliment Someone","type":"synonym","note":"비슷하게 칭찬이나 찬사를 전달하는 표현입니다."},{"slug":"give-credit-where-credit-is-due","title":"Give Credit Where Credit Is Due","type":"synonym","note":"마땅히 받아야 할 사람에게 공로를 인정해 주라는 의미입니다."},{"slug":"applaud-someone","title":"Applaud Someone","type":"synonym","note":"격려하거나 칭찬의 의미로 박수를 보내는 행위입니다."},{"slug":"criticize-someone","title":"Criticize Someone","type":"antonym","note":"칭찬과 반대로 누군가의 잘못이나 단점을 지적하는 행위입니다."},{"slug":"blame-someone","title":"Blame Someone","type":"antonym","note":"누군가에게 잘못의 책임을 지우는 행위입니다."}],"date":"2025-10-31T00:01"}');
;// ./blog/wear-many-hats/content.json
const wear_many_hats_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"wear-many-hats","title":"Wear Many Hats","koreanPronunciation":"웨어 매니 햇츠","tags":["관용구","자주 쓰는 표현"],"meaning":"한 사람이 여러 가지 역할을 동시에 수행하거나 다양한 업무를 맡는다는 의미입니다","description":"이 표현은 한 개인이 다양한 직무나 책임을 맡아 처리하는 상황을 묘사할 때 사용됩니다. 특히 소규모 팀이나 스타트업에서 직원이 여러 역할을 수행하거나, 다재다능한 사람을 설명할 때 자주 쓰입니다.","examples":[{"en":"As a small business owner, she has to wear many hats, from managing finances to customer service.","ko":"소규모 사업주로서 그녀는 재정 관리부터 고객 서비스까지 여러 가지 역할을 해야 합니다."},{"en":"In our startup, everyone wears many hats to get things done quickly.","ko":"저희 스타트업에서는 모든 사람이 일을 빨리 처리하기 위해 여러 역할을 합니다."},{"en":"He\'s a true multi-tasker; he wears many hats in the office.","ko":"그는 진정한 멀티태스커입니다; 사무실에서 여러 역할을 수행합니다."},{"en":"My mom wears many hats: she\'s a full-time employee, a dedicated mother, and a talented baker.","ko":"우리 엄마는 여러 역할을 하세요: 전업 직원, 헌신적인 엄마, 그리고 재능 있는 제빵사입니다."},{"en":"The director of the play had to wear many hats, including costume designer and stage manager.","ko":"그 연극의 감독은 의상 디자이너와 무대 감독을 포함한 여러 역할을 해야 했습니다."}],"related":[{"slug":"jack-of-all-trades","title":"Jack of All Trades","type":"synonym","note":"여러 분야에 능통하지만, 특정 분야의 전문가는 아닌 사람을 의미합니다."},{"slug":"multi-tasker","title":"Multi-tasker","type":"synonym","note":"여러 가지 일을 동시에 처리할 수 있는 사람을 직접적으로 가리킵니다."},{"slug":"juggle-many-balls","title":"Juggle Many Balls","type":"synonym","note":"여러 가지 일을 동시에 처리하며 균형을 유지해야 하는 상황을 비유적으로 표현합니다."}],"date":"2025-07-09T16:29"}');
;// ./blog/wear-ones-heart-on-ones-sleeve/content.json
const wear_ones_heart_on_ones_sleeve_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"wear-ones-heart-on-ones-sleeve","title":"Wear One\'s Heart On One\'s Sleeve","koreanPronunciation":"웨어 원스 하트 온 원스 슬리브","tags":["관용구"],"meaning":"자신의 감정이나 생각을 숨기지 않고 솔직하게 드러내는 것을 의미합니다.","description":"이 표현은 중세 시대 기사들이 토너먼트에서 자신이 좋아하는 여인의 색깔이 담긴 스카프를 소매에 달고 다닌 것에서 유래했다고 알려져 있습니다. 이는 자신의 사랑을 공개적으로 표현하는 행위였으며, 오늘날에는 자신의 감정을 숨김없이 드러내는 사람을 묘사할 때 사용됩니다. 특히 슬픔, 기쁨, 분노 등 어떤 감정이든 가면을 쓰지 않고 솔직하게 표현하는 태도를 강조합니다.","examples":[{"en":"She always wears her heart on her sleeve, so you always know how she\'s feeling.","ko":"그녀는 항상 자신의 감정을 솔직하게 드러내서, 당신은 그녀가 어떻게 느끼는지 항상 알 수 있습니다."},{"en":"It\'s hard for him to hide his disappointment; he truly wears his heart on his sleeve.","ko":"그는 실망감을 숨기기 어려워합니다. 정말로 감정을 솔직하게 드러내는 편입니다."},{"en":"Don\'t wear your heart on your sleeve too much at work; some people might take advantage of it.","ko":"직장에서는 너무 감정을 드러내지 마세요. 어떤 사람들은 이를 이용할 수도 있습니다."},{"en":"He\'s an honest person; he wears his heart on his sleeve and doesn\'t play games.","ko":"그는 정직한 사람입니다. 자신의 감정을 숨기지 않고 속임수를 쓰지 않습니다."}],"related":[{"slug":"open-up","title":"Open Up","type":"synonym","note":"마음을 열고 솔직하게 이야기하다"},{"slug":"be-an-open-book","title":"Be an Open Book","type":"synonym","note":"다른 사람들이 쉽게 이해할 수 있도록 자신의 생각과 감정을 숨기지 않는 사람을 묘사"},{"slug":"bottle-up-ones-feelings","title":"Bottle Up One\'s Feelings","type":"antonym","note":"감정을 억누르다, 감정을 속에 담아두다"},{"slug":"keep-a-poker-face","title":"Keep a Poker Face","type":"antonym","note":"표정으로 속마음을 드러내지 않고 무표정한 얼굴을 유지하다"}],"date":"2025-12-02T00:01"}');
;// ./blog/take-it-easy/content.json
const take_it_easy_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"take-it-easy","title":"Take It Easy","koreanPronunciation":"테이크 잇 이지","tags":["자주 쓰는 표현","관용구"],"meaning":"편안히 쉬거나 진정하라고 말하거나, 작별 인사를 할 때 \'조심해서 잘 지내\'라는 의미입니다","description":"이 표현은 주로 상대방에게 걱정하거나 스트레스 받지 말고 편안하게 지내라고 조언할 때 사용됩니다. 또한, 작별 인사로 \'조심해서 잘 지내\'라는 의미로도 쓰이며, 흥분한 사람에게 \'진정해\'라고 말할 때도 유용합니다.","examples":[{"en":"You\'ve been working too hard. You should take it easy this weekend.","ko":"너무 열심히 일했어요. 이번 주말에는 좀 쉬어야 해요."},{"en":"Don\'t worry about the exam, just take it easy and do your best.","ko":"시험에 대해 걱정하지 마, 그냥 편안하게 최선을 다해."},{"en":"I\'m just going to take it easy tonight and watch a movie.","ko":"오늘 밤은 그냥 편히 쉬면서 영화나 볼 거예요."},{"en":"Hey, take it easy! There\'s no need to rush.","ko":"야, 진정해! 서두를 필요 없어."},{"en":"Take it easy, see you tomorrow!","ko":"조심해서 가, 내일 봐!"}],"related":[{"slug":"relax","title":"Relax","type":"synonym"},{"slug":"calm-down","title":"Calm down","type":"synonym"},{"slug":"chill-out","title":"Chill out","type":"synonym"},{"slug":"stress-out","title":"Stress out","type":"antonym","note":"지나치게 걱정하거나 스트레스를 받는다는 의미로, \'take it easy\'와 반대되는 상황입니다."},{"slug":"worry","title":"Worry","type":"antonym","note":"걱정하다는 의미로, \'take it easy\'의 \'걱정하지 마라\'는 메시지와 대조됩니다."}],"date":"2025-09-28T00:01"}');
