const drop_in_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"drop-in","title":"Drop In","koreanPronunciation":"드롭 인","tags":["구동사","자주 쓰는 표현"],"meaning":"예고 없이 잠시 방문하거나 들르는 것의 의미입니다","description":"이 표현은 보통 친구나 지인의 집, 또는 어떤 장소에 짧게, 그리고 계획 없이 방문할 때 사용됩니다. 격식을 차리지 않고 가볍게 들르는 상황을 묘사할 때 유용합니다. 예를 들어, 근처를 지나다가 잠시 들러 안부를 묻거나 커피 한 잔을 마시고 갈 때 쓸 수 있습니다.","examples":[{"en":"Feel free to drop in anytime you\'re in the neighborhood.","ko":"이 근처 오면 언제든지 편하게 들러요."},{"en":"I just thought I\'d drop in and say hello.","ko":"그냥 잠시 들러서 안부 인사를 전하고 싶었어요."},{"en":"My cousin dropped in unexpectedly last night.","ko":"사촌이 어젯밤에 예고 없이 들렀어요."},{"en":"Let\'s drop in at the new cafe on our way home.","ko":"집에 가는 길에 새로 생긴 카페에 잠시 들러보자."}],"related":[{"slug":"stop-by","title":"Stop By","type":"synonym","note":"비슷하게 잠시 들르는 것을 의미하지만, \'drop in\'보다 목적성이 약간 더 있을 수 있습니다."},{"slug":"pop-in","title":"Pop In","type":"synonym","note":"\'drop in\'과 거의 동일하게 짧고 예상치 못한 방문을 나타냅니다."},{"slug":"come-over","title":"Come Over","type":"synonym","note":"주로 누군가의 집으로 방문하는 것을 의미하며, \'drop in\'보다 약간 더 계획된 방문일 수 있습니다."}],"date":"2026-03-09T00:01"}');
;// ./blog/a-penny-for-your-thoughts/content.json
const a_penny_for_your_thoughts_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"a-penny-for-your-thoughts","title":"A Penny For Your Thoughts","koreanPronunciation":"어 페니 포 유어 쏘츠","tags":["관용구"],"meaning":"상대방이 무슨 생각을 하는지 물어볼 때 사용하는 의미입니다","description":"이 표현은 상대방이 깊은 생각에 잠겨 있거나 침묵하고 있을 때, 그 사람이 무슨 생각을 하고 있는지 궁금해서 물어볼 때 사용됩니다. 상대방의 생각을 알아내고 싶을 때 부드럽게 대화를 시작하는 방식입니다. 문자 그대로 \'생각 값으로 1페니를 주겠다\'는 뜻으로, 상대방의 생각을 가치 있게 여긴다는 뉘앙스를 담고 있습니다.","examples":[{"en":"You\'ve been quiet for a while. A penny for your thoughts?","ko":"한동안 조용하시네요. 무슨 생각하세요?"},{"en":"She seemed lost in thought, so I asked, \\"A penny for your thoughts?\\"","ko":"그녀는 생각에 잠긴 듯 보였고, 그래서 저는 \\"무슨 생각하니?\\"라고 물었습니다."},{"en":"You look like you\'re miles away. A penny for your thoughts?","ko":"생각에 잠겨 있는 것 같네요. 무슨 생각하고 계세요?"},{"en":"He just stared out the window. \\"A penny for your thoughts, John?\\" I asked.","ko":"그는 그저 창밖을 응시했어요. 제가 \\"무슨 생각해, 존?\\"하고 물었죠."}],"related":[{"slug":"what-is-on-your-mind","title":"What is on your mind?","type":"synonym","note":"직접적으로 상대방의 생각을 묻는 표현입니다."},{"slug":"what-are-you-thinking","title":"What are you thinking?","type":"synonym","note":"가장 기본적인 형태로, 현재 상대방이 무엇을 생각하는지 묻습니다."}],"date":"2025-08-22T00:00"}');
