const loyal_person_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"loyal-person","title":"A Loyal Person","koreanPronunciation":"어 로열 퍼슨","tags":["자주 쓰는 표현"],"meaning":"충성스럽고 의리가 있으며 믿을 수 있는 사람을 의미합니다.","description":"이 표현은 개인, 그룹, 혹은 대의에 대한 헌신, 신뢰, 그리고 흔들림 없는 지지를 보여주는 사람을 묘사할 때 사용됩니다. \'A Loyal Person\'은 약속을 잘 지키고, 어려움 속에서도 변치 않는 지지를 보내며, 타인의 신뢰를 저버리지 않는 특성을 가집니다. 친구, 가족, 동료, 국가 등 다양한 관계에서 중요하게 여겨지는 가치입니다.","examples":[{"en":"She\'s always been a loyal person, standing by her friends through thick and thin.","ko":"그녀는 항상 충성스러운 사람이어서, 좋든 나쁘든 친구들 곁을 지켰습니다."},{"en":"Our company values a loyal person who is dedicated to long-term goals.","ko":"저희 회사는 장기적인 목표에 헌신하는 충성스러운 사람을 높이 평가합니다."},{"en":"He proved to be a loyal person by never revealing the secret, even under pressure.","ko":"그는 압력 속에서도 비밀을 절대 누설하지 않음으로써 충성스러운 사람임을 증명했습니다."},{"en":"Finding a loyal person in a competitive environment is truly a blessing.","ko":"경쟁적인 환경에서 충성스러운 사람을 찾는 것은 정말 축복입니다."}],"related":[{"slug":"a-trustworthy-person","title":"A Trustworthy Person","type":"synonym","note":"신뢰할 수 있고 의지할 수 있는 사람을 강조합니다."},{"slug":"a-dependable-person","title":"A Dependable Person","type":"synonym","note":"일관성 있게 신뢰할 수 있고 의무를 다하는 사람을 나타냅니다."},{"slug":"a-faithful-friend","title":"A Faithful Friend","type":"synonym","note":"특히 우정 관계에서의 변함없는 충실함을 강조합니다."},{"slug":"an-unreliable-person","title":"An Unreliable Person","type":"antonym","note":"약속을 지키지 않거나 의지할 수 없는 사람을 의미합니다."},{"slug":"a-traitor","title":"A Traitor","type":"antonym","note":"자신이 속한 그룹이나 대의를 배신하는 사람을 의미합니다."}],"date":"2026-04-05T00:01"}');
;// ./blog/bite-the-dust/content.json
const bite_the_dust_content_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"bite-the-dust","title":"Bite the Dust","koreanPronunciation":"바이트 더 더스트","tags":["관용구"],"meaning":"죽거나 완전히 실패하다는 의미입니다.","description":"이 표현은 본래 전투에서 병사가 죽어 땅에 엎어지는 모습을 묘사하는 데서 유래했습니다. 현대에는 비단 죽음뿐만 아니라 사업이나 계획 등이 완전히 실패하거나 좌절되는 상황을 비유적으로 나타낼 때도 사용됩니다. 주로 부정적인 결과나 패배를 강조할 때 쓰입니다.","examples":[{"en":"The company\'s new product launch bit the dust due to poor marketing.","ko":"그 회사의 신제품 출시는 미흡한 마케팅 때문에 완전히 실패했다."},{"en":"His hopes of winning the championship bit the dust after he lost the final match.","ko":"결승전에서 패배한 후, 챔피언십 우승에 대한 그의 희망은 좌절되었다."},{"en":"Many small businesses bit the dust during the economic recession.","ko":"많은 소기업들이 경제 불황기에 도산했다."}],"related":[{"slug":"kick-the-bucket","title":"Kick The Bucket","type":"synonym","note":"비격식적인 표현으로, \'죽다\'라는 의미의 속어입니다."},{"slug":"go-down-in-flames","title":"Go Down In Flames","type":"synonym","note":"화려하게 또는 완전히 실패하다는 의미입니다."},{"slug":"meet-ones-end","title":"Meet One\'s End","type":"synonym","note":"\'죽음을 맞이하다\'라는 직접적인 표현입니다."},{"slug":"fail-spectacularly","title":"Fail Spectacularly","type":"synonym","note":"\'장렬히 실패하다\'라는 의미로, \'bite the dust\'와 유사하게 큰 실패를 나타냅니다."}],"date":"2025-07-05T17:14"}');
;// ./blog/it-never-rains-but-it-pours/content.json
